import { useState, useEffect, useRef } from "react";

const Q = [{"num":1,"text":"La definición de enfermería de Virginia Henderson, publicada por el International Council of Nurses (ICN) en 1961 es:","options":{"a":"La función específica de la enfermera es ayudar a la persona, enferma o sana, a la realización de actividades que contribuyan a la salud o a su rehabilitación e inserción (o a una muerte tranquila) que realizaría sin ayuda si tuviera la fuerza, la voluntad o los conocimientos necesarios, y a hacerlo de tal manera que la ayude a ganar la independencia lo más rápidamente posible.","b":"La enfermería es una profesión esencial del sistema de salud dedicada al cuidado integral de personas, familias y comunidades, promoviendo la salud, previniendo enfermedades y asistiendo en la recuperación, abarcando aspectos físicos, mentales y sociales desde el nacimiento hasta la muerte, con un enfoque colaborativo y centrado en las personas que intervienen en el proceso.","c":"La función específica de la enfermera es ayudar a la persona, enferma o sana, a la realización de actividades que contribuyan a la salud o a su recuperación (o a una muerte tranquila) que realizaría sin ayuda si tuviera la fuerza, la voluntad o los conocimientos necesarios, y a hacerlo de tal manera que la ayude a ganar la independencia lo más rápidamente posible.","d":"La enfermería es una profesión esencial del sistema de salud dedicada al cuidado integral de personas, familias y comunidades, promoviendo la salud, previniendo enfermedades y asistiendo en la recuperación, abarcando aspectos físicos, mentales y sociales desde el nacimiento hasta la muerte, con un enfoque colaborativo y centrado en el paciente."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":2,"text":"La teoría de Florence Nightingale se centró en el entorno, aun cuando ella en sus escritos prefirió el término alrededores. Definió y describió los conceptos de:","options":{"a":"Ventilación, calidez, luz, dieta, limpieza y ruido.","b":"Ventilación, calidez, luz, dieta, limpieza y descanso.","c":"Ventilación, humores, luz, dieta, limpieza y descanso.","d":"Ventilación, calidez, efluvios, alimentación, limpieza y ruido."},"correct":"a","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":3,"text":"La obra de Nightingale es clara y fácil de comprender. Abordo tres tipos de relaciones principales, SEÑALE LA INCORRECTA:","options":{"a":"Entorno-paciente.","b":"Enfermera-entorno.","c":"Entorno-Cuidados.","d":"Enfermera-paciente."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":4,"text":"¿Cuál de los siguientes NO es un Modelo Conceptual en enfermería?","options":{"a":"Modelo de la conservación.","b":"Modelo de promoción de la salud.","c":"Modelo del sistema conductual.","d":"Modelo de adaptación."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":5,"text":"Dorothea Orem afirmó que:","options":{"a":"El autocuidado son las actividades que las personas realizan para mantener su salud y bienestar, pero cuando estas actividades exceden la capacidad de la persona, surge una \"Disminución para mejorar la capacidad de autocuidado\" y el personal sanitario debe intervenir para suplir esa falta mediante educación y apoyo, basándose en su teoría central, el Modelo del Déficit de Autocuidado.","b":"La enfermería pertenece a la familia de los servicios sanitarios que se organizan para prestar asistencia directa a personas con necesidades legítimas de diferentes formas de atención directa por sus estados de salud o por la naturaleza de sus necesidades de asistencia sanitaria.","c":"El autocuidado son las actividades que las personas realizan para mantener su salud y bienestar, pero cuando estas actividades exceden la capacidad de la persona, surge un \"déficit de cuidado\" y el personal sanitario debe intervenir para suplir esa falta mediante educación y apoyo, basándose en la teoría del Modelo de insuficiencia de Autocuidado.","d":"La enfermería pertenece a la familia de los servicios sanitarios y sociales que se organizan para prestar asistencia directa a personas con necesidades legítimas de diferentes formas de atención directa por sus estados de salud o por la naturaleza de sus necesidades de asistencia sanitaria."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":6,"text":"¿Cuál de las siguientes teorías NO forma parte de la teoría general del déficit de autocuidado?","options":{"a":"La teoría de autocuidado.","b":"La teoría de procedimientos enfermeros.","c":"La teoría del déficit de autocuidado.","d":"La teoría del cuidado dependiente."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":7,"text":"Los requisitos de autocuidado de desarrollo (RACD) estaban separados de los requisitos de autocuidado universales en la segunda edición de Nursing: Concepts of Practice de Orem. Se identificaron tres conjuntos de RACD, señálelos:","options":{"a":"Provisión de condiciones que fomentan el desarrollo, Implicación en el autodesarrollo y Prevenir o vencer los efectos de las condiciones humanas y de las situaciones vitales que pueden afectar de manera negativa al desarrollo humano.","b":"Provisión de condiciones que fomentan el desarrollo, Implicación en la adaptación a los cambios sobrevenidos y Prevenir o vencer los efectos de las condiciones humanas y de las situaciones vitales que pueden afectar de manera negativa al desarrollo humano.","c":"Provisión de condiciones que fomentan el desarrollo, Implicación en la adaptación al entorno y Prevenir o vencer los efectos de las condiciones humanas y de las situaciones vitales que pueden afectar de manera negativa al desarrollo humano.","d":"Provisión de condiciones que fomentan el desarrollo, Implicación en el autodesarrollo y Prevenir o vencer los efectos de las condiciones de la relación entorno-paciente-enfermera y de las situaciones vitales que pueden afectar de manera negativa al desarrollo humano."},"correct":"a","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":8,"text":"¿Cuál es una característica general de los modelos conceptuales de enfermería?","options":{"a":"Establecen el significado de los fenómenos de enfermería a través del análisis, el razonamiento y la presentación lógica.","b":"Cada uno aborda los conceptos metaparadigmáticos de persona, entorno, salud y enfermería.","c":"Contribuyeron al desarrollo del conocimiento proporcionando una directriz o una base para los posteriores desarrollos.","d":"Reflejan métodos y enfoques científicos contemporáneos."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":9,"text":"¿Cuál de las siguientes teorías de enfermería se considera una Teoría de nivel medio en enfermería?","options":{"a":"Teoría de las transiciones.","b":"Teoría de la diversidad y de la universalidad de los cuidados culturales.","c":"Teoría del duelo disfuncional.","d":"Teoría bioética sinfonológica."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":10,"text":"¿Qué representación gráfica creo Florence Nightingale para representar los fallecimientos innecesarios en la Guerra de Crimea?","options":{"a":"Diagrama de Gantt.","b":"Diagrama de tela de araña.","c":"Diagrama de rosa de los vientos.","d":"Diagrama de área polar."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":11,"text":"NO es un criterio para el desarrollo del estatus de profesional de enfermería.","options":{"a":"Aplica su corpus de conocimiento en servicios prácticos cruciales para el bienestar social y humano.","b":"Aumenta constantemente el corpus de conocimiento que utiliza y mejora sus técnicas de educación y servicio mediante el uso del método científico.","c":"Atrae a individuos con cualidades intelectuales y personales que ensalzan el servicio por encima del beneficio personal y que reconocen la ocupación que han escogido como un trabajo de por vida.","d":"Funciona de manera interdependiente para formular estrategias profesionales y, por tanto, controlar la actividad profesional."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":12,"text":"Es considerada la madre de la enfermería psiquiátrica:","options":{"a":"Nancy Roper.","b":"Hildegard E. Peplau.","c":"Madeleine M. Leininger.","d":"Callista Roy."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":13,"text":"Para Sor Callista Roy, la adaptación se refiere:","options":{"a":"Al proceso de ajustar el comportamiento, estructura o funcionamiento para acomodarse a un entorno o situación cambiante, permitiendo la estabilidad y el éxito en un ambiente determinado.","b":"Al proceso y al resultado por los que las personas, que tienen la capacidad de pensar, actuar y de sentir, como individuos, son conscientes y escogen integrar el ser humano con su entorno.","c":"Al proceso de ajustar el comportamiento, estructura o funcionamiento para acomodarse a un entorno o situación estable, permitiendo la supervivencia y el éxito en un ambiente determinado.","d":"Al proceso y al resultado por los que las personas, que tienen la capacidad de pensar y de sentir, como individuos o en grupos, son conscientes y escogen integrar el ser humano con su entorno."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":14,"text":"La descripción breve de factor relacionado es:","options":{"a":"Evidencias o inferencias observables, que se agrupan como manifestaciones de diagnósticos, focalizados en problemas de promoción de la salud o síndromes.","b":"Factor antecedente que aumenta la susceptibilidad de una persona, cuidador, cuidadora, familia o comunidad a una respuesta humana indeseable.","c":"Factor antecedente que parece mostrar algún tipo de patrón de relación con la respuesta humana.","d":"Grupos de personas que comparten características socio demográficas, antecedentes de salud/familiares, estados de crecimiento/desarrollo o exposición a ciertos eventos/experiencias que hacen que todos los individuos sean susceptibles de una respuesta humana particular."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":15,"text":"¿Cuál de las siguientes, se corresponde con una etiqueta diagnóstica nueva de la edición 2024-2026 de Diagnósticos enfermeros?","options":{"a":"Deterioro de la bipedestación.","b":"Riesgo de lesión.","c":"Salud deficiente de la comunidad.","d":"Disposición para mejorar el patrón del sueño."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":16,"text":"¿Que engloba un diagnóstico enfermero?","options":{"a":"La culminación de los conocimientos disciplinares, enfermeros y el razonamiento clínico.","b":"Las observaciones realizadas y la consiguiente anotación de signos, síntomas y comportamientos específicos.","c":"La representación y codificación de las afecciones médicas que tratan.","d":"Una etiqueta derivada de los resultados de una valoración exhaustiva, basada en la comprensión de los conceptos cruciales dentro de la disciplina enfermera."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":17,"text":"¿Cuál es el dominio en el que se encuentra el diagnóstico de “Hipertermia”?","options":{"a":"Confort.","b":"Principios vitales.","c":"Seguridad/protección.","d":"Eliminación/intercambio."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":18,"text":"Una de las funciones que puede tener de la taxonomía II de NANDA I es:","options":{"a":"Identificar diagnósticos enfermeros fuera de su área de experiencia.","b":"Registrar más datos.","c":"Distinguir los datos relevantes de los irrelevantes.","d":"Puede ayudar a los profesionales sanitarios a desarrollar el currículo de formación de enfermería."},"correct":"a","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":19,"text":"La taxonomía II de NANDA-I se organiza en:","options":{"a":"13 Dominios, 47 clases y 277 diagnósticos.","b":"12 Dominios, 48 clases y 277 diagnósticos.","c":"13 Dominios, 47 clases y 277 diagnósticos.","d":"13 Dominios, 48 clases y 277 diagnósticos."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":20,"text":"¿En qué dominio “encaja” la clase 4; Función respiratoria?","options":{"a":"Actividad/reposo.","b":"Eliminación/intercambio.","c":"Principios vitales.","d":"Necesidad de respirar."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":21,"text":"La definición del diagnóstico (00030), Deterioro del intercambio de gases es:","options":{"a":"Sensación exagerada y sostenida, de agotamiento y disminución de la capacidad para el trabajo físico y mental habitual.","b":"Exceso o déficit en la oxigenación y/o eliminación de dióxido de carbono.","c":"Dificultad para mantener una ventilación adecuada durante la inspiración y/o la expiración.","d":"Incapacidad para iniciar, y o mantener la respiración, independientemente para el mantenimiento de la vida."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":22,"text":"Es un marco de valoración basado en la evidencia, recomendado según la declaración de posición de la NANDA-I.","options":{"a":"14 Necesidades básicas de Virginia Henderson.","b":"11 Patrones Funcionales de Salud.","c":"13 Dominios de la taxonomía NANDA-I.","d":"Conjunto mínimo básico de datos."},"correct":"b","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":23,"text":"Según la estructura axial de NANDA-I, en el eje 2: sujeto del cuidado, se define al “paciente” como:","options":{"a":"Individuo, cuidador principal y familia.","b":"Individuo y familia.","c":"Individuo, cuidadores y comunidad.","d":"Individuo, familia y comunidad."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":24,"text":"Señale la respuesta correcta en referencia a la obtención de datos subjetivos.","options":{"a":"Se refiere a las creencias o sentimientos que recoge la enfermera.","b":"Denotan hechos, observados por la enfermera u otros profesionales de la salud.","c":"Proceden de los informes verbales del paciente, que abarcan sus percepciones y pensamientos sobre diversos aspectos de la salud, la vida cotidiana, la comodidad, la relaciones y otros.","d":"Engloban las observaciones realizadas por las enfermeras sobre el paciente, recogidas mediante exploraciones físicas y resultados de pruebas diagnósticas."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":25,"text":"“Una configuración de conductas que se produce secuencialmente largo del tiempo”, es la definición de:","options":{"a":"Patrón de M. Gordon.","b":"Necesidades de Maslow.","c":"Necesidad de autorrealización.","d":"Niveles de adquisición de habilidades clínicas en enfermería de P. Benner."},"correct":"a","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":26,"text":"La secuencia ordenada de principio a final de los diversos componentes del Proceso Enfermero es:","options":{"a":"Valoración-Planificación-Diagnosticar -Implementar-Evaluar.","b":"Diagnosticar-Valoración -Planificación-Implementar-Evaluar.","c":"Observación-Diagnosticar-Planificación-Implementar-Evaluar.","d":"Valoración-Diagnosticar-Planificación-Implementar-Evaluar."},"correct":"d","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":27,"text":"En relación con los axiomas de la comunicación formulados por Watzlawick, señale la afirmación VERDADERA:","options":{"a":"La comunicación solo se produce cuando existe una intención consciente de transmitir un mensaje.","b":"El nivel de contenido de un mensaje es independiente del tipo de relación existente entre los interlocutores.","c":"La manera en que cada interlocutor puntúa la secuencia comunicativa influye en la naturaleza de la relación.","d":"Las interacciones complementarias se caracterizan siempre por relaciones patológicas de dependencia."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":28,"text":"En relación con la formación de la primera impresión en la comunicación interpersonal, ¿cuál de las siguientes afirmaciones es la CORRECTA?","options":{"a":"La primera impresión refleja de forma directa la intención comunicativa del emisor cuando el mensaje verbal es claro.","b":"La primera impresión depende exclusivamente de los elementos no verbales observables en el interlocutor.","c":"La primera impresión se construye a partir de la interpretación del receptor, que no siempre coincide con la intención comunicativa del emisor.","d":"La primera impresión puede controlarse completamente mediante la planificación consciente del discurso verbal."},"correct":"c","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":29,"text":"En el ámbito de la comunicación interpersonal, ¿cuál de las siguientes definiciones se corresponde CORRECTAMENTE con la distancia personal lejana?","options":{"a":"Distancia limitada aproximadamente a la extensión del brazo, que marca el límite del dominio físico y suele utilizarse en interacciones personales sin contacto íntimo.","b":"Distancia propia de conversaciones formales con grupos o audiencias, en la que el interlocutor se sitúa claramente fuera del espacio personal.","c":"Distancia caracterizada por el contacto físico frecuente y la percepción del olor y la temperatura corporal.","d":"Distancia habitual en conversaciones informales entre personas que comparten un entorno laboral y mantienen una relación cotidiana."},"correct":"a","disputed":false,"topic":"Modelos y Teorías Enfermeras"},{"num":30,"text":"En el contexto de la relación terapéutica, ¿cuál de las siguientes afirmaciones define de forma más precisa la actitud empática del profesional sanitario?","options":{"a":"Tendencia a experimentar una respuesta de lástima ante el sufrimiento del paciente, acompañada del deseo de protegerlo o aliviar su malestar.","b":"Capacidad de compartir emocionalmente el sufrimiento del paciente, viviéndolo como propio y reduciendo la distancia emocional entre ambos.","c":"Capacidad de comprender y percibir con precisión la experiencia emocional del paciente, comunicándole esa comprensión y manteniendo un límite claro entre el “yo” profesional y el “tú” del paciente.","d":"Actitud de preocupación afectiva orientada principalmente a consolar y aliviar el malestar del paciente, sin necesidad de explorar ni devolver de forma explícita su vivencia emocional."},"correct":"c","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":31,"text":"Según la escala de Carkhuff para medir el nivel de autenticidad del profesional, ¿qué característica define mejor el NIVEL 4 de autenticidad?","options":{"a":"El profesional escucha al paciente, pero evita implicarse por temor a que la relación terapéutica se deteriore.","b":"El profesional responde de forma estereotipada, no se compromete con el paciente y desconoce su estado emocional.","c":"El profesional abandona una actitud rígida, muestra empatía hacia el paciente y facilita que este hable de lo que le ocurre, comprometiéndose a ayudarle.","d":"El profesional se compromete totalmente, comunica de forma empática y anima al paciente a una revelación profunda de su yo auténtico."},"correct":"c","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":32,"text":"En la resolución de conflictos, ¿qué estilo se caracteriza por un equilibrio entre asertividad y cooperación, en el que ambas partes ceden parcialmente y ninguna obtiene plenamente lo que desea?","options":{"a":"Evitación.","b":"Compromiso.","c":"Colaboración.","d":"Acomodación."},"correct":"b","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":33,"text":"En relación con la capacidad del profesional sanitario para desconectar y no llevarse consigo los problemas de los pacientes, ¿cuál de las siguientes afirmaciones es la MÁS ajustada a una práctica profesional saludable?","options":{"a":"Implicarse plenamente en el aquí y ahora con el paciente, delimitando conscientemente el momento en que finaliza la relación asistencial para poder reorientarse a otras actividades sin culpa.","b":"Reducir la implicación emocional durante la atención para evitar el desgaste profesional, manteniendo una distancia afectiva constante con todos los pacientes.","c":"Compartir de forma habitual con familiares o personas cercanas las vivencias emocionales intensas del trabajo como principal estrategia de descarga.","d":"Evitar reflexionar sobre las situaciones vividas con los pacientes una vez finalizada la jornada laboral para impedir la aparición de malestar emocional."},"correct":"a","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":34,"text":"Una paciente expresa durante la entrevista: “Me siento muy sola últimamente. Desde que falleció mi marido no tengo ganas de salir ni de ver a nadie; creo que eso es lo que me está provocando esta tristeza constante”. Según las fases de la relación de ayuda, ¿en cuál de las siguientes se sitúa principalmente este momento del proceso?","options":{"a":"Configuración del encuentro personal: acogida y orientación.","b":"Exposición, clarificación, identificación y definición del problema.","c":"Confrontación y reestructuración del problema.","d":"Iniciación al plan de acción: definición de objetivos y planificación de actividades."},"correct":"b","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":35,"text":"Durante una sesión grupal, una profesional de enfermería recibe feedback de sus compañeras sobre un tono autoritario del que ella no era consciente y que puede estar influyendo negativamente en la comunicación con los pacientes. Según el modelo de la ventana de Johari, ¿en qué área se situaba inicialmente este aspecto de su conducta?","options":{"a":"Área abierta o libre.","b":"Área oculta.","c":"Área ciega.","d":"Área desconocida."},"correct":"c","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":36,"text":"Cuando un paciente llega agresivo a la consulta, ¿cuál es la intervención MÁS adecuada desde el punto de vista de la comunicación terapéutica?","options":{"a":"Manifestarle que nos preocupa su agresividad, explorando a qué se debe y qué cree que le ayudaría a sentirse mejor.","b":"Desde el primer momento mostrarle firmeza, estableciendo límites claros mediante mensajes directos como “no toleramos que nos grite o nos falte al respeto”.","c":"Decirle que lo atenderemos cuando se calme, interrumpiendo la interacción hasta que modifique su conducta.","d":"Responder a la agresividad con un tono igualmente firme y autoritario para recuperar el control de la situación."},"correct":"a","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":37,"text":"En el contexto de la comunicación terapéutica, el feedback se define como:","options":{"a":"Reflejar literalmente al paciente lo que nos ha dicho, sin añadir ni modificar ningún contenido.","b":"Devolver al paciente lo que hemos comprendido de su mensaje, integrando tanto el contenido como los aspectos emocionales percibidos.","c":"Interpretar el discurso del paciente desde el marco teórico del profesional para explicarle el origen de su problema.","d":"Resumir la información aportada por el paciente con el objetivo principal de agilizar la entrevista clínica."},"correct":"b","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":38,"text":"En el contexto de la relación de ayuda, el profesional que actúa como receptor eficaz es aquel que:","options":{"a":"Se comporta en todo momento de forma auténtica, priorizando la expresión de sus propias vivencias personales durante la interacción con el paciente.","b":"Sabe disimular adecuadamente las situaciones difíciles para evitar que el paciente se sienta incómodo.","c":"Sabe interpretar correctamente los mensajes verbales y no verbales del paciente, devolviéndolos de forma comprensible y ajustada.","d":"Mantiene una actitud distante y neutral para no implicarse emocionalmente en los problemas del paciente."},"correct":"c","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":39,"text":"En la fase de confrontación de la relación de ayuda, el profesional debe decidir qué aspectos confrontar para favorecer la toma de conciencia del paciente. Señale la opción FALSA:","options":{"a":"Las incongruencias entre lo que el paciente dice y lo que hace.","b":"Los mecanismos de defensa que dificultan la autoexploración","c":"La responsabilidad del paciente en la persistencia de su problema.","d":"Los rasgos de personalidad del paciente para que los modifique."},"correct":"d","disputed":false,"topic":"Comunicación y Relación Terapéutica"},{"num":40,"text":"La definición de la categoría III de las lesiones por presión, se corresponde con:","options":{"a":"La pérdida de espesor parcial de la dermis se presenta como una úlcera abierta poco profunda con un lecho de la herida rojo-rosado, sin esfacelos.","b":"El tejido subcutáneo o hipodermis puede ser visible, pero los huesos, tendones o músculos no están expuestos, pudiendo presentar cavitaciones y tunelizaciones.","c":"Pérdida del espesor total de los tejidos donde la profundidad real de la lesión por presión está completamente cubierta por esfacelos y/o escaras en el lecho de la herida.","d":"Piel intacta con enrojecimiento que no palidece al presionar en un área localizada generalmente sobre una prominencia ósea."},"correct":"b","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":41,"text":"Señale la respuesta CORRECTA relacionada con la prevención de lesiones por presión relacionadas con uso de dispositivos sanitarios.","options":{"a":"Revisa al menos 2 veces/día la piel bajo los dispositivos sanitarios.","b":"Considere usar apósitos reguladores de metaloproteasas para la prevención de lesiones cutáneas.","c":"Evite la presión directa sobre las prominencias óseas del cuerpo y aplíquela sobre dispositivos.","d":"Realice cambios posturales cada 2h."},"correct":"a","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":42,"text":"Las localizaciones más frecuentes de lesiones por presión en la posición de decúbito lateral, son:","options":{"a":"Maléolos, los trocánteres, las costillas, los hombros, las orejas, los pómulos, las crestas ilíacas y la cara interna y lateral de las rodillas.","b":"Maléolos, los trocánteres, las costillas, los hombros, las orejas, los pómulos, las mamas, las crestas ilíacas y la cara interna y lateral de las rodillas.","c":"Maléolos, los trocánteres, las costillas, los hombros, las orejas, las crestas ilíacas y la cara interna y lateral de las rodillas.","d":"Maléolos, los trocánteres, las costillas, los hombros, las orejas, los omoplatos, las crestas ilíacas y la cara interna y lateral de las rodillas."},"correct":"c","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":43,"text":"Osakidetza ha establecido consideraciones especiales, tanto para la valoración inicial como para la revaluación del riesgo de lesiones por presión. SEÑALE LA CORRECTA.","options":{"a":"En ingresos inferiores a 24h es obligatorio valorar el riesgo en las primeras 2 horas.","b":"En intervenciones quirúrgicas programadas se debe realizar la valoración pre y post cirugía.","c":"En hospitalización a domicilio, la valoración del riesgo debe realizarse en las primeras 72h tras el ingreso.","d":"Es obligatorio valorar el riesgo de lesión por presion a las mujeres que ingresan en obstetricia para parto o cesárea."},"correct":"c","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":44,"text":"En Atención Hospitalaria, la primera valoración del riesgo de lesiones por presión debe realizarse al ingreso. La frecuencia de la valoración de una persona sin riesgo, ingresada en una Unidad de Cuidados Intensivos es:","options":{"a":"c/ 7 días.","b":"Diaria.","c":"c/ 4 días.","d":"c/ 2 días."},"correct":"b","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":45,"text":"En la prevención de lesiones por presión, en las posiciones de decúbito lateral y a fin de evitar apoyar el peso sobre los trocánteres:","options":{"a":"Se recomienda sobrepasar los 30º de lateralización.","b":"No se recomienda sobrepasar los 60º de lateralización.","c":"Se recomienda sobrepasar los 60º de lateralización.","d":"No se recomienda sobrepasar los 30º de lateralización."},"correct":"d","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":46,"text":"Señale la respuesta CORRECTA relacionada con la prevención de lesiones por presión en personas que permanecen sentadas.","options":{"a":"Utilice flotadores o rodetes cuando la persona esté en sedestación.","b":"Recomiende que efectúe pulsiones cada 15 minutos. Si no se puede movilizar, se le realizarán cambios posturales al menos cada hora.","c":"Limite el tiempo que la persona pasa sentado en una silla con alivio de presión.","d":"Ponga los pies de la persona sobre una silla anexa cuando éstos no llegan a tocar el suelo."},"correct":"b","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":47,"text":"Ante una persona que presenta mayor riesgo de desarrollar lesión por presión y no sea factible realizar cambios posturales, se debe utilizar:","options":{"a":"Superficie especial de manejo de presión estática.","b":"Colchones-cojines viscoelásticos.","c":"Colchonetas-cojines estáticos de aire.","d":"Superficie especial de manejo de presión activa."},"correct":"d","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":48,"text":"En el interior de heridas, como material de relleno, ya que tienen gran capacidad de absorción de exudado, se recomienda utilizar:","options":{"a":"Alginatos e hidrofibras gelificantes.","b":"Apósitos con plata.","c":"Espuma de poliuretano como apósito secundario.","d":"a) y c) son correctas."},"correct":"a","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":49,"text":"Señale una propiedad de los Ácidos Grasos Hiperoxigenados.","options":{"a":"Forman una película transparente e impermeable a líquidos.","b":"Restablecen el film hidro-lipídico de la piel.","c":"Mejoran la hidratación de la piel, aumentando su resistencia a la humedad.","d":"Preserva el nivel de oxigenación de los tejidos de apoyo, disminuyendo la microcirculación sanguínea y evitando las lesiones por presión."},"correct":"b","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":50,"text":"Señale la afirmación CORRECTA relacionada con la prevención de lesiones por presión.","options":{"a":"Utilice dispositivos que eleven y descarguen el talón completamente de tal manera que distribuyan el peso de la pierna a lo largo del tríceps sural, presionando el talón de Aquiles.","b":"Proteja la piel del exceso de humedad con productos barrera (cremas con base de zinc o películas barrera)","c":"Utilice ácidos grasos hiperoxigenados (AGHO) hasta su absorción para hidratar a la persona en riesgo.","d":"Los apósitos recomendados para el alivio de presión son los apósitos de espuma de poliuretano."},"correct":"d","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":51,"text":"Una puntuación de 7 en la escala de Braden, corresponde con:","options":{"a":"Percepción sensorial: Muy limitada. Exposición a la Humedad: Constantemente húmeda. Actividad: Encamado. Movilidad: Completamente inmóvil. Nutrición: Probablemente inadecuada. Roce y peligro de lesiones: No existe problema aparente.","b":"Percepción sensorial: Completamente limitada. Exposición a la Humedad: Constantemente húmeda. Actividad: Encamado. Movilidad: Completamente inmóvil. Nutrición: Probablemente inadecuada. Roce y peligro de lesiones: No existe problema aparente.","c":"Percepción sensorial: Completamente limitada. Exposición a la Humedad: Constantemente húmeda. Actividad: Encamado. Movilidad: Completamente inmóvil. Nutrición: Muy pobre. Roce y peligro de lesiones: Problema.","d":"Percepción sensorial: Completamente limitada. Exposición a la Humedad: Constantemente húmeda. Actividad: Encamado. Movilidad: Completamente inmóvil. Nutrición: Probablemente inadecuada. Roce y peligro de lesiones: Problema."},"correct":"d","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":52,"text":"En la escala Resvech 2.0, ¿Cómo se define el exudado “mojado”?","options":{"a":"Hay pequeñas cantidades de líquido visibles cuando se retira el apósito; el apósito primario se encuentra muy manchado, pero no hay paso de exudado; la frecuencia de cambio del apósito resulta adecuada para el tipo de apósito.","b":"Los apósitos se encuentran saturados y hay fugas de exudado de los apósitos primario y secundario hacia las ropas o más allá; se requiere una frecuencia de cambio del apósito mucho mayor de la habitual para este tipo de apósito.","c":"El apósito primario se encuentra mojado y hay traspaso de exudado; se requiere una frecuencia de cambio del apósito mayor de la habitual para este tipo de apósito; la piel perilesional puede encontrarse macerada.","d":"Hay pequeñas cantidades de líquido visibles cuando se retira el apósito; el apósito primario puede estar ligeramente manchado; la frecuencia de cambio del apósito resulta adecuada para el tipo de apósito."},"correct":"a","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":53,"text":"En el adulto, las necesidades energéticas totales se determinan principalmente por tres compartimentos del gasto energético. ¿Cuál de las siguientes opciones NO corresponde a uno de esos compartimentos principales?","options":{"a":"Termogénesis.","b":"Índice de masa corporal.","c":"Metabolismo basal.","d":"Ejercicio físico."},"correct":"b","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":54,"text":"Durante la evaluación del estado nutricional de un paciente adulto, el profesional debe ajustar la recomendación dietética conforme a las Ingestas Nutricionales de Referencia (INR). Según la Agencia Española de Seguridad Alimentaria y Nutrición, ¿cuál de las siguientes recomendaciones se ajusta correctamente a dichas INR en población adulta?","options":{"a":"Hidratos de carbono: 45–60% del valor energético total.","b":"Proteínas: 1,2 g/kg de peso/día.","c":"Grasas: 15-20% del valor energético total.","d":"Fibra: 15 g/día."},"correct":"a","disputed":false,"topic":"Lesiones por Presión y Heridas"},{"num":55,"text":"En un paciente adulto en el que el cribado nutricional ha detectado riesgo nutricional, el profesional debe elaborar un plan de cuidados nutricionales individualizado. ¿Cuál de los siguientes aspectos NO debe incluirse obligatoriamente en dicho plan?","options":{"a":"Cálculo de requerimientos.","b":"Determinación sistemática de perfil lipídico.","c":"Función del tubo digestivo.","d":"Posibilidades de utilizar la vía oral."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":56,"text":"¿Cuál de las siguientes situaciones NO constituye una indicación para la prescripción de una dieta de textura líquida?","options":{"a":"Transición entre nutrición parenteral/sueroterapia e inicio de vía oral.","b":"Preparación para exploración gastrointestinal o cirugía intestinal.","c":"Intervención dietética avanzada en paciente con estreñimiento funcional sin otra patología digestiva.","d":"Reintroducción dietética tras mejoría de procesos digestivos agudos."},"correct":"c","disputed":false,"topic":"Nutrición y Dietética"},{"num":57,"text":"¿Cuál de las siguientes definiciones corresponde correctamente a una dieta con bajo contenido en residuo?","options":{"a":"Dieta destinada a reducir exclusivamente el aporte de sustancias vegetales no digeribles con el fin de disminuir el débito fecal.","b":"Dieta destinada a reducir la ingesta de sustancias vegetales no digeribles y no absorbibles que contribuyen a incrementar el débito fecal.","c":"Dieta dirigida a disminuir la irritación mecánica intestinal mediante la supresión de alimentos integrales, semillas y vegetales crudos.","d":"Dieta orientada a reducir el contenido intestinal endoluminal no absorbido presente en heces tras la digestión."},"correct":"d","disputed":false,"topic":"Nutrición y Dietética"},{"num":58,"text":"En el diseño de una dieta hipercalórica, es fundamental ajustar el aporte energético al gasto energético total (GET) para evitar el riesgo de sobrealimentación. ¿Cuál de las siguientes afirmaciones es correcta respecto al cálculo del GET en un paciente candidato a dieta hipercalórica?","options":{"a":"Tras estimar o medir el gasto energético en reposo el GET se obtiene aplicando un factor de estrés y un factor de actividad física.","b":"Para medir el GET, la calorimetría indirecta se considera la técnica gold standard.","c":"El GET se calcula directamente a partir del peso corporal y la edad.","d":"Las ecuaciones predictivas permiten establecer directamente el aporte calórico total sin necesidad de realizar ajustes posteriores."},"correct":"a","disputed":false,"topic":"Nutrición y Dietética"},{"num":59,"text":"¿Cuál de las siguientes afirmaciones describe de forma más adecuada el concepto actual de obesidad?","options":{"a":"La obesidad se define exclusivamente como un aumento del peso corporal debido a un balance energético positivo mantenido.","b":"La obesidad es un proceso agudo y reversible cuyo origen depende principalmente de factores psicológicos.","c":"La obesidad se explica principalmente por la epigenética, siendo un fenómeno adquirido sin participación significativa de la genética.","d":"La obesidad es una enfermedad crónica caracterizada por acumulación excesiva/anormal de tejido adiposo y disfunción del mismo."},"correct":"d","disputed":false,"topic":"Nutrición y Dietética"},{"num":60,"text":"¿Cuál de las siguientes afirmaciones es correcta respecto a la interpretación de los pliegues cutáneos en la evaluación de obesidad?","options":{"a":"Se considera obesidad si al menos un pliegue cutáneo está por encima de 4 desviación típica (DT) según edad y sexo.","b":"Se considera obesidad si al menos un pliegue cutáneo está por encima de 1 desviación típica (DT) según edad y sexo.","c":"Se considera obesidad si al menos un pliegue cutáneo está por encima de 2 desviación típica (DT) según edad y sexo.","d":"Se considera obesidad si al menos un pliegue cutáneo está por encima de 5 desviación típica (DT) según edad y sexo."},"correct":"c","disputed":false,"topic":"Nutrición y Dietética"},{"num":61,"text":"¿Cuál de las siguientes afirmaciones es correcta respecto al tipo de fibra recomendada en distintas situaciones clínicas?","options":{"a":"Dislipemia: únicamente fibra insoluble.","b":"Diabetes: principalmente fibra insoluble.","c":"Enfermedad cardiovascular: únicamente fibra insoluble.","d":"Enfermedad inflamatoria intestinal: Principalmente fibra soluble."},"correct":"d","disputed":false,"topic":"Nutrición y Dietética"},{"num":62,"text":"¿Cuál de los siguientes hallazgos en el aspirado obtenido a través de una sonda nasogástrica es más compatible con una correcta colocación en el estómago?","options":{"a":"Aspirado con pH ≤ 5, color verdoso o claro, con presencia de fragmentos de mucosidad amarillenta.","b":"Aspirado con pH entre 6 y 7, color amarillo-dorado a verde amarronado, de consistencia espesa.","c":"Aspirado con pH ≥ 6, color amarillo pálido y consistencia acuosa.","d":"Aspirado con pH 7, color verdoso y de consistencia líquida."},"correct":"a","disputed":false,"topic":"Nutrición y Dietética"},{"num":63,"text":"En relación con las diferentes vías de acceso para la nutrición enteral, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"La sonda nasogástrica puede utilizarse de forma segura durante periodos prolongados superiores a un mes.","b":"La sonda nasointestinal requiere infusión continua y no se recomienda la alimentación intermitente debido a la respuesta osmótica del intestino delgado.","c":"La yeyunostomía permite la administración de nutrición en bolos sin riesgo de intolerancia digestiva.","d":"La yeyunostomía se asocia a una menor incidencia de complicaciones gastrointestinales, como cólicos y vómitos."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":64,"text":"En relación con la administración de la nutrición parenteral total (NPT), ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Una velocidad de infusión elevada de la NPT mejora el aporte calórico y nitrogenado sin producir efectos adversos significativos.","b":"Una velocidad de infusión excesivamente rápida puede provocar diuresis hiperosmolar y, en casos graves, convulsiones, coma y muerte.","c":"Una velocidad de infusión lenta de la NPT incrementa el riesgo de sobrecarga metabólica y complicaciones neurológicas.","d":"La administración de la NPT a velocidad reducida garantiza una mejor tolerancia metabólica y un mayor aprovechamiento nutricional."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":65,"text":"En la infusión de lípidos intravenosos en un adulto, ¿cuál de las siguientes pautas de administración debe tenerse en cuenta durante el primer día de tratamiento?","options":{"a":"Administración de lípidos al 10% hasta 250 ml en 2–3 horas, con un máximo de 4 g/kg/día.","b":"Infusión de lípidos al 20% hasta 750 ml en 8 horas, con un límite de 3 g/kg/día.","c":"Administración de lípidos al 10% hasta 500 ml en 4–6 horas, con un máximo de 2,5 g/kg de peso corporal al día.","d":"Infusión de lípidos al 10% hasta 1000 ml en 10–12 horas, sin restricción según el peso corporal."},"correct":"c","disputed":false,"topic":"Nutrición y Dietética"},{"num":66,"text":"Durante la exploración física respiratoria, al realizar la auscultación pulmonar, se identifican roncus. ¿Cuál de las siguientes opciones describe correctamente sus características?","options":{"a":"Sonidos continuos, de tono bajo, producidos por la obstrucción parcial de la vía aérea.","b":"Sonidos discontinuos, de tono bajo, asociados a broncoconstricción o estrechamiento de las vías respiratorias.","c":"Sonidos continuos, de tono alto, audibles tanto en inspiración como en espiración.","d":"Sonidos discontinuos, de tono alto, audibles principalmente durante la espiración."},"correct":"a","disputed":false,"topic":"Nutrición y Dietética"},{"num":67,"text":"En pacientes con afecciones respiratorias, la oxigenoterapia se indica principalmente para aumentar la presión parcial de oxígeno arterial (PaO₂) y alcanzar valores normales para el individuo. Según la curva de disociación de la oxihemoglobina, ¿qué combinación de PaO₂ y saturación de oxígeno arterial (SaO₂) corresponde a esos rangos considerados normales?","options":{"a":"PaO₂ 55–80 mmHg y SaO₂ 88–96%.","b":"PaO₂ 70–100 mmHg y SaO₂ 90–99%.","c":"PaO₂ 60–95 mmHg y SaO₂ 80–98%.","d":"PaO₂ 50–90 mmHg y SaO₂ 85–97%."},"correct":"c","disputed":false,"topic":"Nutrición y Dietética"},{"num":68,"text":"Un paciente con insuficiencia respiratoria recibe oxigenoterapia con FiO₂ >50% durante más de 24 horas. Posteriormente comienza con clínica respiratoria progresiva. ¿Cuál de los siguientes conjuntos de signos y síntomas es más compatible con toxicidad por oxígeno con daño pulmonar?","options":{"a":"Malestar subesternal, parestesias, disnea, inquietud, fatiga, hipoxemia persistente y atelectasia alveolar.","b":"Tos productiva purulenta, leucocitosis marcada, dolor pleurítico e hiperinsuflación pulmonar bilateral.","c":"Dolor torácico opresivo, diaforesis, disnea, hipoxemia, elevación del segmento ST y bradicardia.","d":"Disnea súbita con hemoptisis, taquicardia, hipotensión, hipocapnia y signos de sobrecarga ventricular derecha en ECG."},"correct":"a","disputed":false,"topic":"Nutrición y Dietética"},{"num":69,"text":"Respecto a la mascarilla Venturi utilizada en oxigenoterapia, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Proporciona una concentración variable de oxígeno, dependiente principalmente del patrón ventilatorio (profundidad y frecuencia) del paciente.","b":"Emplea el principio de Bernoulli, generando arrastre de aire ambiental, lo que permite administrar una FiO₂ precisa y constante.","c":"Utiliza un reservorio con reinhalación parcial de CO₂, aumentando progresivamente la FiO₂ conforme se incrementa el volumen corriente.","d":"Emplea el principio de Venturi-Laplace, que crea un efecto de vacío intramascarilla para aumentar automáticamente la FiO₂ según la demanda ventilatoria del paciente."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":70,"text":"En relación con la espirometría de incentivo y las recomendaciones de enfermería para su correcta utilización, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"Se recomienda que el paciente adopte una posición semi-Fowler o erecta antes de iniciar el procedimiento.","b":"El paciente debe colocar firmemente la boquilla en la boca, inspirar a través de la boca y mantener una apnea inspiratoria de al menos 5 segundos para mantener el indicador entre las líneas.","c":"La espirometría de incentivo debe realizarse 10 respiraciones consecutivas cada hora durante las horas de vigilia; entre intentos se aconsejan varias respiraciones normales para evitar la fatiga.","d":"En el espirómetro incentivo de flujo, la esfera o pesa se eleva en función de la intensidad del aire inspirado."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":71,"text":"En relación con el drenaje postural y las recomendaciones de enfermería para su realización correcta y segura, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"Antes del drenaje postural, se recomienda que el paciente inhale broncodilatadores y mucolíticos, si están prescritos, ya que facilitan el drenaje del árbol bronquial.","b":"Se indica al paciente permanecer en cada posición aproximadamente 10–15 minutos, realizando una respiración controlada.","c":"Durante cada posición el paciente debe inspirar lentamente por la nariz y espirar despacio con los labios fruncidos, con el fin de mantener las vías respiratorias abiertas y favorecer el drenaje de secreciones.","d":"En pacientes con tos ineficaz o incapacidad para toser, el drenaje postural debe evitarse, ya que la retención de secreciones aumenta el riesgo de atelectasia."},"correct":"d","disputed":false,"topic":"Nutrición y Dietética"},{"num":72,"text":"¿Cuál de las siguientes opciones incluye complicaciones reconocidas asociadas a la traqueostomía, tanto inmediatas como a largo plazo?","options":{"a":"Rotura del tronco arterial braquiocefálico, disfagia, dilatación e isquemia laríngea y hemorragia.","b":"Broncoaspiración, infección, estenosis traqueal y embolia grasa.","c":"Desplazamiento de la sonda, neumotórax, broncoaspiración y enfisema subcutáneo o mediastínico.","d":"Desintubación accidental, daño en el nervio traqueal y fístula traqueoesofágica."},"correct":"c","disputed":false,"topic":"Nutrición y Dietética"},{"num":73,"text":"Según la clasificación clínica habitual, la neumonía puede dividirse en cuatro tipos principales. ¿Cuál de las siguientes opciones incluye correctamente dichas categorías?","options":{"a":"Neumonía lobar, bronconeumonía, neumonía intersticial y neumonía necrotizante.","b":"Neumonía bacteriana, neumonía vírica, neumonía fúngica y neumonía por aspiración.","c":"Neumonía aguda, neumonía crónica, neumonía recurrente y neumonía idiopática.","d":"Neumonía extrahospitalaria, neumonía asociada a la atención sanitaria, neumonía intrahospitalaria y neumonía asociada a ventilación mecánica."},"correct":"d","disputed":false,"topic":"Nutrición y Dietética"},{"num":74,"text":"Respecto a la clasificación anatomopatológica de la neumonía según su patrón de afectación pulmonar, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Cuando una gran parte de uno o más lóbulos está afectada, se denomina neumonía lobular; la bronconeumonía corresponde a neumonía “en placas” y es más frecuente que la neumonía lobular.","b":"La neumonía lobular corresponde a lesiones parcheadas de origen bronquial y es más frecuente que la bronconeumonía.","c":"La bronconeumonía afecta típicamente un lóbulo completo y su origen se localiza en el parénquima alveolar.","d":"La neumonía lobular y la bronconeumonía presentan la misma frecuencia, diferenciándose únicamente por la etiología (vírica frente a bacteriana)."},"correct":"a","disputed":false,"topic":"Nutrición y Dietética"},{"num":75,"text":"En relación con la tuberculosis (TB), señale la afirmación correcta:","options":{"a":"Mycobacterium tuberculosis es el principal agente causal de la TB; se trata de un bacilo acidorresistente, anaerobio y de crecimiento lento.","b":"Mycobacterium bovis y Mycobacterium avium casi nunca se relacionan con la aparición de una infección tuberculosa.","c":"La TB afecta principalmente al sistema nervioso central y raramente compromete el parénquima pulmonar.","d":"La TB no se relaciona con factores socioeconómicos."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":76,"text":"Respecto a la interpretación de la prueba de la tuberculina (PPD/Mantoux) y a la vacunación con BCG, señale la afirmación correcta:","options":{"a":"Una induración de 0–4 mm se considera siempre significativa y compatible con infección tuberculosa previa.","b":"Una induración ≥10 mm se considera relevante únicamente en pacientes VIH positivos o contactos estrechos de TB activa.","c":"Una induración ≥5 mm se considera positiva en cualquier persona con inmunidad normal, aun sin factores de riesgo.","d":"Una induración ≥5 mm puede considerarse significativa en personas de riesgo, como pacientes positivos al VIH."},"correct":"d","disputed":false,"topic":"Nutrición y Dietética"},{"num":77,"text":"En relación con las manifestaciones clínicas de la insuficiencia respiratoria aguda, señale la opción que describe correctamente la progresión clínica asociada al deterioro de la oxigenación y al avance de la hipoxemia.","options":{"a":"Los signos tempranos pueden incluir inquietud, fatiga, cefalea, disnea y taquicardia; a medida que progresa la hipoxemia aparecen confusión, letargia, taquipnea, cianosis central y diaforesis.","b":"Los signos iniciales son tos productiva, fiebre y sibilancias; conforme progresa aparece edema agudo de pulmón y shock cardiogénico.","c":"Los signos iniciales incluyen cianosis central y confusión; posteriormente aparecen cefalea, inquietud, hipertensión y fatiga.","d":"Los signos tempranos se caracterizan por bradicardia e hipotensión; conforme progresa, aparecen taquicardia y diaforesis."},"correct":"a","disputed":false,"topic":"Nutrición y Dietética"},{"num":78,"text":"En relación con la enfermedad pulmonar obstructiva crónica (EPOC), señale la afirmación que es INCORRECTA:","options":{"a":"La limitación del flujo aéreo en la EPOC es progresiva y se asocia a una respuesta inflamatoria anómala de los pulmones frente a partículas o gases nocivos.","b":"La destrucción de la pared alveolar aumenta las uniones alveolares y reduce la elasticidad pulmonar.","c":"La respuesta inflamatoria afecta tanto a vías respiratorias proximales y periféricas como al parénquima pulmonar y la vasculatura pulmonar.","d":"En las vías respiratorias proximales puede producirse incremento de células caliciformes y crecimiento de glándulas submucosas, favoreciendo hipersecreción mucosa."},"correct":"b","disputed":false,"topic":"Nutrición y Dietética"},{"num":79,"text":"En relación con la realización de un electrocardiograma (ECG) estándar de 12 derivaciones y la correcta colocación de los electrodos, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"El ECG estándar de 12 derivaciones requiere la colocación de 12 electrodos.","b":"Los electrodos de los miembros deben colocarse preferentemente sobre prominencias óseas, para asegurar una mejor conducción eléctrica y reducir el artefacto por movimiento.","c":"En un ECG de 12 derivaciones los electrodos de los miembros generan las derivaciones I, II, III, aVR, aVL y aVF.","d":"La colocación exacta de los electrodos torácicos no influye en la interpretación clínica del ECG, ya que el trazado puede corregirse automáticamente por el monitor."},"correct":"c","disputed":false,"topic":"Nutrición y Dietética"},{"num":80,"text":"Respecto a las extrasístoles auriculares, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Se caracterizan por alteración del ritmo con pausas compensatorias completas, sin cambios visibles en la morfología de la onda P, y con intervalos PP que suelen ser el doble del intervalo previo.","b":"Se observa una onda P prematura con morfología diferente, que acorta el intervalo PP y suele acompañarse de una pausa no compensatoria.","c":"Presentan ondas P negativas constantes en todas las derivaciones, con intervalo PR siempre mayor a 0,20 s y QRS ancho >0,12 s.","d":"Son exclusivas de cardiopatía estructural avanzada y no aparecen en corazones normales."},"correct":"b","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":81,"text":"En la valoración vascular de las extremidades inferiores mediante Doppler manual de onda continua, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Cuanto mayor es la frecuencia (MHz), mayor es la penetración del tejido y mejor la detección en profundidad.","b":"El Doppler de onda continua permite localizar de forma precisa el sitio de una estenosis y diferenciar sin dificultad flujo arterial del venoso.","c":"Para la exploración de extremidades inferiores se coloca al paciente en sedestación con las piernas en declive para favorecer el llenado arterial y mejorar la señal.","d":"Se aplica gel acústico y se coloca el transductor sobre la arteria a 45–60°, inclinándolo lentamente hasta identificar el flujo arterial."},"correct":"d","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":82,"text":"Respecto al Índice Tobillo-Brazo (ITB) como método de valoración de arteriopatía periférica, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"El ITB es la relación entre la presión sistólica en el tobillo y la presión sistólica en el brazo; para su cálculo se divide la presión sistólica más alta del tobillo de cada pie por la presión sistólica braquial más alta.","b":"El ITB se calcula dividiendo la presión diastólica del tobillo entre la presión sistólica braquial, y se obtiene con Doppler en ambos valores.","c":"Para determinar el ITB el paciente debe estar sentado al menos 5 minutos, y el manguito se coloca a nivel del maléolo lateral.","d":"Las presiones sistólicas del tobillo se obtienen únicamente en la arteria femoral superficial, ya que las arterias tibial posterior y dorsal del pie no son accesibles con Doppler."},"correct":"a","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":83,"text":"En relación con las úlceras venosas secundarias a insuficiencia venosa crónica, ¿cuál de las siguientes características es la más compatible con este tipo de lesión?","options":{"a":"Úlcera localizada en la región maleolar (interna o externa), generalmente grande, superficial y con exudado abundante.","b":"Úlcera pequeña, profunda y circular, localizada en la punta de los dedos o en espacios interdigitales.","c":"Lesión necrótica en la cara medial del primer dedo o lateral del quinto dedo, de bordes bien delimitados, secundaria a isquemia y presión.","d":"Úlcera distal con escaso exudado, dolor desencadenado por ejercicio y mejoría con reposo."},"correct":"a","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":84,"text":"En el manejo de enfermería del paciente con úlceras en extremidades inferiores, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"En fases iniciales puede ser necesario restringir la actividad física para favorecer la cicatrización.","b":"Se debe evitar uso de almohadillas térmicas o bolsas de agua caliente ya que aumentan la demanda tisular de oxígeno.","c":"Se recomienda una dieta rica en proteínas, vitaminas D y K, hierro y cinc, para promover la cicatrización.","d":"Si el dolor limita la actividad del paciente, pueden prescribirse analgésicos para mejorar la tolerancia funcional."},"correct":"c","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":85,"text":"Según la tabla de clasificación de la presión arterial en adultos mayores de 18 años, ¿cuál de las siguientes opciones relaciona correctamente los valores de tensión normal, prehipertensión, hipertensión etapa 1 e hipertensión etapa 2?","options":{"a":"Normal: 120–139/80–89 mmHg; Prehipertensión: <120/<80 mmHg; HTA etapa 1: ≥160 o ≥100 mmHg; HTA etapa 2: 140–159 o 90–99 mmHg.","b":"Normal: <120/<80 mmHg; Prehipertensión: 120–139 o 80–89 mmHg; HTA etapa 1: 140–159 o 90–99 mmHg; HTA etapa 2: ≥160 o ≥100 mmHg.","c":"Normal: <120/<80 mmHg; Prehipertensión: 130–149 o 85–95 mmHg; HTA etapa 1: 150–169 o 95–104 mmHg; HTA etapa 2: ≥170 o ≥110 mmHg.","d":"Normal: <130/<85 mmHg; Prehipertensión: 130–139 o 85–89 mmHg; HTA etapa 1: 140–149 o 90–94 mmHg; HTA etapa 2: ≥150 o ≥95 mmHg."},"correct":"b","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":86,"text":"En relación con los factores de riesgo asociados a hipertensión arterial (HTA), señale la opción correcta:","options":{"a":"La dislipidemia asociada a HTA se caracteriza por concentraciones elevadas de HDL y disminución de LDL.","b":"El tabaquismo es una causa directa de hipertensión arterial.","c":"La prevalencia de HTA depende fundamentalmente de factores hereditarios.","d":"La HTA se asocia frecuentemente a dislipidemia, obesidad y diabetes."},"correct":"d","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":87,"text":"En relación con la insuficiencia cardiaca, señale la afirmación INCORRECTA.","options":{"a":"La clasificación funcional de la insuficiencia cardiaca según la New York Heart Association (NYHA) valora la limitación para la actividad física en clases I–IV.","b":"La fracción de eyección (FE) ventricular normal se sitúa habitualmente entre 45– 60% del volumen ventricular.","c":"La diabetes mellitus se asocia a un mayor riesgo de desarrollar insuficiencia cardiaca.","d":"La ateroesclerosis de las arterias coronarias constituye una causa primaria de insuficiencia cardiaca."},"correct":"b","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":88,"text":"Un paciente refiere dolor torácico de aparición en reposo, acompañado de elevación reversible del segmento ST en el ECG. El cuadro se atribuye a vasoespasmo de una arteria coronaria. ¿Qué tipo de angina describe mejor esta presentación clínica?","options":{"a":"Angina estable.","b":"Angina inestable.","c":"Angina refractaria.","d":"Angina variable."},"correct":"d","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":89,"text":"En relación con la trombosis venosa profunda y los factores precipitantes implicados en el desarrollo de tromboembolismo venoso, ¿cuál de las siguientes combinaciones corresponde a la tríada de Virchow?","options":{"a":"Hipertensión arterial, hiperlipidemia y disfunción endotelial.","b":"Daño endotelial, estasis venosa y alteración de la coagulación.","c":"Disminución del gasto cardiaco, vasoconstricción venosa y agregación plaquetaria.","d":"Alteración endotelial, hipoxemia tisular y aumento de la presión intratorácica."},"correct":"b","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":90,"text":"Ante un paciente con sospecha de arritmia grave en una tira electrocardiográfica, ¿cuál es la secuencia de análisis prioritaria y correcta para identificar de forma sistemática el trastorno del ritmo?","options":{"a":"Eje eléctrico → onda T → intervalo QT.","b":"Ondas P → intervalo PR → segmento ST.","c":"Frecuencia y ritmo ventricular → QRS (duración/forma) → ondas P y relación P:QRS.","d":"Segmento ST → onda U → intervalo QT."},"correct":"c","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":91,"text":"Un paciente presenta angina de pecho y se instaura tratamiento médico. ¿Cuál de las siguientes afirmaciones describe mejor el tratamiento y objetivos terapéuticos de la angina?","options":{"a":"Los nitratos constituyen el tratamiento estándar para el alivio del dolor; el abordaje busca disminuir la demanda de oxígeno del miocardio y aumentar su suministro.","b":"El tratamiento estándar se basa exclusivamente en β-bloqueantes.","c":"La nitroglicerina es un vasodilatador potente que dilata principalmente arterias coronarias.","d":"El tratamiento farmacológico de la angina se orienta principalmente a incrementar el aporte de oxígeno al miocardio mediante vasodilatación arterial."},"correct":"a","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":92,"text":"¿Cuál es la principal acción de la colecistoquinina (CCK) en el sistema digestivo?","options":{"a":"Estimular la secreción de ácido clorhídrico y pepsinógeno.","b":"Incrementar la liberación de insulina tras comidas ricas en carbohidratos.","c":"Estimular la contracción de la vesícula biliar y la secreción de enzimas pancreáticas.","d":"Reducir la secreción de bilis y acelerar el vaciamiento gástrico."},"correct":"c","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":93,"text":"¿Cuál es el principal mecanismo celular responsable de la secreción de ácido clorhídrico por las células parietales gástricas?","options":{"a":"La difusión pasiva de protones a través de la membrana luminal.","b":"El co-transporte sodio-hidrógeno dependiente de gradiente electroquímico.","c":"La acción del intercambiador H⁺/K⁺-ATPasa en la membrana luminal.","d":"La secreción directa de ácido carbónico hacia la luz gástrica."},"correct":"c","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":94,"text":"¿Cuál de los siguientes cambios relacionados con el envejecimiento del estómago puede provocar intolerancias alimentarias y disminución en la absorción de vitamina B12?","options":{"a":"La disminución de la motilidad y del vaciamiento gástrico.","b":"La degeneración y atrofia de las superficies mucosas gástricas con disminución de la producción de ácido clorhídrico.","c":"La reducción del tono del esfínter esofágico inferior.","d":"La disminución de la secreción de moco y de la elasticidad de la pared rectal."},"correct":"b","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":95,"text":"¿Cuál de las siguientes situaciones clínicas es más coherente con un cuadro de gastritis crónica?","options":{"a":"Dolor epigástrico intenso de inicio brusco acompañado de hematemesis.","b":"Náuseas y vómitos autolimitados tras la ingesta de alimentos irritantes.","c":"Saciedad temprana, intolerancia a alimentos grasos y fatiga mantenida en el tiempo.","d":"Melena y signos de inestabilidad hemodinámica secundarios a sangrado digestivo."},"correct":"c","disputed":false,"topic":"Cardiología y Electrocardiografía"},{"num":96,"text":"En un paciente con sospecha de hemorragia digestiva alta secundaria a una úlcera péptica, ¿cuál de las siguientes manifestaciones clínicas orienta con MAYOR probabilidad a una hemorragia de pequeña cuantía pero mantenida?","options":{"a":"Hematemesis con vómitos de sangre roja brillante.","b":"Melena o heces negras y alquitranadas sin vómitos de sangre.","c":"Hipotensión brusca con taquicardia y palidez cutánea.","d":"Vómitos en “posos de café” asociados a inestabilidad hemodinámica."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":97,"text":"Según los criterios diagnósticos de Roma IV, ¿cuál es el requisito temporal mínimo para establecer el diagnóstico de estreñimiento funcional?","options":{"a":"Presencia de síntomas durante al menos 3 meses, con inicio al menos 6 meses antes del diagnóstico.","b":"Presencia de síntomas durante al menos 6 meses, con inicio en los últimos 3 meses.","c":"Presencia de síntomas continuos durante 12 meses consecutivos.","d":"Presencia de síntomas intermitentes durante al menos 6 meses."},"correct":"a","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":98,"text":"¿Cuál de las siguientes complicaciones sistémicas se asocia con MAYOR frecuencia a la colitis ulcerosa que a la enfermedad de Crohn?","options":{"a":"Obstrucción del intestino delgado.","b":"Megacolon tóxico.","c":"Colelitiasis.","d":"Hidronefrosis derecha."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":99,"text":"En pacientes con disfunción hepática crónica, ¿cuál es la causa MÁS directamente relacionada con la aparición de hipoprotrombinemia y tendencia hemorrágica?","options":{"a":"Deficiencia de vitamina C.","b":"Deficiencia de vitamina K.","c":"Deficiencia de vitamina B₁ (tiamina).","d":"Deficiencia de vitamina A."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":100,"text":"En un paciente con cirrosis alcohólica y tendencia a la retención de líquidos, ¿cuál es el objetivo principal del asesoramiento enfermero para identificar y evitar el consumo habitual de alimentos en conserva?","options":{"a":"Reducir la ingesta de proteínas para prevenir la encefalopatía hepática.","b":"Disminuir el aporte de sodio y prevenir el empeoramiento del edema y la ascitis.","c":"Evitar la absorción de grasas saturadas y colesterol.","d":"Prevenir déficits de vitaminas hidrosolubles."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":101,"text":"En relación con la fisiopatología de la pancreatitis aguda, señale la afirmación FALSA:","options":{"a":"La activación intrapancreática de enzimas digestivas contribuye al daño tisular local y a la respuesta inflamatoria inicial.","b":"La liberación de mediadores inflamatorios desde el páncreas puede participar en el desarrollo de alteraciones sistémicas y fallo multiorgánico.","c":"En la pancreatitis aguda asociada a litiasis biliar, la obstrucción del sistema de conductos pancreáticos puede favorecer la activación enzimática.","d":"La necrosis pancreática constituye un requisito fisiopatológico previo para que se inicie la activación de las enzimas digestivas."},"correct":"d","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":102,"text":"Tras la inserción de una sonda nasogástrica destinada a aspiración gástrica en un paciente adulto, ¿cuál de las siguientes actuaciones es la opción VERDADERA para identificar de forma correcta su colocación antes de utilizarla?","options":{"a":"Insuflar aire con una jeringa y auscultar el epigastrio en busca de borborigmos, como se ha hecho tradicionalmente.","b":"Comprobar que el paciente no presenta tos, disnea ni cambios en la saturación de oxígeno tras la inserción.","c":"Aspirar contenido a través de la sonda y valorar sus características junto con la medición del pH.","d":"Verificar que la longitud externa de la sonda coincide con la medida estimada previamente."},"correct":"c","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":103,"text":"En un paciente portador de una ileostomía reciente, ¿cuál es la recomendación dietética CORRECTA durante las primeras cuatro semanas tras la cirugía para reducir el riesgo de obstrucción intestinal?","options":{"a":"Priorizar el consumo de frutas y verduras crudas bien masticadas desde el inicio para favorecer la motilidad intestinal.","b":"Consumir frutas y verduras en puré y seguir una dieta baja en residuos.","c":"Mantener una dieta sin restricciones específicas siempre que no aparezcan molestias abdominales.","d":"Introducir los alimentos ricos en fibra junto con un aumento de la ingesta hídrica."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":104,"text":"Un paciente con resección extensa del duodeno presenta cansancio progresivo, palidez cutáneo-mucosa y glositis. ¿Qué alteración nutricional explica mejor este cuadro clínico?","options":{"a":"Déficit de vitamina B₁₂ por alteración de la absorción ileal.","b":"Déficit de hierro por alteración de su absorción intestinal.","c":"Déficit de vitamina D con alteración del metabolismo óseo.","d":"Déficit de ácido fólico secundario a malabsorción yeyunal distal."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":105,"text":"¿Cuál de los siguientes medicamentos puede alterar los resultados de una prueba tiroidea?","options":{"a":"Amoxicilina.","b":"Amiodarona.","c":"Paracetamol.","d":"Metformina."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":106,"text":"En relación con el metabolismo basal disminuido en el hipotiroidismo, ¿cuál de las siguientes combinaciones de signos clínicos es más coherente con el estado metabólico de estos pacientes?","options":{"a":"Pérdida de peso con aumento del apetito.","b":"Pérdida rápida de masa muscular con hiperreflexia generalizada.","c":"Bradicardia, gasto cardiaco disminuido y fatiga fácil al esfuerzo mínimo.","d":"Aumento del consumo de oxígeno en reposo y disnea por aumento del trabajo respiratorio."},"correct":"c","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":107,"text":"¿Cuál de los siguientes valores cumple criterios diagnósticos de diabetes mellitus en una persona asintomática, siempre que se confirme en una segunda determinación?","options":{"a":"Glucemia plasmática en ayunas de 110 mg/dl tras 6 horas de ayuno.","b":"Hemoglobina A1c del 6,6 %.","c":"Glucemia plasmática a las 2 horas de una Prueba de Tolerncia Oral de la Glucosa de 180 mg/dl.","d":"Glucemia plasmática aleatoria de 180 mg/dl sin síntomas."},"correct":"b","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":108,"text":"En las dietas para personas con diabetes mellitus, ¿cuál es el límite de calorías procedentes de grasas saturadas?","options":{"a":"Menos del 10 % de las calorías totales.","b":"Menos del 20 % de las calorías totales.","c":"Hasta el 30 % de las calorías totales.","d":"No existe un límite específico si se controla el colesterol total."},"correct":"a","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":109,"text":"En relación con la fibra dietética en personas con diabetes mellitus, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La fibra soluble acelera el vaciamiento gástrico y la absorción de la glucosa.","b":"El aumento de la fibra dietética incrementa la necesidad de insulina exógena.","c":"La relevancia clínica de la fibra dietética en el control glucémico es insignificante.","d":"Se recomienda una ingesta diaria mínima de 25 g de fibra."},"correct":"d","disputed":false,"topic":"Gastroenterología y Aparato Digestivo"},{"num":110,"text":"¿Cuál de las siguientes insulinas se caracteriza por un inicio de acción de 10– 15 minutos, un pico máximo aproximado de 1 hora y una duración de 2 a 4 horas?","options":{"a":"Insulina lispro.","b":"Insulina regular.","c":"Insulina NPH.","d":"Insulina glargina."},"correct":"a","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":111,"text":"¿Cuál de las siguientes características corresponde al fenómeno del alba como causa de hiperglucemia matutina?","options":{"a":"Hipoglucemia nocturna seguida de hiperglucemia de rebote al despertar.","b":"Glucemia normal hasta aproximadamente las 3:00 a. m., con aumento posterior.","c":"Incremento progresivo de la glucemia desde la hora de acostarse hasta las primeras horas de la mañana.","d":"Descenso de la glucemia nocturna por exceso de insulina vespertina."},"correct":"b","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":112,"text":"Paciente con diabetes mellitus tipo 2 presenta glucemias en ayunas dentro de objetivos, pero picos repetidos de hiperglucemia posprandial tras las comidas. ¿Qué grupo farmacológico sería el más adecuado para actuar sobre este mecanismo?","options":{"a":"Biguanidas.","b":"Tiazolidinedionas.","c":"Inhibidores de la α-glucosidasa.","d":"Secretagogos de insulina."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":113,"text":"Paciente de 72 años con diabetes mellitus tipo 2 tratado con insulina NPH por la tarde acude a urgencias tras presentar desorientación y dificultad para despertar durante la madrugada. A su llegada, la glucemia capilar es de 38 mg/dL. En relación con este caso, ¿cuál de las siguientes afirmaciones es VERDADERA?","options":{"a":"El cuadro clínico es compatible con hipoglucemia moderada, que puede tratarse exclusivamente con hidratos de carbono por vía oral.","b":"La causa más probable es el fenómeno del alba, caracterizado por hiperglucemia progresiva desde las 3:00 a. m.","c":"En este contexto, está indicada la administración de glucagón por vía intramuscular si el paciente no puede deglutir.","d":"Una vez corregida la glucemia y recuperado el nivel de conciencia, no es necesaria vigilancia posterior si el paciente se encuentra estable."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":114,"text":"Paciente de 24 años con diabetes mellitus tipo 1 acude a urgencias por vómitos, dolor abdominal y respiración profunda y rápida. Presenta poliuria, polidipsia y aliento afrutado. La glucemia capilar es de 520 mg/dL y el pH arterial es de 7,18. En relación con este cuadro clínico, ¿cuál de las siguientes afirmaciones es VERDADERA?","options":{"a":"La cetoacidosis diabética se produce por un exceso de insulina que favorece la hipoglucemia y la alcalosis metabólica.","b":"En la cetoacidosis diabética, la administración de bicarbonato intravenoso es una medida de primera línea para corregir la acidosis metabólica","c":"La respiración de Kussmaul representa un mecanismo compensador frente a la acidosis metabólica producida por la acumulación de cuerpos cetónicos.","d":"Este cuadro clínico es más compatible con un síndrome hiperosmolar hiperglucémico, caracterizado por ausencia de acidosis y de cuerpos cetónicos."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":115,"text":"En relación con las intervenciones de enfermería en el síndrome hiperosmolar hiperglucémico, ¿cuál de las siguientes intervenciones NO es correcta?","options":{"a":"Vigilar de forma estrecha el estado hídrico y el gasto urinario debido al alto riesgo de deshidratación grave.","b":"Administrar líquidos intravenosos y ajustar su composición según las cifras de sodio y la gravedad de la pérdida de volumen.","c":"Priorizar la corrección rápida de la hiperglucemia mediante insulina intravenosa para revertir la acidosis metabólica.","d":"Monitorizar con frecuencia los electrolitos séricos y el estado cardiovascular durante el tratamiento."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":116,"text":"En la valoración y prevención del pie diabético en personas con diabetes, ¿cuál de las siguientes intervenciones es CORRECTA?","options":{"a":"Realizar una exploración completa de los pies al menos una vez al año, incluyendo la valoración de la sensibilidad protectora.","b":"Limitar la exploración del pie a los pacientes que refieren dolor o molestias.","c":"Utilizar el monofilamento de Semmes-Weinstein únicamente en presencia de úlceras visibles.","d":"Recomendar el corte curvo de las uñas para evitar la presión sobre el lecho ungueal."},"correct":"a","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":117,"text":"Paciente de 68 años con diabetes mellitus tipo 2 desde hace 12 años acude a consulta de enfermería. No presenta lesiones visibles en los pies. En la exploración, no percibe el estímulo del monofilamento en zonas plantares de apoyo y se observan callosidades. Pulsos periféricos palpables. En relación con este caso, ¿cuál de las siguientes actuaciones es la más adecuada?","options":{"a":"Clasificar al paciente como de bajo riesgo al no presentar úlceras ni signos de infección activa.","b":"Mantener una revisión anual del pie, sin aumentar la frecuencia, al conservar la integridad cutánea.","c":"Derivar al podólogo para el abordaje de las zonas de presión y prevenir la aparición de úlceras.","d":"Iniciar tratamiento antibiótico profiláctico para evitar la infección de las callosidades."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":118,"text":"En relación con la regulación del flujo sanguíneo cerebral, ¿cuál de las siguientes afirmaciones es FALSA?","options":{"a":"La autorregulación cerebral permite mantener un flujo sanguíneo cerebral relativamente constante pese a variaciones de la presión arterial sistémica.","b":"El flujo sanguíneo cerebral regional puede variar de forma importante en respuesta a cambios metabólicos locales.","c":"El aumento de la presión parcial de dióxido de carbono en sangre produce vasodilatación cerebral y aumento del flujo sanguíneo cerebral.","d":"Cuando la presión arterial media desciende por debajo del límite inferior de autorregulación, el flujo sanguíneo cerebral pasa a depender principalmente de los mecanismos metabólicos locales."},"correct":"d","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":119,"text":"Paciente de 70 años es trasladado a urgencias tras un inicio brusco de síntomas neurológicos. La tomografía computarizada craneal confirma un ictus hemorrágico. En relación con este diagnóstico, ¿cuál de los siguientes signos o síntomas NO se corresponde habitualmente con un ictus hemorrágico?","options":{"a":"Deterioro progresivo del nivel de conciencia.","b":"Vómitos secundarios al aumento de la presión intracraneal","c":"Cefalea intensa de inicio súbito.","d":"Hipotensión arterial mantenida."},"correct":"d","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":120,"text":"En relación con la cascada isquémica que se produce en el ictus cerebrovascular isquémico, ¿cuál de las siguientes afirmaciones es FALSA?","options":{"a":"La disminución del flujo sanguíneo cerebral obliga a las neuronas a recurrir a la respiración anaerobia, con producción de ácido láctico y descenso del pH.","b":"El fallo en la producción de ATP provoca alteraciones en las bombas de membrana y desequilibrio iónico celular.","c":"La penumbra isquémica corresponde a una zona de tejido cerebral irrecuperable que evoluciona inevitablemente a necrosis.","d":"El aumento del calcio intracelular y la liberación de glutamato activan vías que conducen a la lesión y muerte celular."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":121,"text":"En el contexto de un ictus, pueden verse afectadas diversas funciones cerebrales. ¿Cuál de las siguientes definiciones es CORRECTA?","options":{"a":"Hemiparesia: Parálisis completa de la cara, el brazo y la pierna en un mismo lado del cuerpo (por una lesión en el hemisferio contrario)","b":"Disartria: alteración del lenguaje que impide comprender o expresar palabras.","c":"Apraxia: pérdida de la coordinación y del equilibrio que se manifiesta como marcha inestable y movimientos imprecisos.","d":"Hemianopsia homónima: pérdida de la misma mitad del campo visual (derecha/izquierda) en ambos ojos."},"correct":"d","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":122,"text":"En relación con el envejecimiento cognitivo normal, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"Con la edad, la memoria a corto plazo se deteriora de forma marcada incluso cuando no se exige una alta demanda de procesamiento.","b":"Las personas mayores muestran un deterioro similar en tareas de recuerdo libre y en tareas de reconocimiento.","c":"El envejecimiento cognitivo normal se asocia a una mayor afectación de los procesos de recuperación de la información que de los procesos de codificación.","d":"El envejecimiento cognitivo normal implica una pérdida generalizada de la capacidad intelectual y del funcionamiento cognitivo global."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":123,"text":"En relación con los principales síndromes de demencia progresiva, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La enfermedad de Alzheimer se caracteriza por una atrofia cortical predominante en los lóbulos parietal y temporal.","b":"La demencia frontotemporal se manifiesta inicialmente por un deterioro predominante de la memoria episódica, similar al observado en la enfermedad de Alzheimer.","c":"La demencia vascular cursa de forma uniforme y progresiva, sin relación con eventos cerebrovasculares focales.","d":"La demencia con cuerpos de Lewy se asocia a la acumulación predominante de amiloide β como principal mecanismo fisiopatológico."},"correct":"a","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":124,"text":"En la valoración neurológica de un paciente con sospecha de ictus, se emplean distintas escalas clínicas. ¿Cuál de los siguientes ítems forma parte de la Escala NIHSS?","options":{"a":"Respuesta motora a estímulos dolorosos.","b":"Nivel de independencia funcional para las actividades básicas de la vida diaria.","c":"Evaluación de la desviación de la mirada conjugada.","d":"Valoración de la orientación temporal y espacial mediante preguntas estructuradas."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":125,"text":"En relación con las crisis convulsivas, la epilepsia y el estado epiléptico, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"El estado epiléptico puede incluir convulsiones clínicas o eléctricas continuas que persisten durante al menos 30 minutos, incluso sin recuperación completa del estado de conciencia entre episodios.","b":"La epilepsia se diagnostica cuando una convulsión generalizada se acompaña de alteración del estado de conciencia y actividad motora bilateral.","c":"Las convulsiones generalizadas se originan de forma característica en un hemisferio cerebral y posteriormente se propagan al resto del encéfalo.","d":"Las convulsiones secundarias a causas metabólicas agudas se clasifican como epilepsia cuando se repiten durante un mismo episodio clínico."},"correct":"a","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":126,"text":"Durante la exploración neurológica, una enfermera solicita al paciente que cierre los ojos con fuerza, muestre los dientes y eleve las cejas para valorar la simetría facial. ¿Qué nervio craneal se está explorando?","options":{"a":"V par craneal.","b":"VII par craneal.","c":"III par craneal.","d":"XI par craneal."},"correct":"b","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":127,"text":"Una mujer de 32 años, diagnosticada de esclerosis múltiple hace 8 años, presentó inicialmente episodios de visión borrosa y debilidad en extremidades con recuperación casi completa tras cada brote. Desde hace aproximadamente 2 años, refiere un empeoramiento neurológico progresivo y continuo, con aumento de la dificultad para la marcha y la fatiga, independientemente de la aparición de nuevos brotes. Según esta evolución clínica, ¿cuál es el tipo de esclerosis múltiple más probable?","options":{"a":"Esclerosis múltiple progresiva primaria.","b":"Esclerosis múltiple remitente-recurrente.","c":"Esclerosis múltiple progresiva secundaria.","d":"Esclerosis múltiple progresiva recurrente."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":128,"text":"Un paciente de 72 años consulta en urgencias por cefalea de inicio reciente, localizada en la región temporal derecha, acompañada de fatiga generalizada y pérdida de peso no intencionada. Refiere dolor al masticar y presenta hipersensibilidad al palpar la arteria temporal. Desde la perspectiva de la valoración enfermera, ¿cuál de las siguientes interpretaciones es la MÁS adecuada?","options":{"a":"Cefalea primaria de tipo tensional.","b":"Migraña con aura.","c":"Cefalea secundaria compatible con arteritis craneal.","d":"Cefalea trigémino-autonómica."},"correct":"c","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":129,"text":"Un varón de 79 años, previamente autónomo para las actividades básicas, ingresa por una fractura de cadera tras una caída. A las 48 horas del ingreso comienza a presentar desorientación intermitente, dificultad para mantener la atención durante la entrevista y alternancia entre periodos de somnolencia y agitación, especialmente por la noche. En algunos momentos responde de forma coherente y en otros no reconoce el lugar ni la fecha. No constan antecedentes de deterioro cognitivo previo. Desde la perspectiva de la valoración enfermera, ¿ante cuál de las siguientes situaciones clínicas es MÁS probable que nos encontremos?","options":{"a":"Demencia tipo Alzheimer en fase inicial.","b":"Demencia vascular.","c":"Envejecimiento cognitivo normal, con alteraciones leves de la memoria sin afectación de la atención.","d":"Delírium."},"correct":"d","disputed":false,"topic":"Endocrinología y Diabetes"},{"num":130,"text":"Durante la valoración neurológica de un paciente ingresado por traumatismo craneoencefálico, la enfermera aplica la escala de coma de Glasgow. Respecto a esta escala, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La escala de coma de Glasgow evalúa exclusivamente el nivel de conciencia mediante la valoración de las pupilas, la respuesta verbal y motora.","b":"La mejor respuesta motora tiene un rango de puntuación de \"1\" a \"6\", siendo “obedece órdenes” la puntuación más alta.","c":"Una puntuación total de \"0\" indica un estado de coma profundo con ausencia de respuesta a estímulos.","d":"La escala de coma de Glasgow incluye la valoración de reflejos del tronco encefálico como parte de su puntuación total."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":131,"text":"En relación con los cuidados de enfermería y las recomendaciones al paciente tras la colocación de una escayola de yeso húmeda, señale la opción INCORRECTA:","options":{"a":"Debe evitarse la carga de peso sobre la escayola hasta que esté completamente seca, lo cual suele ocurrir en un período aproximado de 48–72 horas.","b":"Se debe informar al paciente de que, durante el proceso de fraguado y secado del yeso, puede experimentar sensación de calor local.","c":"Se recomienda el empleo de medios artificiales (por ejemplo, secador de pelo o aire caliente) para acelerar el secado del yeso y prevenir deformidades.","d":"Tras su colocación, la extremidad debe mantenerse elevada por encima del nivel del corazón, apoyando la escayola sobre almohadas para favorecer el retorno venoso."},"correct":"c","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":132,"text":"En un paciente con fractura de cadera a la espera de intervención quirúrgica, ¿qué tipo de tracción se utiliza clásicamente como medida temporal para alineación e inmovilización del miembro afectado?","options":{"a":"Tracción de Dunlop.","b":"Tracción tipo Russell.","c":"Tracción de Bryant.","d":"Tracción de Buck."},"correct":"d","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":133,"text":"En el contexto de un paciente adulto con fractura abierta de tibia tratada mediante fijación externa, durante la valoración de enfermería se observa secreción en la zona de inserción de las agujas del fijador. En relación con los cuidados de enfermería y el mantenimiento del aparato de fijación externa, especialmente en los puntos de entrada de las agujas, señale la afirmación correcta:","options":{"a":"La presencia de drenaje graso en el trayecto de la aguja debe interpretarse siempre como un signo de infección activa y requiere antibioterapia inmediata.","b":"El drenaje graso que puede observarse en la superficie de contacto entre el fijador y el tejido adiposo, especialmente con el movimiento del tejido alrededor de la aguja, no debe confundirse con exudado purulento.","c":"La aparición de cualquier tipo de exudado en la zona de inserción de las agujas es indicación absoluta de retirada inmediata del aparato de fijación externa.","d":"La presencia de exudado en la zona de inserción de las agujas indica siempre una complicación infecciosa, por lo que está indicado realizar curas con antisépticos varias veces al día."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":134,"text":"En relación con la movilización y posicionamiento del paciente en el postoperatorio inmediato tras una artroplastia total de rodilla, señale la afirmación correcta:","options":{"a":"Se debe ayudar al paciente a adoptar una posición cómoda, pudiendo realizar cambios posturales y ajustar la cabecera de la cama, ya que el riesgo de desplazamiento de la prótesis es bajo.","b":"El dispositivo de movimiento pasivo continuo (CPM) debe iniciarse de forma estándar a 60º y aumentar rápidamente hasta alcanzar 120º de flexión en las primeras 48 horas.","c":"Para facilitar la adaptación al CPM, se recomienda mantener la rodilla en flexión mantenida con una almohada bajo la articulación entre sesiones.","d":"El CPM debe iniciarse únicamente cuando se retire el drenaje y el paciente presente control completo del dolor sin analgesia pautada."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":135,"text":"En relación con la clasificación de los esguinces según el grado de lesión ligamentosa, señale la afirmación correcta:","options":{"a":"El esguince de primer grado se caracteriza por el desgarro de algunas fibras del ligamento y la posible aparición de un hematoma leve y localizado, acompañado de dolor leve y edema.","b":"El esguince de primer grado implica un desgarro parcial del ligamento y se asocia típicamente a inestabilidad articular y pérdida parcial de la función.","c":"El esguince de segundo grado se produce cuando existe rotura completa del ligamento, con dolor intenso, edema máximo y movimiento articular anómalo.","d":"El esguince de tercer grado se caracteriza por la distensión leve del ligamento, con edema mínimo y ausencia de limitación funcional significativa."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":136,"text":"En relación con el acrónimo PRICE, utilizado en el abordaje inicial de lesiones musculoesqueléticas agudas (p. ej., esguinces), ¿cuál de las siguientes opciones indica correctamente el significado de sus letras?","options":{"a":"Protección – Reposicionamiento – Inmovilización – Compresión – Ejercicio.","b":"Protección – Reposo – Ice (hielo) – Compresión – Elevación.","c":"Prevención – Rehabilitación – Inmovilización – Control del dolor – Elevación.","d":"Protección – Reducción de la inflamación – Inmovilización – Compresión – Estiramientos."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":137,"text":"En relación con la osteoporosis y sus manifestaciones clínicas, señale la afirmación INCORRECTA:","options":{"a":"La osteoporosis se caracteriza por la disminución de la masa ósea, deterioro de la matriz y reducción de la fortaleza arquitectónica del hueso.","b":"En la osteoporosis el recambio óseo se altera, de modo que la resorción ósea mantenida por los osteoblastos es mayor que la formación ósea llevada a cabo por los osteoclastos, produciendo una menor masa ósea total.","c":"Como consecuencia, los huesos se tornan progresivamente más porosos, quebradizos y frágiles, pudiendo fracturarse ante esfuerzos que no afectarían a un hueso normal.","d":"Las fracturas por fragilidad asociadas a osteoporosis afectan con frecuencia a la columna torácica y lumbar, cadera y muñeca, pudiendo constituir la primera manifestación clínica."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":138,"text":"En relación con los factores de riesgo para el desarrollo de osteoporosis, señale la afirmación INCORRECTA:","options":{"a":"Índice de masa corporal alto.","b":"Alteraciones de malabsorción (p. ej., enfermedad celíaca o cirugía bariátrica).","c":"Tratamiento con corticoesteroides sistémicos durante más de 3 meses.","d":"Hombres mayores de 60 años."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":139,"text":"Respecto al vendaje compresivo para reducción y modelado del muñón tras una amputación de extremidad inferior, señale la afirmación INCORRECTA:","options":{"a":"Tras el lavado con agua y jabón, conviene asegurar un secado completo antes de vendar.","b":"El objetivo es favorecer un muñón cónico, especialmente en amputación por encima de la rodilla.","c":"El vendaje debe generar un gradiente de presión, siendo mayor en el extremo distal.","d":"La venda debe aplicarse con vueltas circulares horizontales, evitando los recorridos diagonales, para asegurar una presión uniforme."},"correct":"d","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":140,"text":"En relación con la clasificación de las fracturas abiertas, señale la afirmación correcta:","options":{"a":"El tipo II se caracteriza por una herida grande con avulsión extensa y riesgo elevado de amputación traumática.","b":"El tipo I corresponde a una herida contaminada de más de 1 cm y con daño extenso de tejidos blandos.","c":"El tipo III se asocia a herida muy contaminada y extenso daño de tejidos blandos.","d":"El tipo I se define por una herida limpia de más de 2 cm y sin afectación de tejidos blandos."},"correct":"c","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":141,"text":"En relación con la artritis reumatoide, señale la afirmación correcta:","options":{"a":"Afecta con mayor frecuencia a hombres.","b":"Se asocia a predisposición genética y respuesta inmune mediada por células T.","c":"La inflamación sinovial no suele producir alteración estructural articular relevante.","d":"Se caracteriza por disminución de citocinas y ausencia de autoanticuerpos."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":142,"text":"Ante un paciente con artritis reumatoide, ¿cuál de estos síntomas podría encontrar?","options":{"a":"Inicio brusco con fiebre alta.","b":"Fatiga, pérdida de peso y rigidez generalizada.","c":"Dolor localizado sin rigidez y con síntomas sistémicos.","d":"Episodios autolimitados sin exacerbaciones ni remisiones."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":143,"text":"Según las directrices de la Organización Mundial de la Salud sobre osteoporosis, ¿en cuál de las siguientes situaciones se recomienda iniciar tratamiento en mujeres posmenopáusicas y hombres >50 años?","options":{"a":"Fractura previa de cadera o vértebra.","b":"Probabilidad mayor del 30% de una fractura importante relacionada con osteoporosis a 10 años.","c":"Probabilidad de fractura de cadera a 10 años mayor del 1%.","d":"T-score entre −1,5 y −3,5 y con antecedente familiar de osteoporosis."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":144,"text":"Nos encontramos ante una gestante de 28 semanas que presenta cifras de hematocrito discretamente disminuidas respecto a valores pregestacionales. Este dato se explica primordialmente por:","options":{"a":"Aumento desproporcionado del volumen plasmático.","b":"Déficit de hierro por aumento del consumo fetal.","c":"Aumento de la destrucción eritrocitaria.","d":"Disminución de la eritropoyesis."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":145,"text":"¿Cuál de los siguientes cambios respiratorios es característico del embarazo normal?","options":{"a":"Hipoventilación fisiológica.","b":"Aumento de la PaCO₂.","c":"Aumento del ángulo subcostal y expansión de la caja costal.","d":"Alcalosis respiratoria descompensada."},"correct":"c","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":146,"text":"La aparición de cetonuria en una gestante con ingesta insuficiente de hidratos de carbono se explica porque:","options":{"a":"Disminuye la absorción de grasa.","b":"Se incrementa la movilización lipídica.","c":"Aumenta el uso de proteínas fetales.","d":"Se reduce el metabolismo basal."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":147,"text":"En una mujer con IMC normal antes del embarazo, el aumento de peso recomendado es:","options":{"a":"6-8 kg.","b":"8,1-11,3 kg.","c":"11,4–15,9 kg.","d":">16 kg."},"correct":"c","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":148,"text":"En la gestación, el estreñimiento se relaciona con:","options":{"a":"Relajación de la musculatura lisa intestinal y aumento del peristaltismo.","b":"Relajación de la musculatura lisa intestinal y aumento de la secreción gástrica.","c":"Relajación de la musculatura lisa intestinal y pirosis.","d":"Relajación de la musculatura lisa intestinal."},"correct":"d","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":149,"text":"¿Qué signo de peligro en el embarazo debe ser comunicado inmediatamente?","options":{"a":"Ptialismo.","b":"Leucorrea.","c":"Síndrome del túnel carpiano.","d":"Hiperemesis gravídica."},"correct":"d","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":150,"text":"Durante los primeros días del puerperio es normal encontrar:","options":{"a":"Loquios rubra.","b":"Hematoma.","c":"Ausencia de sangrado.","d":"Útero atónico."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":151,"text":"En el postparto, a todas las mujeres Rh negativas que cumplen unos requisitos específicos:","options":{"a":"Hay que administrarles globulina inmunitaria Rh (RhoROL) en las 24 horas posteriores al parto para prevenir la sensibilización por la transfusión materno-fetal de hematíes fetales Rh positivos.","b":"Hay que administrarles globulina inmunitaria Rh (RhoIGM) en las 72 horas posteriores al parto para prevenir la sensibilización por la transfusión materno- fetalde hematíes fetales Rh positivos.","c":"Hay que administrarles globulina inmunitariaRh (RhoGAM) en las 72 horas posteriores al parto para prevenir la sensibilización por la transfusión materno- fetalde hematíes fetales Rh positivos.","d":"Hay que administrarles globulina inmunitariaRh (RhoGAM) en las 24 horas posteriores al parto para prevenir la sensibilización por la transfusión materno- fetalde hematíes fetales Rh positivos."},"correct":"c","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":152,"text":"En relación con la alimentación durante el embarazo, es correcto afirmar que:","options":{"a":"Se deben duplicar las calorías ingeridas.","b":"Se recomienda la suplementación con ácido fólico y hierro.","c":"Las mayores necesidades de vitaminas y minerales pueden cubrirse mediante. suplementación.","d":"Se recomienda una dieta equilibrada adaptada estacionalmente."},"correct":"b","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":153,"text":"Las contracciones de Braxton Hicks se caracterizan por ser:","options":{"a":"Contracciones uterinas intermitentes no dolorosas que aparecen cada 10 ó 20 minutos. Se presentan con mayor frecuencia hacia el término de la gestación, y a veces se confunden con verdaderos signos de parto.","b":"Contracciones uterinas intermitentes dolorosas que aparecen cada 10 ó 20 minutos. Se presentan con mayor frecuencia hacia el inicio de la gestación, y a veces se confunden con verdaderos signos de parto.","c":"Contracciones uterinas intermitentes no dolorosas que aparecen cada 10 ó 20 minutos. Se presentan con mayor frecuencia hacia el término de la gestación, y no se confunden con verdaderos signos de parto.","d":"Contracciones uterinas intermitentes dolorosas que aparecen cada 10 ó 20 minutos. Se presentan con mayor frecuencia hacia la mitad de la gestación, y a veces se confunden con verdaderos signos de parto."},"correct":"a","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":154,"text":"Señale la afirmación CORRECTA sobre la miocardiopatía perinatal.","options":{"a":"Su tratamiento incluye digoxina, adrenérgicos, los vasodilatadores necesarios, hemorreológicos, y un estricto reposo en cama.","b":"Los síntomas son semejantes a los de la insuficiencia respiratoria adquirida en la comunidad: disnea, ortopnea, cansancio, tos, dolor torácico y edema.","c":"No está desaconsejado un nuevo embarazo porque la enfermedad no tiende a recidivar durante la gestación.","d":"Consiste en una disfunción del ventrículo izquierdo que se produce en el último mes de la gestación o en los 5 primeros meses del puerperio."},"correct":"d","disputed":false,"topic":"Neurología y Neurocirugía"},{"num":155,"text":"Se consideran las principales causas de depresión posparto:","options":{"a":"Adaptaciones psicológicas y los factores hormonales.","b":"La fatiga, la incomodidad.","c":"La incomodidad y la sobreestimulación.","d":"Factores hormonales y la sobreestimulación."},"correct":"a","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":156,"text":"Son cambios maternales correspondientes a las 24 semanas de gestación:","options":{"a":"El feto desciende a la pelvis materna (encajamiento). La placenta es casi cuatro veces más gruesa que hace 20 semanas y pesa casi 10 kg. La madre está deseando parir, puede tener accesos finales de energía. Aumentan las lumbalgias y la frecuencia urinaria. Las contracciones de Braxton Hicks se intensifican mientras el cérvix y el segmento uterino inferior se preparan para el parto. La pareja puede visitar las salas de dilatación y de parto.","b":"El fondo uterino llega a la altura del ombligo. Las mamas empiezan a secretar calostro. La bolsa amniótica contiene unos400 mL de líquido. La mujer puede marearse y desvanecerse, especialmente al cambiar bruscamente de postura. Pueden empezar a aparecer varices venosas. La mujer percibe los movimientos del feto y el embarazo puede parecerle “más real” de repente. Las aréolas se oscurecen. Puede aparecer congestión nasal. Pueden empezar a producirse calambres en las piernas. Puede producirse estreñimiento.","c":"El fondo uterino alcanza la apófisis xifoides; las mamas están hinchadas y sensibles. Puede reaparecer la polaquiuria. Pueden hincharse los tobillos y aparecer problemas para dormir. Puede producirse disnea.","d":"El fondo uterino se sitúa por encima del ombligo. Puede producirse lumbalgia y calambres en las piernas. La piel puede sufrir cambios, como estrías gravídicas, cloasma, línea negra, acné, eritema palmar y plantar. Pueden producirse hemorragias nasales. El crecimiento del útero puede provocar prurito abdominal; seguirá hasta el término de la gestación."},"correct":"d","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":157,"text":"En relación a los principales mecanismos fisiológicos de regulación renal. ¿Cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La regulación de la excreción de agua depende principalmente de la aldosterona, que ajusta el volumen urinario en función de la ingesta hídrica diaria.","b":"La regulación de la excreción de solutos implica que, en condiciones normales, la cantidad de electrolitos excretados diariamente es igual a la cantidad ingerida, estando el sodio bajo control hormonal de la aldosterona.","c":"La regulación del equilibrio ácido-base se basa fundamentalmente en la eliminación pulmonar del dióxido de carbono, siendo mínima la participación renal en la excreción de ácidos.","d":"La regulación de la presión arterial renal se produce por vasodilatación directa de los glomérulos en respuesta al aumento de la presión arterial sistémica, sin participación hormonal."},"correct":"b","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":158,"text":"Durante la valoración de enfermería, se identifican antecedentes personales que pueden aumentar el riesgo de alteraciones renales o urológicas. ¿Cuál de las siguientes asociaciones entre enfermedad sistémica y complicación renal es CORRECTA?","options":{"a":"Lupus eritematoso sistémico → Nefritis y enfermedad renal crónica.","b":"Embarazo → Incontinencia urinaria permanente por daño neurológico.","c":"Esclerosis múltiple → Insuficiencia renal aguda por hipoperfusión renal.","d":"Radioterapia de la pelvis → Formación de cálculos renales de oxalato cálcico."},"correct":"a","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":159,"text":"Un paciente con insuficiencia renal crónica avanzada presenta deterioro progresivo del estado mental, dificultades de concentración y alteraciones del nivel de conciencia compatibles con encefalopatía urémica crónica. Desde la perspectiva del tratamiento, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La encefalopatía urémica crónica se trata fundamentalmente mediante la restricción hídrica y el ajuste dietético, sin necesidad de terapia de reemplazo renal.","b":"El tratamiento de elección consiste en la administración intravenosa de bicarbonato para corregir la acidosis metabólica y mejorar el estado neurológico.","c":"La hemodiálisis solo está indicada en casos de encefalopatía aguda, no siendo útil en alteraciones neurológicas crónicas asociadas a uremia.","d":"La diálisis actúa como tratamiento de soporte vital al eliminar productos de desecho y desequilibrios electrolíticos responsables de la encefalopatía urémica."},"correct":"d","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":160,"text":"En pacientes con insuficiencia renal crónica en tratamiento con hemodiálisis, ¿cuál de las siguientes afirmaciones sobre el manejo de las proteínas en la dieta es CORRECTA?","options":{"a":"Debe restringirse de forma estricta, independientemente del tratamiento sustitutivo, para evitar la acumulación de productos nitrogenados.","b":"Debe aumentarse la ingesta proteica para prevenir la desnutrición proteico- energética asociada a la uremia y a las pérdidas durante la diálisis.","c":"Debe basarse preferentemente en proteínas vegetales, ya que aportan un mayor valor biológico que las proteínas animales.","d":"Puede reducirse la ingesta proteica siempre que el aporte calórico total de la dieta sea suficiente."},"correct":"b","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":161,"text":"Un paciente de 68 años ingresa por vómitos y diarrea de varios días de evolución. En la analítica se observa aumento de urea y creatinina, con una relación urea/creatinina claramente elevada. La diuresis está disminuida. En el estudio de orina se objetivan sodio urinario < 20 mEq/L, osmolalidad urinaria elevada y sedimento urinario sin alteraciones significativas. Según estos datos, ¿qué tipo de lesión renal aguda es la más probable?","options":{"a":"Lesión renal aguda intrarrenal.","b":"Lesión renal aguda posrenal.","c":"Lesión renal aguda prerrenal.","d":"Lesión renal aguda por daño parenquimatoso tubular."},"correct":"c","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":162,"text":"¿Cuál de las siguientes NO corresponde a una causa de insuficiencia renal prerrenal?","options":{"a":"Pérdidas gastrointestinales por vómitos y diarrea.","b":"Hemorragia aguda.","c":"Insuficiencia cardiaca con disminución del gasto cardíaco.","d":"Obstrucción de las vías urinarias por hiperplasia prostática benigna."},"correct":"d","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":163,"text":"En relación con los ejercicios de los músculos pélvicos en el tratamiento de la incontinencia urinaria, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"Los ejercicios de Kegel fortalecen exclusivamente la musculatura del suelo pélvico en mujeres y no se recomiendan en hombres.","b":"Los ejercicios de Kegel deben realizarse únicamente durante fases activas de contracción, sin periodos de reposo, para ser eficaces.","c":"Los ejercicios de Kegel consisten en contracciones voluntarias de 5–10 segundos seguidas de fases de reposo, y deben realizarse varias veces al día durante al menos 6 semanas.","d":"La eficacia de los ejercicios de Kegel depende principalmente de la estimulación eléctrica asociada, siendo poco útiles cuando se realizan de forma aislada."},"correct":"c","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":164,"text":"En relación con los tipos de incontinencia urinaria, señale la afirmación FALSA:","options":{"a":"Incontinencia urinaria de esfuerzo: pérdida involuntaria de orina a través de una uretra intacta asociada a aumentos de la presión abdominal, como al toser, estornudar o cambiar de posición, relacionada con un menor soporte del suelo pélvico.","b":"Incontinencia urinaria de urgencia: pérdida involuntaria de orina asociada a un deseo urgente de orinar que no puede ser suprimido, generalmente precipitada por una contracción no inhibida del detrusor, incluso en ausencia de disfunción neurológica evidente.","c":"Incontinencia urinaria funcional: pérdida involuntaria de orina causada por alteraciones estructurales de la vejiga o la uretra, con vías urinarias inferiores intactas pero incapacidad del esfínter para mantener la continencia.","d":"Incontinencia urinaria iatrogénica: pérdida involuntaria de orina secundaria a factores médicos externos, especialmente fármacos, que alteran los mecanismos de cierre uretral o aumentan la presión intravesical."},"correct":"c","disputed":false,"topic":"Salud Mental y Psiquiatría"},{"num":165,"text":"En relación con los factores de riesgo de la incontinencia urinaria, señale la opción FALSA:","options":{"a":"Demencia.","b":"Inmovilidad.","c":"Furosemida.","d":"Ejercicio aeróbico."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":166,"text":"Durante el sondaje vesical permanente, la enfermera debe aplicar medidas para reducir el riesgo de infección urinaria asociada a la sonda. ¿Cuál de las siguientes actuaciones NO es correcta?","options":{"a":"Mantener la bolsa colectora por debajo del nivel de la vejiga.","b":"Irrigar la sonda de forma rutinaria para evitar obstrucciones.","c":"Realizar higiene de manos antes y después de manipular el sistema.","d":"Mantener el sistema de drenaje cerrado y sin desconexiones innecesarias."},"correct":"b","disputed":false,"topic":"Urología y Nefrología"},{"num":167,"text":"En relación con la estimación clínica del llenado de la vejiga, ¿cuál de las siguientes afirmaciones NO es correcta?","options":{"a":"La vejiga normalmente no es palpable hasta que contiene más de 150 ml de orina.","b":"La percusión suprapúbica suele producir un sonido hueco en condiciones normales.","c":"Cuando la vejiga contiene aproximadamente 500 ml, puede apreciarse un abultamiento suprapúbico.","d":"El dolor aparece de forma precoz, antes de alcanzar la capacidad total vesical."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":168,"text":"Durante la revisión del plan de cuidados enfermeros en un paciente con sonda urinaria permanente, te encuentras revisando las intervenciones dirigidas a prevenir la infección urinaria asociada a la sonda. ¿Cuál de las siguientes actuaciones NO es correcta según las recomendaciones actuales?","options":{"a":"Cambiar la sonda urinaria cuando exista obstrucción del flujo para corregir problemas de filtración.","b":"Sustituir la bolsa colectora cada 8 horas de forma sistemática para reducir la carga bacteriana.","c":"Mantener el tubo de drenaje sin acodamientos para asegurar un flujo continuo de orina.","d":"Evitar la irrigación rutinaria de la sonda salvo indicación clínica específica."},"correct":"b","disputed":false,"topic":"Urología y Nefrología"},{"num":169,"text":"Durante la realización de un sondaje vesical, la enfermera debe adaptar la técnica según las diferencias anatómicas entre hombres y mujeres. ¿Cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"En la mujer, la menor longitud de la uretra permite un sondaje más rápido y con menor riesgo de lesión.","b":"En el varón, la menor longitud de la uretra permite un sondaje más rápido y con menor riesgo de lesión.","c":"En la mujer, se recomienda inflar el balón inmediatamente tras la aparición de orina.","d":"En el varón, es necesario avanzar la sonda varios centímetros después de la aparición de orina antes de inflar el balón."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":170,"text":"El sitio más frecuente para la epistaxis es el tabique anterior. ¿Cuál de los siguientes vasos sanguíneos NO está implicado en este tipo de epistaxis?","options":{"a":"Arteria etmoidal anterior.","b":"Rama septal de la arteria labial superior.","c":"Arteria palatina mayor.","d":"Arteria esfenopalatina en la region postoinferior."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":171,"text":"En relación con el manejo inicial de la epistaxis anterior, ¿cuál de las siguientes medidas NO es correcta?","options":{"a":"Colocar al paciente en posición sentada, con la cabeza inclinada hacia adelante.","b":"Aplicar presión directa comprimiendo la parte dura externa de la nariz contra el tabique nasal.","c":"Mantener la compresión nasal continua durante al menos 5–10 minutos.","d":"Utilizar un descongestionante nasal en aerosol, como la fenilefrina, para favorecer la vasoconstricción."},"correct":"b","disputed":false,"topic":"Urología y Nefrología"},{"num":172,"text":"Tras un episodio de epistaxis, la enfermera realiza educación sanitaria orientada a prevenir nuevos sangrados. ¿Cuál de las siguientes recomendaciones SÍ debe incluirse en la capacitación del paciente sobre su autocuidado?","options":{"a":"Reanudar el ejercicio físico intenso a las 24 horas si no reaparece el sangrado.","b":"Aplicar calor local sobre el dorso nasal para favorecer la vasodilatación y la cicatrización.","c":"Evitar alimentos calientes y el consumo de tabaco durante varios días tras el episodio.","d":"Sonarse la nariz con fuerza para eliminar coágulos residuales y prevenir recurrencias."},"correct":"c","disputed":false,"topic":"Urología y Nefrología"},{"num":173,"text":"Durante una valoración auditiva, una enfermera revisa el resultado de una audiometría tonal de un paciente adulto. El informe muestra una pérdida auditiva de 10 dB en el oído derecho. Según la clasificación por decibelios, ¿cómo debe interpretarse este hallazgo?","options":{"a":"Audición normal","b":"Pérdida auditiva leve.","c":"Pérdida auditiva moderada.","d":"Pérdida auditiva grave."},"correct":"a","disputed":false,"topic":"Urología y Nefrología"},{"num":174,"text":"Durante la valoración de un paciente con sospecha de pérdida auditiva conductiva, la enfermera repasa posibles causas relacionadas con el oído externo y medio. ¿Cuál de las siguientes NO se asocia a una pérdida auditiva conductiva?","options":{"a":"Tapones de cerumen","b":"Otitis externa","c":"Otosclerosis del oído medio","d":"Daño del nervio vestíbulo-coclear"},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":175,"text":"En relación con la otitis externa, señale la afirmación CORRECTA:","options":{"a":"Es una infección del oído medio caracterizada por dolor retroauricular y perforación timpánica.","b":"Se produce principalmente por infecciones bacterianas (Aspergillus).","c":"Se presenta con prurito, dolor al movilizar el pabellón auricular, exudado y posible disminución de la audición.","d":"Se recomienda limpiar el conducto auditivo externo con hisopos de algodón."},"correct":"c","disputed":false,"topic":"Urología y Nefrología"},{"num":176,"text":"En la valoración de un paciente con dolor de oído, la enfermera debe diferenciar entre otitis externa y otitis media aguda. ¿Cuál de las siguientes afirmaciones es CORRECTA según las características clínicas de ambos cuadros clínicos?","options":{"a":"En la otitis media, aparece otalgia que se alivia cuando se rompe la membrana timpánica.","b":"En la otitis media aguda cursa con edema del conducto auditivo externo.","c":"En la otitis externa es habitual la presencia de fiebre y síntomas de infección respiratoria alta.","d":"La pérdida auditiva es de tipo neurosensorial en la otitis media aguda y conductiva en la otitis externa."},"correct":"a","disputed":false,"topic":"Urología y Nefrología"},{"num":177,"text":"Tras una cirugía de oído medio o mastoides, la enfermera proporciona educación sanitaria al paciente sobre los cuidados postoperatorios. ¿Cuál de las siguientes intervenciones NO es correcta?","options":{"a":"Evitar sonarse la nariz durante las primeras 2–3 semanas tras la cirugía.","b":"Estornudar y toser con la boca abierta durante varias semanas después de la intervención.","c":"Considerar normales las sensaciones de chasquido o crepitación en el oído intervenido durante los primeros días.","d":"Irrigar el oído intervenido con suero fisiológico si aparece sensación de taponamiento."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":178,"text":"En relación con la otitis media aguda (OMA) en lactantes, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La principal causa de OMA en lactantes es la inmadurez del sistema inmunitario, independientemente de la anatomía de la trompa de Eustaquio.","b":"La trompa de Eustaquio más corta, horizontal y ancha en los lactantes facilita el reflujo de líquido y bacterias desde la nasofaringe al oído medio.","c":"La alimentación con biberón reduce el riesgo de OMA al favorecer una deglución más eficaz en posición supina.","d":"La posición horizontal del lactante durante el sueño disminuye la posibilidad de que la infección alcance el oído medio."},"correct":"b","disputed":false,"topic":"Urología y Nefrología"},{"num":179,"text":"En relación con el colesteatoma como complicación de la otitis media, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"Se trata de una lesión del oído medio, generalmente asociada a otitis media crónica, que puede producir erosión ósea progresiva y pérdida auditiva.","b":"Es una complicación aguda de la otitis media que cursa típicamente con dolor intenso, fiebre elevada y otorrea purulenta de inicio brusco.","c":"Su desarrollo depende fundamentalmente de infecciones virales repetidas del oído medio y suele resolverse con tratamiento antibiótico sistémico prolongado.","d":"Es una lesión inflamatoria benigna que rara vez produce complicaciones locales o intracraneales y no requiere tratamiento quirúrgico."},"correct":"a","disputed":false,"topic":"Urología y Nefrología"},{"num":180,"text":"En relación con los trastornos del equilibrio y del oído interno, señale la definición INCORRECTA:","options":{"a":"Laberintitis: inflamación del laberinto del oído interno, de origen viral o bacteriano, que puede afectar tanto a la audición como al equilibrio y, en ocasiones, aparecer como complicación de una otitis media.","b":"Enfermedad de Ménière: trastorno del oído interno caracterizado por un desequilibrio en los líquidos endolinfáticos, con aumento de la presión endolinfática, que provoca episodios de vértigo, alteraciones auditivas y acúfenos.","c":"Vértigo: percepción errónea o ilusión de movimiento de la persona o de su entorno, que suele describirse como una sensación de giro y se asocia a alteraciones del sistema vestibular.","d":"Mareo: alteración del equilibrio causada por una lesión inflamatoria del laberinto del oído interno, que provoca sensación rotatoria intensa."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":181,"text":"En relación con la enfermedad de Ménière, ¿cuál de las siguientes combinaciones de síntomas es la CORRECTA?","options":{"a":"Vértigo episódico, hipoacusia fluctuante y acúfenos.","b":"Mareo continuo, otalgia intensa y fiebre.","c":"Inestabilidad postural, diplopía y cefalea persistente.","d":"Pérdida auditiva conductiva, vértigo y dolor auricular."},"correct":"a","disputed":false,"topic":"Urología y Nefrología"},{"num":182,"text":"Una mujer de 52 años diagnosticada de enfermedad de Ménière acude a consulta de enfermería para reforzar las recomendaciones dietéticas. Refiere que ha reducido la sal “de mesa”, pero continúa con síntomas fluctuantes. ¿Cuál de las siguientes intervenciones NO es adecuada dentro del plan educativo enfermero?","options":{"a":"Recomendar la distribución regular de comidas y tentempiés a lo largo del día para evitar cambios bruscos en el volumen de líquidos del oído interno.","b":"Aconsejar limitar alimentos procesados y enlatados por su alto contenido en potasio.","c":"Evitar el consumo de cafeína y bebidas carbonatadas por su efecto diurético.","d":"Advertir sobre el consumo de alimentos ricos en glutamato monosódico, por su posible relación con el empeoramiento de los síntomas."},"correct":"b","disputed":false,"topic":"Urología y Nefrología"},{"num":183,"text":"En relación con el mantenimiento de un catéter periférico corto, ¿cuál de las siguientes actuaciones es la más adecuada para disminuir el riesgo de infección y complicaciones asociadas al acceso venoso periférico?","options":{"a":"Cambiar el bioconector siempre que se cambie el catéter o, como máximo, cada 7 días.","b":"Limpiar siempre el bioconector con solución de Clorhexidina alcohólica >2% en alcohol isopropílico al 75% o alcohol isopropílico de 75%.","c":"Observar el punto de inserción al menos una vez al día y realizar cura inmediata si el apósito está sucio, mojado o despegado.","d":"Si se exterioriza parcialmente el catéter periférico corto, puede reintroducirse con técnica aséptica si la salida es inferior a 0,5 cm."},"correct":"a","disputed":false,"topic":"Urología y Nefrología"},{"num":184,"text":"¿En cuál de estos casos NO está indicada la vía venosa periférica?","options":{"a":"Paciente con capital venoso preservado.","b":"Terapia intravenosa prevista inferior a 7 días.","c":"Administración de sustancias no vesicantes ni irritantes con pH entre 5 y 9.","d":"Administración de soluciones con osmolaridad inferior a 600 mOsm/L."},"correct":"d","disputed":false,"topic":"Urología y Nefrología"},{"num":185,"text":"Según las características de los catéteres centrales de inserción periférica (PICC), ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"El PICC de punta abierta con válvula proximal impide el reflujo sanguíneo hacia la punta del catéter y no puede utilizarse para monitorización de la presión venosa central.","b":"El PICC Groshong (punta cerrada con válvula distal) es apto para medición de PVC.","c":"El PICC de punta abierta no valvulado (con pinza) no permite monitorización de PVC.","d":"Los PICC de silicona tienen paredes más finas que los de poliuretano, por lo que aumentan la luz interna para el mismo French (Fr)."},"correct":"a","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":186,"text":"En relación con los cuidados extraluminales e intraluminales de los catéteres centrales de inserción periférica (PICC), ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"En PICC en reposo, el lavado intraluminal debe realizarse diariamente con 5 ml de suero fisiológico para mantener la permeabilidad.","b":"En infusión continua, no se recomienda el lavado intraluminal hasta finalizar el tratamiento, dado que el flujo continuo evita obstrucciones.","c":"Se recomienda que todos los PICC dispongan de bioconector, incluso en perfusión continua.","d":"En infusión intermitente, el lavado intraluminal se realizará únicamente al final del día, independientemente del número de usos."},"correct":"c","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":187,"text":"A la hora de realizar la cura de una herida con sutura (puntos), el/la profesional de enfermería deberá:","options":{"a":"Cortar el hilo de sutura por debajo del punto, alejado del nudo.","b":"Cortar el hilo de sutura por debajo del punto y lo más próximo posible al nudo.","c":"Cortar el hilo de sutura por encima del punto, alejado del nudo.","d":"Cortar el hilo de sutura por encima del punto y lo más próximo posible al nudo."},"correct":"b","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":188,"text":"En la fase preoperatoria de un/a paciente quirúrgico/a, se realizan diversas intervenciones orientadas a la preparación y verificación clínica. ¿Cuál de las siguientes intervenciones NO se lleva a cabo en dicha fase?","options":{"a":"Anamnesis.","b":"Revisión de pruebas de laboratorio.","c":"Verbalización formal del protocolo “paciente correcto, procedimiento correcto, sitio correcto”.","d":"Evaluación física."},"correct":"c","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":189,"text":"Según el sistema de puntuación de recuperación postanestesia de Aldrete, ¿en cuál de los siguientes escenarios el/la paciente cumple criterios para el alta de la Unidad de Recuperación Postanestésica (URPA), considerando que se requiere una puntuación total igual o mayor a 9?","options":{"a":"Paciente que mueve voluntariamente las cuatro extremidades, presenta tensión arterial dentro de ± 20 mmHg del valor preanestésico, está totalmente despierto, mantiene una spO2 >92% con aire ambiente y respira normalmente sin dificultad.","b":"Paciente que mueve voluntariamente dos extremidades, presenta tensión arterial dentro de ± 40 mmHg del valor preanestésico, se despierta al llamarlo, requiere de oxígeno suplementario para mantener spO2 >90% y presenta respiración superficial.","c":"Paciente que mueve voluntariamente las cuatro extremidades, presenta tensión arterial > 50 mmHg del valor preanestésico, se despierta al llamarlo, requiere de oxígeno suplementario para mantener spO2 >90% y presenta respiración superficial.","d":"Paciente que mueve voluntariamente dos extremidades, presenta tensión arterial dentro de ± 45 mmHg del valor preanestésico, se despierta al llamarlo, requiere de oxígeno suplementario y respira normalmente sin dificultad."},"correct":"a","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":190,"text":"Durante el seguimiento clínico del paciente en la sala de recuperación postanestésica, ¿cuál es la secuencia correcta para el control de las constantes vitales y la valoración del dolor tras la cirugía?","options":{"a":"Control cada 30 minutos hasta la estabilización, posteriormente cada hora durante 6 horas y después cada 8 horas durante 48 horas.","b":"Valoración cada 10 minutos durante la primera hora, posteriormente cada 2 horas durante 12 horas y después cada 6 horas durante 72 horas.","c":"Monitorización continua durante las primeras 4 horas, seguida de controles cada 2 horas durante las siguientes 24 horas.","d":"Evaluación cada 15 minutos hasta la estabilización, posteriormente cada 30 minutos durante 2 horas, cada hora durante 4 horas y, finalmente, cada 4 horas durante 24– 48 horas."},"correct":"d","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":191,"text":"Al realizar un balance hídrico de un paciente y considerando los aportes y pérdidas medias diarias de líquidos en un adulto sano, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Las pérdidas urinarias habituales representan aproximadamente 800 ml al día, siendo el principal mecanismo de eliminación hídrica.","b":"La producción endógena de agua derivada del catabolismo de proteínas, carbohidratos y grasas aporta aproximadamente 300 ml diarios.","c":"Las pérdidas a través de la piel son inferiores a 200 ml diarios en condiciones normales.","d":"La eliminación hídrica por vía fecal constituye la principal fuente de pérdida de líquidos, superando los 600 ml diarios."},"correct":"b","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":192,"text":"El denominado “tercer espacio” se refiere al desplazamiento del líquido desde el espacio extracelular hacia compartimentos no funcionales, donde no contribuye al equilibrio hídrico entre el líquido intracelular y extracelular. En este contexto, ¿cuál de los siguientes conjuntos de signos y síntomas es más indicativo de la formación de tercer espacio?","options":{"a":"Aumento del volumen urinario, hipertensión arterial, elevación de la presión venosa central y pérdida de peso.","b":"Disminución de la frecuencia cardíaca, aumento de la presión arterial, edemas y balance hídrico positivo.","c":"Oliguria, hipotensión, disminución de la presión venosa central, edema y aumento ponderal.","d":"Poliuria, hipotensión, disminución de la presión venosa central, bradicardia y desequilibrio entre ingresos y egresos de líquidos."},"correct":"c","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":193,"text":"Durante la administración de anestesia general en el contexto quirúrgico, el personal de enfermería debe conocer las características clínicas de cada una de sus etapas para garantizar la seguridad del paciente. ¿Cuál de las siguientes afirmaciones describe correctamente las manifestaciones y cuidados prioritarios en cada fase anestésica?","options":{"a":"En la etapa I predominan la inconsciencia profunda y la inmovilidad.","b":"La etapa II se caracteriza por agitación psicomotriz que incluye manifestaciones variables como gritos, risa o llanto.","c":"Durante la etapa III el paciente presenta midriasis fija, pulso débil y riesgo elevado de paro respiratorio.","d":"La etapa IV el paciente presenta sudoración profusa, sialorrea, hipertensión y taquipnea."},"correct":"b","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":194,"text":"Durante la administración y el seguimiento de un paciente sometido a anestesia raquídea, ¿cuál de las siguientes afirmaciones describe correctamente sus características clínicas y los cuidados posteriores más relevantes?","options":{"a":"La anestesia raquídea se administra habitualmente en el espacio subaracnoideo a nivel de L2–L3 y produce un bloqueo progresivo descendente desde el abdomen hacia las extremidades inferiores.","b":"La cefalea posterior a la anestesia raquídea se previene fundamentalmente mediante la sedestación precoz y la estimulación de la deambulación temprana.","c":"La colocación del paciente en posición semisentada inmediatamente tras la punción favorece un mayor nivel de bloqueo y reduce las complicaciones neurológicas.","d":"Tras la punción subaracnoidea lumbar, el bloqueo suele iniciarse en los dedos y el perineo, progresa hacia las extremidades inferiores y el abdomen."},"correct":"d","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":195,"text":"En el contexto de las técnicas de anestesia regional empleadas en el ámbito quirúrgico, ¿cuál de las siguientes afirmaciones describe correctamente una característica propia de la anestesia epidural?","options":{"a":"La anestesia epidural se administra en el espacio subaracnoideo tras atravesar la duramadre, utilizando dosis bajas de anestésico local.","b":"La anestesia epidural produce exclusivamente bloqueo sensitivo, sin afectar la función motora ni autonómica.","c":"La anestesia epidural requiere dosis más elevadas que la anestesia raquídea y presenta menor riesgo de cefalea postpunción.","d":"La anestesia epidural se caracteriza por un inicio inmediato del bloqueo debido al contacto directo del anestésico con la médula espinal."},"correct":"c","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":196,"text":"¿Qué característica define mejor a la enfermedad neoplásica maligna?","options":{"a":"Crecimiento lento y encapsulado.","b":"Regresión espontánea.","c":"Dependencia hormonal exclusiva.","d":"Capacidad de invasión y metástasis."},"correct":"d","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":197,"text":"En la administración de quimioterapia vesicante prolongada se recomienda:","options":{"a":"Vía intramuscular.","b":"Vía subcutánea.","c":"Vía oral.","d":"Catéter venoso central."},"correct":"d","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":198,"text":"¿Cuál es un efecto secundario frecuente derivado de la mielosupresión?","options":{"a":"Trombocitopenia.","b":"Hipertensión.","c":"Hiperglucemia.","d":"Retención urinaria."},"correct":"a","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":199,"text":"¿Qué equipo es obligatorio para preparar quimioterapia?","options":{"a":"Doble guante de nitrilo.","b":"Cabina de flujo laminar convencional.","c":"Gabinete de seguridad biológica clase II o III.","d":"Mascarilla quirúrgica simple."},"correct":"c","disputed":false,"topic":"Oncología y Cuidados Oncológicos"},{"num":200,"text":"Durante la primera hora de infusión de citostáticos, suelen aparecer:","options":{"a":"Daño renal.","b":"Necrosis tisular.","c":"Reacciones de hipersensibilidad.","d":"Náuseas, vómitos intensos, diarrea y mucositis."},"correct":"c","disputed":false,"topic":"Cuidados Paliativos"},{"num":201,"text":"La estomatitis asociada a quimioterapia requiere:","options":{"a":"Cepillado agresivo.","b":"Enjuagues alcohólicos.","c":"Ayuno prolongado.","d":"Exploración bucal diaria."},"correct":"d","disputed":false,"topic":"Cuidados Paliativos"},{"num":202,"text":"¿Qué complicación trombótica es frecuente en pacientes oncológicos?","options":{"a":"Tromboembolia venosa.","b":"Trombocitosis.","c":"Hemofilia adquirida.","d":"Púrpura trombótica."},"correct":"a","disputed":false,"topic":"Cuidados Paliativos"},{"num":203,"text":"Un objetivo clave de enfermería en radioterapia es:","options":{"a":"Evitar toda actividad física.","b":"Aplicar cremas alcohólicas.","c":"Regular la exposición solar.","d":"Cuidar de la piel irradiada."},"correct":"d","disputed":false,"topic":"Cuidados Paliativos"},{"num":204,"text":"La ropa contaminada con citostáticos debe:","options":{"a":"Colocarse en contenedores específicos.","b":"Reutilizarse tras lavado.","c":"Desecharse como residuo común.","d":"Lavarse en casa."},"correct":"a","disputed":false,"topic":"Cuidados Paliativos"},{"num":205,"text":"Es una característica de las neoplasias malignas:","options":{"a":"Presenta células bien diferenciadas, parecidas a las células normales del tejido del que se originó el tumor.","b":"El tumor crece por expansión y no infiltra los tejidos circundantes.","c":"Su velocidad de crecimiento es, casi siempre, lenta.","d":"Crece en la periferia y emite prolongaciones que infiltran e invaden los tejidos circundantes."},"correct":"d","disputed":false,"topic":"Cuidados Paliativos"},{"num":206,"text":"Señala el cáncer con influencia genética de carácter autosómico recesivo:","options":{"a":"Síndrome de Cowden.","b":"Síndrome de Lynch (cáncer de colon hereditario sin poliposis).","c":"Síndrome de melanoma familiar.","d":"Síndrome de Li-Fraumeni."},"correct":"c","disputed":false,"topic":"Cuidados Paliativos"},{"num":207,"text":"Los interferones, son:","options":{"a":"Citocinas producidas por subconjuntos de linfocitos T,células citolíticas naturales y células dendríticas.","b":"Citocinas con propiedades antivíricas, antitumorales e inmunomoduladoras (inhibición o estimulación del sistema inmunitario).","c":"Sustancia que causa inflamación, daño y necrosis tisulares cuando se extravasa y hay contacto con los tejidos.","d":"Sustancias que contienen porciones de células malignas, solas o combinadas."},"correct":"b","disputed":false,"topic":"Cuidados Paliativos"},{"num":208,"text":"¿Qué EPI es correcto al manipular citostáticos?","options":{"a":"Doble guante específico para quimioterapia.","b":"Doble guante estéril quirúrgico.","c":"Doble guante de nitrilo.","d":"Doble guante de poliisopreno."},"correct":"c","disputed":false,"topic":"Cuidados Paliativos"},{"num":209,"text":"En los cuidados al final de la vida, existen ciertas claves que nos permiten escuchar de forma eficaz: SEÑALE LA INCORRECTA.","options":{"a":"Evitar las respuestas estereotípicas, como “sé cómo se siente”.","b":"Hacer preguntas.","c":"Alentar con gentileza: “¿Necesitan más tiempo para pensarlo?”.","d":"Rellenar con cualquier charla el “espacio vacío” en la comunicación."},"correct":"d","disputed":false,"topic":"Cuidados Paliativos"},{"num":210,"text":"El acrónimo COMFORT sirve de marco para la comunicación en cuidados paliativos, sus letras se refieren a:","options":{"a":"Comunicación, Orientacion, Convencerse,Familia,Oportunidades,Relacionarse y Trabajo en equipo.","b":"Comunicación, Orientacion, Consciencia,Familia,Oportunidades,Relacionarse y Trabajo en equipo.","c":"Comunicación, Orientacion,Convencerse,Familia,Oportunidades,Relajarse y Trabajo en equipo.","d":"Comunicación, Orientacion, Consciencia,Familia,Oportunidades,Relacionarse y Terapia farmacológica."},"correct":"b","disputed":false,"topic":"Cuidados Paliativos"},{"num":211,"text":"¿Cuál sería una respuesta adecuada ante una persona en situación grave que pregunta al personal de enfermería sobre si se está muriendo?","options":{"a":"En esta situación, está permitido dar respuestas inútiles que desacrediten las preocupaciones reales del enfermo o releguen el problema a otro profesional de la salud mejor preparado.","b":"Se escucha con atención, se hacen preguntas adicionales de aclaración y se tranquiliza al enfermo sólo cuando él sea realista.","c":"Se debe establecer una declaración o pregunta cerrada (“¿Piensa usted en la muerte?”).","d":"Se debe evitar el contacto visual, favoreciendo el contacto físico y comenzar con una declaración que reconozca los temores del paciente."},"correct":"b","disputed":false,"topic":"Cuidados Paliativos"},{"num":212,"text":"Son signos de muerte próxima:","options":{"a":"La visión y la audición pueden estar disminuidos y el habla puede ser difícil de comprender.","b":"Es posible que las secreciones se acumulen en la parte posterior de la garganta y se escuche un borboteo cuando el paciente respira por la boca.","c":"La respiración puede volverse irregular, con períodos sin respiración (apnea).","d":"a),b) y c) son correctas."},"correct":"d","disputed":false,"topic":"Cuidados Paliativos"},{"num":213,"text":"¿Cuál de los siguientes es un fármaco de elección para el exceso de secreciones bucales y respiratorias cuando la muerte es inminente?","options":{"a":"Adrenalina.","b":"Salbutamol.","c":"Escopolamina.","d":"Bromuro de ipratropio."},"correct":"c","disputed":false,"topic":"Cuidados Paliativos"},{"num":214,"text":"¿Cuál de las siguientes expresiones asocia a la etapa de Negociación del duelo de Kübler-Ross?","options":{"a":"“No sé cómo se las van a arreglar mis hijos cuando yo no esté”.","b":"“He tenido una buena vida y no lamento nada”.","c":"“Esto no puede ser cierto”.","d":"“Sólo quiero ver el nacimiento de mi nieto, entonces voy a estar listo...”."},"correct":"d","disputed":false,"topic":"Cuidados Paliativos"},{"num":215,"text":"El dolor como consecuencia del cáncer relacionado con órganos es:","options":{"a":"Dolor visceral.","b":"Dolor neuropatica.","c":"Dolor somático.","d":"Dolor simpático."},"correct":"a","disputed":false,"topic":"Cuidados Paliativos"},{"num":216,"text":"La Escala visual del dolor revisada:","options":{"a":"Utiliza diferentes palabras o frases para describir la intensidad del dolor, como “sin dolor, leve, moderado, grave, muy intenso y el peor posible”.","b":"Tiene seis rostros para que sea congruente con otras escalas que emplean la métrica de 0 a 10. Los rostros van desde una expresión facial neutra a una de dolor intenso y están numeradas con 0, 2, 4, 6, 8 y 10.","c":"Consiste en una línea horizontal (a veces vertical) de 10 cm con referencias de palabras en los extremos, como “sin dolor” en un extremo y “dolor tan grave como sea posible” o “peor dolor posible” en el otro extremo.","d":"Consta de seis caras de dibujos con descriptores por escrito, que van desde un rostro sonriente a la derecha para “sin dolor” a un rostro con ceño fruncido lloroso a la izquierda para “el peor dolor”."},"correct":"b","disputed":false,"topic":"Cuidados Paliativos"},{"num":217,"text":"¿Cuál de las siguientes es una característica del fentanilo?","options":{"a":"Produce efectos adversos hemodinámicos mínimos.","b":"Tiene un inicio lento pero una acción de larga duración.","c":"Es un opiáceo lipófobo, a diferencia de la morfina.","d":"Tiene un inicio rápido y una acción de larga duración."},"correct":"a","disputed":false,"topic":"Cuidados Paliativos"},{"num":218,"text":"Entre los procesos clave del duelo que permiten a las personas adaptarse a la pérdida de manera sana NO se encuentra:","options":{"a":"Replicar los antiguos vínculos con la persona fallecida.","b":"Reaccionar a la separación, experimentar y expresar el dolor de la pérdida.","c":"Recordar y re experimentar al difunto, la relación y los sentimientos implicados.","d":"Reajustarse para adaptarse al nuevo mundo sin olvidar el antiguo."},"correct":"a","disputed":false,"topic":"Cuidados Paliativos"},{"num":219,"text":"Durante la sedación paliativa, el personal de enfermería: SEÑALE LA INCORRECTA.","options":{"a":"Brinda apoyo emocional al paciente y su familia.","b":"Decide el momento de inicio del tratamiento farmacológico.","c":"Ofrece atención física centrada en el bienestar.","d":"Actúa como colaborador del equipo interdisciplinar."},"correct":"b","disputed":false,"topic":"Cuidados Paliativos"},{"num":220,"text":"La atención paliativa, como concepto más amplio que el de cuidados paliativos, es una estrategia de atención que pretende:","options":{"a":"La prevención y el alivio del sufrimiento, intervienen y alivian el dolor, trabajar con los temas sobre la muerte y duelo, crear vínculos espirituales y psicológicos para la familia y el paciente.","b":"Ayudar a las personas con enfermedades graves a sentirse mejor al prevenir o tratar los síntomas y efectos secundarios de la enfermedad y el tratamiento.","c":"Prevenir y aliviar el sufrimiento y mantener lo mejor posible la calidad de vida delos pacientes y sus familias, cualquiera que sea la etapa de la enfermedad o la necesidad de otros tratamientos.","d":"Un enfoque que mejora la calidad de vida de pacientes y familias que se enfrentan a los problemas asociados con enfermedades amenazantes para la vida, a través de la prevención y alivio del sufrimiento por medio de la identificación temprana e impecable evaluación y tratamiento del dolor y otros problemas, físicos, psicológicos y espirituales."},"correct":"c","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":221,"text":"Cicely Saunders, reconocida como la fundadora del movimiento hospice moderno y pionera de los cuidados paliativos a nivel mundial. Revolucionó la atención al final de la vida al fundar en 1967 el:","options":{"a":"Royal Trinity Hospice.","b":"St Andrew's Hospice.","c":"St Catherine's Hospice.","d":"St. Christopher’s Hospice."},"correct":"d","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":222,"text":"¿Qué significa tener un envejecimiento activo y saludable?","options":{"a":"Aumentar la esperanza de vida exclusivamente mediante una buena alimentación.","b":"Realizar actividad física diaria.","c":"Mantenerse libre de enfermedades que permitan que perdure la actividad laboral.","d":"Participar en la sociedad aprovechando las capacidades físicas, emocionales y sociales."},"correct":"d","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":223,"text":"¿Cuál es la recomendación general de actividad física diaria para mejorar la salud en personas mayores de 65 años?","options":{"a":"1 hora diaria de actividad intensa.","b":"30 minutos diarios de actividad física.","c":"1 hora diaria de ejercicio aeróbico.","d":"Actividad física dos veces por semana practicando algún deporte."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":224,"text":"La valoración social de una persona anciana requiere:","options":{"a":"La aplicación del índice de Katz.","b":"La aplicación de la escala OARS.","c":"La aplicación de la escala Yesavage.","d":"La aplicación de la escala Zarit."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":225,"text":"Entre los objetivos principales de la Valoración Geriátrica Integral NO encontramos:","options":{"a":"Establecer un diagnostico multidimensional.","b":"Planificar los cuidados de la mejor manera posible.","c":"Definir cuál es la localización más adecuada para el paciente anciano.","d":"Rentabilizar al máximo los recursos sanitarios."},"correct":"d","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":226,"text":"En las personas mayores sin patología tiroidea, la valoración de la función tiroidea se caracteriza por:","options":{"a":"Valores de TSH normales con T4 libre y T3 libre aumentadas.","b":"Valores de TSH bajos con T4 libre y T3 libre también bajos.","c":"Valores de TSH normales con T4 libre y T3 libre normales.","d":"Valores de TSH altos con T4 libre y T3 libre bajos."},"correct":"c","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":227,"text":"La incontinencia urinaria más común en mujeres ancianas y probablemente el tipo de incontinencia establecida más frecuente en mujeres menores de 75 años es:","options":{"a":"Incontinencia funcional.","b":"Incontinencia de esfuerzo.","c":"Incontinencia mixta.","d":"Incontinencia por hiperactividad vesical."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":228,"text":"Señale cuál de los siguientes, corresponde con un cambio fisiológico relacionado con el envejecimiento:","options":{"a":"Aumento de agua extracelular.","b":"Incontinencia urinaria.","c":"Incremento de masa grasa.","d":"Afección selectiva para los tonos de frecuencia baja en la audición."},"correct":"c","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":229,"text":"¿Cómo se interpreta una puntuación de 50 en el Índice de Barthel?","options":{"a":"Dependiente moderado para las actividades básicas de la vida diaria.","b":"Dependiente severo para las actividades básicas de la vida diaria.","c":"Dependiente leve para las actividades básicas de la vida diaria.","d":"Dependiente para las actividades instrumentales de la vida diaria."},"correct":"a","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":230,"text":"El Mini Mental State Examination (MMSE) utiliza la copia de un dibujo (dos pentágonos en intersección)para valorar:","options":{"a":"Atención y cálculo.","b":"Lenguaje y praxis constructiva.","c":"Fijación.","d":"Memoria."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":231,"text":"El CAM (Confusion Assessment Method) es un instrumento útil para el diagnóstico del delirium y evalúa cuatro criterios fundamentales. De las siguientes opciones, ¿cuál es FALSA?","options":{"a":"Alteración del nivel de consciencia.","b":"Alteración de la orientación.","c":"Comienzo agudo y curso fluctuante.","d":"Pensamiento desorganizado."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":232,"text":"Señale un instrumento de utilización frecuente en la valoración de la postura y la marcha en las personas mayores.","options":{"a":"Test de Pfeiffer.","b":"Escala Plutchik.","c":"Test de Tinneti.","d":"Escala de Gramorgan."},"correct":"c","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":233,"text":"En la Valoración funcional de la persona mayor, no debemos olvidar que la capacidad funcional no está influenciada únicamente por su estado físico, sino también por su capacidad mental y entorno social y ambiental. En este caso,¿ cuando hablamos del Grado de autonomía, nos referimos a?:","options":{"a":"Es la necesidad de asistencia física o verbal a través de dispositivos o terceras personas para realizar ciertos actos.","b":"La capacidad funcional de un individuo para realizar, por propia iniciativa y sin ayuda externa, las tareas elementales de autocuidado y funcionamiento físico necesarias para subsistir, tales como comer, vestirse, asearse, usar el baño y moverse. Implica la toma de decisiones personales sobre el propio estilo de vida y el control sobre las acciones diarias.","c":"El estado permanente de limitación física, psíquica o intelectual por el que una persona necesita ayuda importante o asistencia de terceros para realizar las tareas elementales de autocuidado.","d":"Es la capacidad de la persona de decidir por sí mismo su conducta, la orientación de sus actos y la realización de diversas actividades."},"correct":"d","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":234,"text":"¿Señala el grado CORRECTO que establece la Ley 39/2006 de Promoción de la Autonomía Personal y Atención a las personas en situación de dependencia?","options":{"a":"Dependencia moderada, la persona necesita ayuda para realizar varias actividades de la vida diaria, por lo menos dos veces al día.","b":"Dependencia severa, la persona precisa ayuda para realizar varias actividades de la vida cotidiana tres veces al día, pero no requiere la presencia permanente de la persona cuidadora.","c":"Gran dependencia, la persona precisa ayuda para realizar varias actividades básicas de la vida diaria varias veces al día, y necesita la presencia indispensable y continua de otra persona.","d":"Gran discapacidad, la persona eta ante una situación de incapacidad permanente absoluta que requiere la asistencia de otra persona para las necesidades básicas de la vida diaria."},"correct":"c","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":235,"text":"El baño del recién nacido a término sano en contexto de alta precoz:","options":{"a":"Debe evitarse siempre hasta pasadas 24 horas.","b":"Puede realizarse con seguridad tras completar la valoración al ingreso.","c":"Solo se permite tras retirar el pinzamiento del cordón.","d":"Debe realizarse fuera del área térmica (estufa radiante) para estimular la adaptación."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":236,"text":"La administración de Fitonadiona al recién nacido se indica para:","options":{"a":"Prevenir la hipertensión pulmonar persistente.","b":"Prevenir la hipoglucemia neonatal.","c":"Prevenir la enfermedad hemorrágica por niveles bajos de protrombina.","d":"Prevenir el riesgo de sepsis por Neisseria gonorrhoeae."},"correct":"c","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":237,"text":"En un recién nacido en las primeras horas de vida, ¿cuál de los siguientes hallazgos clínicos es más sugerente de hernia diafragmática congénita?","options":{"a":"Dificultad respiratoria con aleteo nasal y sonidos respiratorios ausentes en el lado izquierdo.","b":"Distensión abdominal marcada con timpanismo generalizado y expansión torácica asimétrica.","c":"Respiración entrecortada con sonidos ausentes unilateralmente y sonidos cardíacos desplazados hacia la izquierda.","d":"Dificultad para comenzar la respiración con aleteo nasal y expansión torácica simétrica."},"correct":"a","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":238,"text":"Ante la identificación de ritmo de galope en un recién nacido, la actuación indicada es:","options":{"a":"Registrarlo a pesar de considerarlo fisiológico en el primer mes de vida.","b":"Remitir a consulta e iniciar estudio cardíaco.","c":"Repetir auscultación y reevaluar pasadas 12 horas y al alta.","d":"Registrar el hallazgo y mantener vigilancia clínica, sin remisión inmediata, si el recién nacido no presenta cianosis ni signos de dificultad respiratoria."},"correct":"b","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":239,"text":"¿Cuál de los siguientes hallazgos se considera patológico en la valoración del recién nacido?","options":{"a":"Perlas de Epstein.","b":"Reflejo de Moro presente.","c":"Perímetro torácico 1-2 cm menor que el cefálico.","d":"Pólipos cutáneos preauriculares."},"correct":"d","disputed":false,"topic":"Obstetricia y Ginecología"},{"num":240,"text":"Para que la prueba de fenilcetonuria del recién nacido sea válida, debe realizarse:","options":{"a":"Antes de iniciar cualquier ingesta oral.","b":"Tras al menos 24 de haber iniciado tomas habituales (leche materna o fórmula).","c":"Solo tras las 72 de vida.","d":"Durante el expulsivo para reducir falsos negativos."},"correct":"b","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":241,"text":"En relación con el inicio de la respiración y la reabsorción del líquido pulmonar en el recién nacido sano a término, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"El inicio de la respiración neonatal depende exclusivamente de estímulos químicos.","b":"La mayor parte del líquido pulmonar fetal se elimina por vía alveolar y su reabsorción se completa en las primeras 2 horas de vida.","c":"Durante el parto, la compresión torácica fetal incrementa la presión intratorácica y facilita la expulsión de aproximadamente un tercio del líquido pulmonar.","d":"En el recién nacido a término, el líquido pulmonar pasa directamente al torrente circulatorio, completándose la reabsorción antes de la primera hora."},"correct":"c","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":242,"text":"Tras la administración de la profilaxis ocular neonatal ¿cuál de los siguientes hallazgos es esperable y no necesariamente indicativo de patología?","options":{"a":"Eritema conjuntival leve con lagrimeo discreto y edema palpebral mínimo, autolimitado en la primera hora, atribuible al contacto con secreciones del canal del parto.","b":"Secreción conjuntival serosa transitoria sin hiperemia, que persiste hasta el tercer día de vida y se asocia de forma típica a obstrucción del conducto nasolagrimal.","c":"Hiperemia conjuntival bilateral con edema moderado y sin secreción purulenta, cuya persistencia hasta las 72 horas se considera un hallazgo normal tras profilaxis y no requiere seguimiento.","d":"Conjuntivitis química transitoria, secundaria a la profilaxis ocular, que puede resolverse espontáneamente en 24–48 horas."},"correct":"d","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":243,"text":"En relación con las necesidades dietéticas recomendadas desde el nacimiento hasta los 6 meses, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Las necesidades calóricas del recién nacido se sitúan en torno a 105–108 kcal/kg/día, distribuidas entre proteínas, hidratos de carbono y grasas.","b":"Las necesidades calóricas del recién nacido se sitúan aproximadamente en 80–90 kcal/kg/día, dado que el metabolismo basal neonatal es inferior al del adulto.","c":"Las necesidades calóricas del recién nacido se sitúan en torno a 100–104 kcal/kg/día, distribuidas entre proteínas, hidratos de carbono y grasas, vitaminas y minerales.","d":"Las necesidades calóricas del recién nacido se sitúan aproximadamente en 90-95– 90 kcal/kg/día, dado que el metabolismo basal neonatal es inferior al del adulto."},"correct":"a","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":244,"text":"Dentro de la educación a la familia durante el periodo neonatal uno de los objetivos es que los progenitores:","options":{"a":"Interpreten las vocalizaciones del recién nacido como conducta voluntaria intencional desde el nacimiento.","b":"Ajusten sus expectativas considerando que el recién nacido debe mantener ciclos regulares de sueño-vigilia desde los primeros días, y que el llanto persistente suele indicar siempre enfermedad orgánica.","c":"Verbalicen expectativas conductuales adecuadas en relación con el desarrollo del recién nacido y conozcan la asistencia continuada en atención primaria.","d":"Reconozcan que el patrón conductual del recién nacido es completamente predecible si se establece una rutina estricta, por lo que la variabilidad en respuestas y estados de alerta se considera un signo de mala adaptación."},"correct":"c","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":245,"text":"¿Cuál de las siguientes afirmaciones es correcta en relación a la clasificación del recién nacido según peso para la edad gestacional?","options":{"a":"La clasificación del recién nacido como pequeño para la edad gestacional (PEG), adecuado para la edad gestacional (AEG) o grande para la edad gestacional (GEG) se establece utilizando percentiles, considerando PEG < percentil 5 y GEG > percentil 95.","b":"La clasificación como pequeño para la edad gestacional (PEG), adecuado para la edad gestacional (AEG) o grande para la edad gestacional (GEG) se determina exclusivamente con el perímetro cefálico.","c":"La clasificación como PEG/AEG/GEG se determina en función del peso absoluto al nacimiento, considerando PEG < 2.500 g y GEG > 4.000 g, independientemente de la edad gestacional.","d":"El recién nacido se clasifica como pequeño para la edad gestacional (PEG) si su peso está por debajo del percentil 10; esta categorización permite anticipar problemas fisiológicos y orientar el plan de cuidados."},"correct":"d","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":246,"text":"En el marco de los cuidados generales del recién nacido sano se establecen medidas relacionadas con seguridad y detección precoz antes del alta. ¿Cuál de las siguientes actuaciones es adecuada?","options":{"a":"Verificar la identidad del recién nacido mediante la coincidencia de brazaletes madre-hijo antes de entregarlo a uno de los progenitores.","b":"Administrar la vacuna de hepatitis A y realizar el cribado metabólico solo si existen antecedentes familiares de enfermedades congénitas.","c":"Priorizar la valoración física del recién nacido, dejando los cribados y medidas de seguridad para la primera visita en atención primaria.","d":"Priorizar el alta precoz con recomendaciones de educación sanitaria centradas en cuidados domiciliarios, programando la realización de cribados (audición y metabólico) y la verificación administrativa de identidad en la primera revisión en atención primaria."},"correct":"a","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":247,"text":"La dosis profiláctica habitual de vitamina K1 recomendada en el recién nacido es:","options":{"a":"10 mg vía intramuscular en las primeras 24 horas de vida.","b":"0,5-1 mg IM en la primera hora tras el nacimiento.","c":"5 mg vía oral durante 2 días consecutivos.","d":"0,5 mg/kg intravenoso en la primera hora de vida."},"correct":"b","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":248,"text":"En relación con las características fisiológicas del recién nacido pretérmino, señale la opción INCORRECTA:","options":{"a":"Presenta inmadurez de la pared torácica y de los músculos respiratorios.","b":"Tiene riesgo de anemia por inmadurez eritrocitaria.","c":"Suele presentar déficit de surfactante pulmonar.","d":"Mantiene un almacenamiento mineral de calcio y glucosa similar al del recién nacido a término."},"correct":"d","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":249,"text":"En el cuidado del recién nacido pretérmino con sospecha de enterocolitis necrotizante, la vigilancia clínica por parte de enfermería es fundamental para su detección precoz. ¿Cuál de los siguientes hallazgos clínicos NO es sugestivo de esta patología?","options":{"a":"Presencia de sangre visible u oculta en heces.","b":"Distensión abdominal leve asociada a enlentecimiento del vaciamiento gástrico, sin repercusión sistémica inicial.","c":"Residuo gástrico aumentado con vómitos biliosos.","d":"Distensión abdominal con asas intestinales prominentes."},"correct":"b","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":250,"text":"En relación con los cuidados del recién nacido con enfermedad de la membrana hialina, ¿cuál de las siguientes actuaciones enfermeras es prioritaria en el manejo inicial de estos pacientes?","options":{"a":"Administrar oxígeno humidificado y calentado, y mantener temperatura neutra en incubadora.","b":"Iniciar alimentación enteral precoz y monitorizar el equilibrio ácido-base.","c":"Mantener al neonato en ambiente frío (32-34ºC) para reducir el consumo metabólico.","d":"Evitar la canalización de accesos vasculares para disminuir el riesgo infeccioso."},"correct":"a","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":251,"text":"En relación con la valoración enfermera del recién nacido que presenta vómitos, ¿cuál de las siguientes afirmaciones NO es correcta?","options":{"a":"Los vómitos de estos niños pueden asociarse con la ingestión de sangre o moco procedente del canal del parto.","b":"La aparición precoz de vómitos se asocia a obstrucción baja del tubo digestivo.","c":"A menudo, los vómitos se asocian a una sobrealimentación.","d":"Los vómitos pueden ser secundarios a procesos infecciosos locales fuera del tracto digestivo."},"correct":"b","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":252,"text":"En relación con la rehidratación intravenosa en un lactante con deshidratación isotónica que presenta signos de hipovolemia, ¿cuál de las siguientes pautas iniciales de sueroterapia es la más adecuada durante la primera hora?","options":{"a":"Suero glucosado al 5% a 10 ml/kg/hora.","b":"Suero salino hipertónico al 3% a 5 ml/kg/hora.","c":"Suero glucosado al 10% a 15 ml/kg/hora.","d":"Suero glucosalino 1/5 a 20 ml/kg/hora."},"correct":"d","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":253,"text":"En relación con la valoración clínica del lactante con sospecha de deshidratación leve, ¿cuál de los siguientes conjuntos de signos y síntomas es más compatible con este grado de deshidratación?","options":{"a":"Letargo y fontanelas hundidas.","b":"Mucosas muy secas y taquicardia leve.","c":"Pérdida de peso inferior al 5% y oliguria incipiente.","d":"Orina concentrada y somnolencia."},"correct":"c","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":254,"text":"En relación con los cuidados enfermeros dirigidos a la familia y personas cuidadoras de un recién nacido ingresado en la Unidad de Cuidados Intensivos Neonatales, señale la afirmación INCORRECTA:","options":{"a":"Proporcionar información homogénea y comprensible entre los distintos miembros del equipo multidisciplinar.","b":"Mantener una comunicación sincera, incluso cuando el pronóstico sea incierto.","c":"Favorecer el contacto familiar mediante la flexibilización de horarios.","d":"Limitar la información proporcionada a la familia para reducir su ansiedad."},"correct":"d","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":255,"text":"En relación con la valoración y los cuidados enfermeros del recién nacido con sospecha de síndrome de aspiración meconial, ¿cuál de los siguientes hallazgos debe alertar prioritariamente a la enfermera sobre la presencia de distrés respiratorio?","options":{"a":"Taquipnea, cianosis y tiraje subcostal.","b":"Bradipnea acompañada de hipotonía y episodios de apnea.","c":"Respiración irregular con respiraciones superficiales.","d":"Bradipnea, aleteo nasal y cianosis."},"correct":"a","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":256,"text":"En relación con los cuidados inmediatos del recién nacido prematuro en la sala de partos, ¿cuál de las siguientes actuaciones enfermeras es prioritaria respecto al uso de la incubadora?","options":{"a":"Mantener la temperatura corporal del recién nacido entre 36,7 y 37,2ºC para evitar hipotermia.","b":"Ajustar la temperatura de la incubadora según la edad gestacional y el peso.","c":"Colocar al recién nacido en incubadora con control térmico intermitente.","d":"Ajustar la temperatura de la incubadora entre 25-29ºC."},"correct":"b","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":257,"text":"En relación con la administración de oxígeno en el recién nacido pretérmino durante la reanimación y los cuidados iniciales, ¿cuál de las siguientes actuaciones enfermeras es correcta?","options":{"a":"Administrar oxígeno al 80-95% para prevenir episodios de hipoxia.","b":"Mantener concentraciones estables de oxígeno durante las primeras horas, ajustándolas solo ante cambios clínicos evidentes.","c":"Administrar oxígeno evitando concentraciones superiores al 40%.","d":"Suspender la administración de oxígeno en cuanto se estabilice la frecuencia respiratoria."},"correct":"c","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":258,"text":"Durante la monitorización de un recién nacido pretérmino ingresado en la Unidad de Cuidados Intensivos Neonatales, la enfermera observa episodios recurrentes de apnea sin causa orgánica aparente. En relación con la apnea idiopática del prematuro, ¿cuál de los siguientes hallazgos es más característico de este cuadro clínico?","options":{"a":"Pausas respiratorias asociadas a inestabilidad laríngea.","b":"Episodios de hipoventilación asociados a inmadurez del control respiratorio.","c":"Episodios de apnea exclusivamente durante el llanto.","d":"Apnea asociada a estridor espiratorio persistente."},"correct":"a","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":259,"text":"¿Cuál de las siguientes afirmaciones NO describe correctamente las convulsiones en el período neonatal?","options":{"a":"Pueden pasar desapercibidas por su presentación poco definida.","b":"Pueden corresponder a crisis ocasionales secundarias a agresiones agudas del sistema nervioso central.","c":"Suelen manifestarse mediante patrones motores claros y reconocibles.","d":"Pueden ser indicativas de disfunción del sistema nervioso central."},"correct":"c","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":260,"text":"Las epilepsias y síndromes epilépticos en el período neonatal pueden manifestarse fundamentalmente de dos formas. ¿Cuál de las siguientes opciones recoge correctamente su clasificación?","options":{"a":"Epilepsias reflejas y epilepsias metabólicas.","b":"Epilepsias ocasionales y verdaderas epilepsias.","c":"Epilepsias transitorias y epilepsias adaptativas.","d":"Epilepsias funcionales y epilepsias madurativas."},"correct":"b","disputed":false,"topic":"Pediatría y Salud Infantil"},{"num":261,"text":"Según las recomendaciones recogidas en el Programa de Salud Infantil de Osakidetza sobre seguridad vial, ¿cuál de las siguientes medidas es la más adecuada para reducir lesiones graves en un niño o una niña como pasajero/a?","options":{"a":"Usar un sistema de retención infantil (SRI) con arnés orientado hacia delante desde que no caben en el SRI a contramarcha hasta por lo menos los 6 años.","b":"Utilizar un sistema de retención infantil homologado, pudiendo utilizar el cinturón de seguridad de adulto en trayectos cortos.","c":"Utilizar cinturón de seguridad de tres puntos cuando ya no quepa en el sistema de retención infantil.","d":"Todos los menores de 15 años deben viajar en los asientos traseros."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":262,"text":"En relación con las recomendaciones de prevención de accidentes y lesiones en la infancia, ¿cuál de las siguientes opciones agrupa medidas preventivas correctas en el hogar y en la vía pública?","options":{"a":"Girar los mangos de las ollas lejos del borde y tener precaución al cocinar con niños alrededor; asegurar el uso de casco en bicicleta/patinete y enseñar seguridad vial.","b":"Enseñar a los niños a compartir y controlar su temperamento; enseñar a evitar animales que no conocen; y evitar el uso de puertas en escalones y escaleras.","c":"Mantener cerillas y mecheros fuera del alcance de los niños; incentivar el uso de andadores para bebes; y asegurar el uso del casco al andar en bicicleta/patinete.","d":"Girar los mangos de las ollas hacia el borde para facilitar el manejo; evitar el transporte de preescolares en vehículos todo terreno; y enseñar a los niños a evitar los animales que no conocen."},"correct":"a","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":263,"text":"El Programa de Salud Infantil de Osakidetza 2021 contempla un total de 15 visitas programadas. De ellas, dos se realizan exclusivamente con finalidad vacunal. ¿A qué edades están establecidas dichas visitas?","options":{"a":"4 meses y 6 meses.","b":"12 meses y 12 años.","c":"12 meses y 15 meses.","d":"6 meses y 13 años."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":264,"text":"Según el Programa de Salud Infantil de Osakidetza 2021, ¿a qué edad se recomienda una visita con enfermería para el cribado de obesidad?","options":{"a":"Entre los 6–8 años, coincidiendo con la incorporación a la Educación Primaria y el inicio de cambios en los hábitos alimentarios.","b":"Entre los 4-6 años, ya que en ese periodo se produce el rebote adiposo.","c":"Entre los 6 y 10 años, dado que en esa edad se observa un riesgo elevado.","d":"A los 12 años, aprovechando la visita de vacunación para evaluar el IMC y orientar medidas preventivas frente al aumento ponderal puberal."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":265,"text":"Según el Programa de Salud Infantil de Osakidetza 2021, respecto a la salud bucodental en menores de 2 años, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Se considerará anormal la falta de erupción de la primera pieza a los 11 meses y la erupción de dientes malformados.","b":"Solamente si se pertenece a un grupo de riesgo de caries dental se darán suplementos de flúor por vía oral a partir de los 6 meses.","c":"En niños menores de 2 años el cepillado deben realizarlo los padres, con una pasta de dientes con 1200 ppm de flúor.","d":"No se considera necesario el cepillado dental hasta la erupción de todas las piezas dentarias temporales."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":266,"text":"¿Cuál de las siguientes opciones incluye factores de riesgo de maltrato infantil relacionados con el menor de edad?","options":{"a":"Separación o divorcio gravemente conflictivo.","b":"Inteligencia del menor superior a la media.","c":"Alta conflictividad parental y violencia doméstica.","d":"Nacimiento prematuro, anomalías al nacimiento o bajo peso al nacer."},"correct":"d","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":267,"text":"Dentro de la promoción de estilos de vida saludables en la infancia, ¿cuál de las siguientes recomendaciones se ajusta mejor al concepto de alimentación equilibrada?","options":{"a":"Priorizar un patrón dietético basado en el incremento de proteínas y la reducción marcada de hidratos de carbono, como estrategia principal para prevenir el exceso ponderal en la infancia.","b":"Promover una dieta variada y equilibrada, ajustada a la edad.","c":"Recomendar la incorporación sistemática de tentempiés entre comidas para evitar la sensación de hambre, aunque ello suponga aumentar el aporte calórico diario.","d":"Se deberá dar consejo alimentario únicamente cuando el IMC se encuentre fuera del rango normal."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":268,"text":"Dentro de la visita “hasta el mes de vida” del Programa de Salud Infantil de Osakidetza 2021, ¿cuál de las siguientes NO es una actividad realizada por enfermería?","options":{"a":"Maniobras de Ortolani y Barlow.","b":"Promoción de la lactancia materna.","c":"Valoración del cordón umbilical.","d":"Comprobar la realización de cribado de metabolopatías."},"correct":"a","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":269,"text":"En Osakidetza, la historia clínica utilizada para la valoración, seguimiento y registro del Progama de Salud Infantil se estructura por etapas que corresponden a 5 guías tipo faro. ¿Cuál de las siguientes opciones recoge correctamente dichas etapas?","options":{"a":"Neonatal (hasta el mes de vida), 2–12 meses, 1–3 años, 3–8 años y 9–14 años.","b":"Neonatal (0–28 días), 2–9 meses, 12–36 meses, 4–7 años y 8–15 años.","c":"Neonatal (hasta el mes de vida), 2–6 meses, 11–24 meses, 3–6 años y 8–13 años.","d":"Neonatal (0–28 días), 2–5 meses, 6–24 meses, 2–6 años y 7–13 años."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":270,"text":"En el ámbito de la Atención Primaria, el personal de enfermería debe tener en cuenta los factores de riesgo relacionados con el desarrollo de obesidad en la infancia. Señale la opción correcta:","options":{"a":"La obesidad en los progenitores no influye en el riesgo de obesidad infantil.","b":"La duración del sueño inferior a 7 horas se asocia a mayor riesgo de obesidad.","c":"El nivel socioeconómico no guarda relación con la obesidad infantil.","d":"La maduración puberal tardía se relaciona con un mayor riesgo de obesidad infantil."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":271,"text":"En el ámbito de la Atención Primaria, el personal de enfermería debe promover hábitos adecuados de higiene bucodental en niños de entre 3 y 6 años, con el fin de prevenir la caries y otras patologías orales. En relación con estas recomendaciones, señale la afirmación INCORRECTA:","options":{"a":"Se recomienda el cepillado dental al menos dos veces al día con pasta fluorada que contenga más de 1000 ppm de flúor.","b":"Uno de los cepillados debe realizarse siempre antes de dormir, utilizando una cantidad de dentífrico similar al tamaño de un guisante.","c":"El cepillado debe ser supervisado por los cuidadores y se debe reducir el consumo de alimentos y bebidas azucaradas.","d":"Tras el cepillado, se debe escupir el dentífrico y enjuagar con abundante agua para eliminar los restos."},"correct":"d","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":272,"text":"En el ámbito del Programa de Salud Infantil de Osakidetza 2021, la prevención del maltrato infantil constituye una línea prioritaria de actuación desde Atención Primaria. En relación con las recomendaciones para la prevención del maltrato infantil, señale la afirmación INCORRECTA:","options":{"a":"La detección sistemática de factores de riesgo en todas las edades permite identificar a familias vulnerables.","b":"La promoción de la lactancia materna forma parte de las estrategias preventivas.","c":"Ante la sospecha de riesgo psicosocial leve, se debe adoptar una actitud de observación sin intervención hasta confirmar el diagnóstico.","d":"La realización de actuaciones preventivas frente a la mutilación genital femenina forma parte de las estrategias del PSI."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":273,"text":"En relación con las etapas del proceso de inicio, consumo y adicción a las drogas en adolescentes, señale la afirmación correcta:","options":{"a":"En la etapa 1 (aprendizaje) el adolescente adquiere sus propios suministros y consume de forma ocasional a diario.","b":"En la etapa 0 (curiosidad) el adolescente consume drogas únicamente en reuniones del grupo durante los fines de semana.","c":"En la etapa 3 (preocupación) el adolescente se siente dependiente y necesita las drogas para mantener su bienestar, pudiendo robar, mentir o faltar a clase para conseguirlas.","d":"En la etapa 4 (destrucción) las drogas producen máxima euforia y se mantiene un consumo elevado."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":274,"text":"En el cribado universal de dislipemia en población adolescente, ¿qué parámetro se recomienda calcular a partir del perfil lipídico sin ayunas?","options":{"a":"Colesterol no-HDL.","b":"Colesterol LDL.","c":"Triglicéridos.","d":"Colesterol VLDL."},"correct":"a","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":275,"text":"En relación con el cribado del consumo de tabaco (CT) en adolescentes, señale la afirmación correcta:","options":{"a":"Existe evidencia sólida de que el cribado del CT reduce el hábito y su intensidad.","b":"El cribado del CT ha demostrado producir cambios consistentes en la actitud del adolescente hacia el consumo.","c":"Aunque no hay evidencia de reducción del hábito, el beneficio potencial del consejo/intervención individual puede superar el riesgo.","d":"Las intervenciones breves de consejo individual se han demostrado moderadamente eficaces."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":276,"text":"En el abordaje del consumo de tabaco en adolescentes desde Atención Primaria, el modelo de intervención recomendado es el de las “5 Aes”. ¿Cuál de las siguientes opciones recoge correctamente sus componentes?","options":{"a":"(Assess) Evaluar actitud – Analizar – Actuar – Acompañar – Ajustar.","b":"(Ask) Interrogar – Aconsejar – (Assess) Evaluar actitud – Ayudar – Acordar seguimiento.","c":"(Ask) Interrogar – Alertar – Aplicar tratamiento – Aconsejar – Auditar.","d":"Aceptar – Animar – Aumentar motivación – (Assess) Evaluar actitud – Aplicar control."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":277,"text":"Respecto a las definiciones relacionadas con el consumo de alcohol en adolescentes, señale la opción INCORRECTA:","options":{"a":"Consumo de alcohol de riesgo: 20–40 g/día en mujeres y 40–60 g/día en hombres.","b":"Consumo excesivo episódico: implica un consumo ≥40 g de alcohol en una sola ocasión.","c":"Consumo perjudicial: >40 g/día en mujeres y >60 g/día en hombres, con consecuencias para la salud física y mental.","d":"Binge drinking: ≥4 bebidas en mujeres y ≥5 en hombres en un corto periodo (≈2 horas)."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":278,"text":"En relación con el consumo de cannabis durante la adolescencia, señale la afirmación correcta:","options":{"a":"Solo se asocia a cambios afectivos transitorios.","b":"No se han descrito cambios estructurales a nivel cerebral.","c":"Se relaciona principalmente con alteraciones del sueño.","d":"Se asocia a deterioro cognitivo y cambios cerebrales."},"correct":"d","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":279,"text":"En relación con las infecciones de transmisión sexual (ITS), señale la opción que incluye únicamente microorganismos causantes de ITS:","options":{"a":"VPH – Chlamydia – Neisseria gonorrhoeae.","b":"VHB – Escherichia coli – tricomona vaginal.","c":"VIH – Candida albicans – Gardnerella vaginalis.","d":"VHS – Mycoplasma hominis – Enterococcus faecalis."},"correct":"a","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":280,"text":"Según las recomendaciones del Programa de Salud Infantil de Osakidetza 2021 sobre sexualidad en la adolescencia, señale la afirmación correcta:","options":{"a":"A los 10 años se indica consejo directo al adolescente sobre ITS y métodos anticonceptivos.","b":"A los 13 años, en adolescentes sexualmente activos/as, se recomienda consejo moderado y valorar riesgo de ITS para posible cribado.","c":"La educación para la salud grupal se recomienda únicamente a partir de los 14 años.","d":"A los 13 años se recomienda consejo de alta intensidad al adolescente y consejo breve a padres y madres."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":281,"text":"Según las recomendaciones de Osakidetza para el cribado de hipercolesterolemia en infancia y adolescencia, ¿cuál es la conducta correcta en niños/as con antecedentes familiares de hipercolesterolemia genética?","options":{"a":"Perfil lipídico universal a los 7 años.","b":"Perfil lipídico selectivo a los 9–11 años.","c":"Perfil lipídico selectivo entre los 12–16 años por mayor sensibilidad.","d":"Perfil lipídico solo si existe obesidad."},"correct":"b","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":282,"text":"En la mayoría de los países europeos, incluida España, una Unidad de Bebida Estándar (UBE) equivale aproximadamente a:","options":{"a":"8 g de alcohol puro.","b":"5 g de alcohol puro.","c":"12 g de alcohol puro.","d":"10 g de alcohol puro."},"correct":"d","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":283,"text":"¿Cuál NO es una de las características de los Anticonceptivos Hormonales Gestágenos?","options":{"a":"Pueden usarse durante la lactancia a partir de las 4 semanas desde el parto.","b":"No interfieren en las relaciones coitales.","c":"Son compatibles con el uso de preservativos.","d":"Pueden usarlos mujeres que no deben usar estrógenos."},"correct":"a","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":284,"text":"En relación con el uso seguro de las Tecnologías de la Información y la Comunicación en adolescentes, señale la definición ERRÓNEA:","options":{"a":"Sharenting: práctica de padres y madres de publicar contenido sobre sus hijos/as en plataformas de internet.","b":"Ciberacoso/ciberbullying: daño intencional y repetido infligido por un/a menor o grupo de menores hacia otro/a menor mediante medios digitales.","c":"Grooming: situación en la que un/a menor difunde deliberadamente imágenes íntimas de otro/a menor a través de redes sociales para dañarle.","d":"Sexting: envío de fotografías o vídeos con contenido sexual realizados por la propia persona y enviados a través de medios digitales, pudiendo derivar en difusión no consentida y acoso."},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":285,"text":"¿Cuál de los siguientes corresponde a un síntoma negativo característico de la esquizofrenia?","options":{"a":"Ideas delirantes de persecución","b":"Alucinaciones auditivas con contenido amenazante","c":"Aplanamiento afectivo","d":"Pensamiento tangencial"},"correct":"c","disputed":false,"topic":"Atención Primaria y Comunitaria"},{"num":286,"text":"¿Cuál de las siguientes definiciones es CORRECTA?","options":{"a":"Trastorno esquizoafectivo: trastorno psicótico caracterizado por la presencia continua de síntomas negativos durante al menos seis meses, sin alteraciones del estado de ánimo asociadas.","b":"Trastorno esquizofreniforme: cuadro clínico con síntomas psicóticos similares a la esquizofrenia, cuya duración total es inferior a seis meses y que no requiere necesariamente deterioro social o laboral para su diagnóstico.","c":"Síndrome de Capgras: trastorno delirante en el que el paciente identifica a personas desconocidas como familiares cercanos que han cambiado de identidad.","d":"Síndrome de Fregoli: alteración psicótica en la que el sujeto cree que ha sido sustituido por un doble idéntico que ocupa su lugar."},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":287,"text":"Durante el seguimiento de un paciente en tratamiento con antipsicóticos, la enfermera debe identificar correctamente las posibles complicaciones y sus manifestaciones clínicas. ¿Cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La acatisia se caracteriza por somnolencia, apatía y síntomas antimuscarínicos.","b":"La discinesia tardía se manifiesta por una inquietud motora intensa con necesidad imperiosa de moverse, especialmente en reposo.","c":"El síndrome neuroléptico maligno cursa con rigidez muscular, hipertermia, disfunción autonómica y alteración del nivel de conciencia.","d":"La distonía aguda consiste en movimientos involuntarios orofaciales de aparición tardía tras años de tratamiento antipsicótico."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":288,"text":"Durante la valoración inicial de un paciente con esquizofrenia ingresado en la unidad, la enfermera observa que el paciente presenta risas inmotivadas, frases incomprensibles, fuga de ideas y tendencia al soliloquio. Según los patrones funcionales, ¿en cuál de los siguientes patrones se encuadran principalmente estos hallazgos?","options":{"a":"Patrón roles y relaciones.","b":"Patrón autopercepción y autoconcepto.","c":"Patrón cognición y percepción.","d":"Patrón afrontamiento y tolerancia al estrés."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":289,"text":"Desde la perspectiva psicológica, ¿qué teoría explica la etiología de los trastornos depresivos como el resultado de un estilo cognitivo alterado que surge a partir de hipótesis aprendidas en la infancia, relacionadas con experiencias de decepción, pérdida o rechazo, y que conduce a expectativas negativas persistentes sobre uno mismo, el mundo y el futuro?","options":{"a":"Teoría psicodinámica","b":"Teoría cognitiva","c":"Teoría conductista","d":"Teoría del déficit motivacional adquirido"},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":290,"text":"Durante la valoración de un paciente con sospecha de trastorno bipolar, la enfermera identifica un período de estado de ánimo anormal y persistentemente elevado. ¿Cuál de los siguientes conjuntos de manifestaciones clínicas es más característico de un episodio maníaco?","options":{"a":"Ánimo deprimido, anhedonia, hipersomnia y sentimientos de inutilidad.","b":"Estado de ánimo elevado, disminución de la necesidad de dormir, verborrea y aumento de la actividad dirigida a objetivos.","c":"Irritabilidad leve, fatiga, enlentecimiento psicomotor y dificultad de concentración.","d":"Ansiedad persistente, insomnio inicial, preocupación excesiva y síntomas somáticos."},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":291,"text":"Durante la valoración de un paciente con trastorno bipolar, la enfermera debe diferenciar un episodio hipomaníaco de un episodio maníaco. ¿Cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"La hipomanía cursa con síntomas psicóticos, mientras que la manía no los presenta.","b":"En la hipomanía existe un deterioro social y laboral grave que suele requerir hospitalización.","c":"La manía implica un estado de ánimo elevado o irritable de mayor duración y gravedad, con deterioro funcional significativo o necesidad de hospitalización.","d":"La diferencia principal entre hipomanía y manía es exclusivamente la edad de inicio del episodio."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":292,"text":"En relación a los criterios diagnósticos de los subtipos del trastorno bipolar, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"Trastorno bipolar I: se caracteriza por la presencia de, al menos, un episodio maníaco, independientemente de que existan o no episodios depresivos mayores.","b":"Trastorno bipolar II: se define por la alternancia de episodios maníacos y episodios hipomaníacos sin depresión mayor.","c":"Trastorno bipolar III: incluye episodios depresivos recurrentes con activación maniforme inducida exclusivamente por antidepresivos.","d":"Trastorno bipolar IV: se diagnostica cuando existen síntomas subclínicos de manía asociados a trastornos de ansiedad crónico."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":293,"text":"Durante la valoración enfermera, un paciente refiere pensamientos constantes de catástrofe, anticipa resultados negativos ante situaciones cotidianas y expresa dificultad para concentrarse. Además, durante la entrevista se observa inquietud motora, tensión muscular y conductas de evitación ante determinadas situaciones. ¿Cuál de las siguientes opciones identifica de forma más adecuada los sistemas de respuesta predominantes en este caso?","options":{"a":"Componente emocional y componente interpersonal.","b":"Componente fisiológico y componente afectivo.","c":"Componente cognitivo y componente conductual.","d":"Componente neurovegetativo y componente perceptivo."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":294,"text":"¿Cuál de las siguientes NO es un principio de manejo general en la atención enfermera a pacientes con trastornos de ansiedad?","options":{"a":"Minimizar la ansiedad del paciente cuando no exista un motivo clínico objetivable que la justifique.","b":"Aceptar inicialmente las estrategias de afrontamiento del paciente, aunque no sean las más adaptativas.","c":"Proporcionar feedback al paciente sobre su conducta, las estrategias que utiliza y los factores de estrés identificados.","d":"Evitar que el paciente se aísle completamente durante el proceso asistencial."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":295,"text":"Durante la valoración de una paciente con sospecha de anorexia nerviosa, la enfermera identifica varias manifestaciones clínicas compatibles con este trastorno. ¿Cuál de las siguientes manifestaciones es MÁS característica de la anorexia nerviosa, según la clínica descrita?","options":{"a":"Episodios recurrentes de atracones seguidos de conductas purgativas repetidas.","b":"Restricción alimentaria mantenida con preocupación intensa por el peso corporal y necesidad de control.","c":"Sensación persistente de saciedad precoz acompañada de evitación progresiva de la ingesta.","d":"Conductas alimentarias impulsivas asociadas a estados emocionales fluctuantes."},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":296,"text":"En relación con el pronóstico de la anorexia nerviosa, señale cuál de los siguientes factores se asocia a una evolución MÁS DESFAVORABLE:","options":{"a":"Detección temprana del trastorno.","b":"Índice de masa corporal superior a 17 en el momento del seguimiento.","c":"Adecuada motivación para el cambio.","d":"Persistencia prolongada de la enfermedad con recaídas repetidas."},"correct":"d","disputed":false,"topic":"Urgencias y Emergencias"},{"num":297,"text":"En relación con la evolución reciente del consumo y la demanda de sustancias adictivas en Euskadi, según el VIII Plan de Adicciones, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"En la población adolescente se observa un descenso generalizado del consumo de todas las sustancias, incluido el alcohol y el cannabis, acompañado de una menor aceptación social.","b":"El consumo de tabaco muestra una tendencia descendente en todos los grupos de edad, siendo el nivel educativo un factor poco relevante en su prevalencia.","c":"El consumo de alcohol se mantiene en niveles muy elevados y socialmente normalizados, con mayor consumo en hombres adultos, aunque sin un patrón claro de desigualdad social en el consumo actual.","d":"La pandemia de la COVID-19 no tuvo un impacto significativo en los consumos, pero sí redujo de forma notable el uso de videojuegos, internet y redes sociales."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":298,"text":"Según los datos recogidos en el VIII Plan de Adicciones de Euskadi, en relación con la venta de alcohol por habitante, ¿cuál fue el consumo aproximado en litros por persona en el año 2020?","options":{"a":"18,6 litros por habitante y año.","b":"28,4 litros por habitante y año.","c":"48,2 litros por habitante y año.","d":"62,8 litros por habitante y año."},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":299,"text":"En el marco conceptual del VIII Plan de Adicciones de Euskadi, ¿cuál de los siguientes elementos se considera un determinante estructural del desarrollo de las adicciones?","options":{"a":"Estrategias individuales de afrontamiento del estrés.","b":"Entorno familiar.","c":"Políticas fiscales y de regulación de la oferta de sustancias.","d":"Habilidades personales para la toma de decisiones."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":300,"text":"En relación con los agentes implicados en el desarrollo del VIII Plan sobre Adicciones de Euskadi, señale cuál de las siguientes entidades NO forma parte de la estructura institucional del plan.","options":{"a":"Comisión Europea.","b":"Osakidetza.","c":"Diputaciones forales.","d":"Entidades del tercer sector y agentes sociales."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":301,"text":"En relación con el marco normativo estatal vinculado a la prevención, tratamiento y mitigación de las adicciones en el Estado español, indique cuál de las siguientes normas NO está directamente relacionada con este ámbito.","options":{"a":"Ley 14/1995, de 25 de abril, General de Sanidad.","b":"Ley 28/2005, de 26 de diciembre, de medidas sanitarias frente al tabaquismo.","c":"Ley 33/2011, de 4 de octubre, General de Salud Pública.","d":"Real Decreto 579/2017, de 9 de junio, por el que se regulan determinados aspectos relativos a la fabricación, presentación y comercialización de los productos del tabaco y los productos relacionados."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":302,"text":"Según el VIII Plan sobre Adicciones de Euskadi, el plan se alinea de manera explícita con varios Objetivos de Desarrollo Sostenible (ODS). Indique cuál de los siguientes ODS NO se encuentra alineado de forma directa con dicho plan:","options":{"a":"Objetivo 5: Igualdad de género.","b":"Objetivo 8: Trabajo decente y crecimiento económico.","c":"Objetivo 10: Reducción de las desigualdades.","d":"Objetivo 17: Alianzas para lograr los objetivos."},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":303,"text":"Según los datos recogidos en el VIII Plan sobre Adicciones de Euskadi 2023- 2027, en relación con la evolución y características del consumo de tabaco y cigarrillos electrónicos, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"Cerca de dos tercios de la población fumadora habitual consume más de medio paquete diario, lo que refleja una intensidad de consumo elevada pese a la tendencia general al descenso.","b":"Aproximadamente un 5 % de las personas fumadoras declara consumir más de un paquete de tabaco al día, concentrándose este patrón en los consumos más intensivos.","c":"En la población joven se observa una tendencia ascendente en el uso de cigarrillos electrónicos, con alrededor del 15 % del alumnado que ha fumado o utilizado alguno al menos una vez.","d":"La edad de inicio en el consumo de tabaco, se mantiene más o menos estable alrededor de los 15 años."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":304,"text":"Según los datos del VIII Plan sobre Adicciones de Euskadi 2023-2027, en relación con el consumo de alcohol, señale la opción que describe de forma MÁS AJUSTADA la situación epidemiológica actual en Euskadi:","options":{"a":"La mayor prevalencia de consumo habitual se concentra en la población adolescente (15-19 años), con diferencias marcadas entre sexos.","b":"Más del 20 % de la población reconoce haberse emborrachado entre 1 y 12 veces en el último año, siendo este patrón más frecuente en mujeres jóvenes de 15-24 años.","c":"La edad media de inicio del consumo de alcohol ha descendido progresivamente desde 2004 hasta 2018, situándose entre los 16 y 17 años.","d":"El consumo habitual de alcohol es significativamente mayor en mujeres que en hombres en todos los grupos de edad adulta."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":305,"text":"Respecto al consumo experimental de cocaína, anfetaminas y otras drogas estimulantes asociadas a contextos de ocio en Euskadi, señale la opción CORRECTA:","options":{"a":"El inicio del consumo se asocia principalmente a una alta percepción de riesgo y a contextos de exclusión social.","b":"El perfil de las personas consumidoras recientes es mayoritariamente femenino, menor de 25 años y con bajo nivel socioeconómico.","c":"El consumo reciente se relaciona con el consumo de cannabis, la cercanía a personas consumidoras y el consumo diario de tabaco, junto con una baja percepción de riesgo.","d":"La edad de inicio ha descendido de forma significativa en la última década y es más temprana en los hombres."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":306,"text":"En relación con el juego con dinero y el juego problemático en Euskadi, según los datos disponibles, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"Más del 70% de la población jugó con dinero en el último año, con porcentajes similares entre hombres y mujeres.","b":"El juego problemático afecta a porcentajes similares de hombres y mujeres, con una prevalencia patológica cercana al 5%.","c":"El juego con dinero es más frecuente en mujeres que en hombres y se asocia a menor gasto medio.","d":"La mayoría de las personas jóvenes se inicia en el juego de forma individual y en edad adulta."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":307,"text":"En relación con el uso de videojuegos y tecnologías digitales entre adolescentes en Euskadi, según los datos más recientes disponibles, ¿cuál de las siguientes afirmaciones es CORRECTA?","options":{"a":"El 10% de los adolescentes refiere haber recibido un mensaje de contenido sexual.","b":"Desde la aparición del Smartphone el uso de videojuegos es marginal, ya que más de la mitad de los adolescentes declara no jugar nunca.","c":"El riesgo principal asociado al uso de tecnologías digitales es el ciberacoso, con una prevalencia superior al 30%."},"correct":"a","disputed":false,"topic":"Urgencias y Emergencias"},{"num":308,"text":"Según la evidencia recogida en el VIII Plan sobre Adicciones de Euskadi, ¿cuál de las siguientes intervenciones en el ámbito comunitario presenta el MAYOR nivel de eficacia?","options":{"a":"Campañas de comunicación en medios tradicionales.","b":"Intervenciones breves o entrevistas motivacionales.","c":"Mentoría o intervención de pares.","d":"Intervenciones con mujeres embarazadas en la comunidad."},"correct":"b","disputed":false,"topic":"Urgencias y Emergencias"},{"num":309,"text":"La Organización Mundial de la salud, cuenta con un marco de trabajo de categorías clínicas de clasificación y fases de afección por VIH para adultos y mayores de 15 años. Corresponde a la fase clínica 4:","options":{"a":"Recuento de linfocitos CD4 (>500 células/μl).","b":"Individuos con herpes zóster, pérdida ponderal moderada inexplicable (<10%del peso corporal asumido) o queilitis angular.","c":"Individuos con síndrome de desgaste por VIH, neumonía por Pneumocystis jiroveci, neumonía bacteriana recurrente, el herpes simple, la tuberculosis extrapulmonar o la candidiasis esofágica.","d":"Individuos con diarrea crónica inexplicable con duración superior a un mes, la pérdida ponderal intensa inexplicable (>10% del peso corporal asumido) o la fiebre persistente inexplicable con duración mayor de un mes (>37,6 °C)."},"correct":"c","disputed":false,"topic":"Urgencias y Emergencias"},{"num":310,"text":"Desde el punto de vista enfermero, el sida es evidente cuando una persona presenta:","options":{"a":"Conteo de células CD4+ inferior a 200 células/μl.","b":"Padece alguna enfermedad definitoria de sida.","c":"a) y b) son incorrectas.","d":"a) y b) son correctas."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":311,"text":"¿Cuál de las siguientes infecciones oportunistas es la causa más frecuente de muerte en personas con VIH?","options":{"a":"Mycobacterium tuberculosis.","b":"Neumonía por Pneumocystis jirovecii.","c":"Mycobacterium avium-intracellulare.","d":"Bartonelosis."},"correct":"a","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":312,"text":"Una mujer de 29 años acude a su primera consulta con 10 semanas de embarazo. Se la ha realizado un aprueba con resultado de VIH positivo. ¿Qué debe hacer para disminuir el riesgo de transmisión de VIH a su hijo/a?","options":{"a":"Prepararse para la lactancia materna, ya que es un factor de protección.","b":"Iniciar inmediatamente el tratamiento antirretroviral con efavirenz.","c":"Iniciar inmediatamente el tratamiento antirretroviral con zidovudina.","d":"Esperar al momento de trabajo del parto para iniciar el tratamiento antirretroviral."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":313,"text":"Entre las causas de resultado negativo falso en el test de ELISA para VIH, esta:","options":{"a":"Trastornos hematológicos malignos.","b":"Tratamiento inmunosupresor.","c":"Trastornos autoinmunitarios.","d":"Transferencia pasiva de anticuerpos contra el VIH (madre a hijo)."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":314,"text":"La mejor alternativa para evitar infecciones por VIH y otras enfermedades de transmisión sexual es:","options":{"a":"Profilaxis preexposición (PrEP) para el VIH.","b":"La abstinencia y las relaciones monógamas entre personas sin infección.","c":"Uso sistemático y correcto de preservativos (masculinos o femeninos).","d":"Realización periódica de pruebas de VIH y otras ETS."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":315,"text":"¿Qué intervención enfermera es fundamental para prevenir infecciones oportunistas en personas con VIH?","options":{"a":"Vacunación antineumocócica una vez, tan pronto como sea posible, después del diagnóstico de la infección por VIH, y luego cada 5 años.","b":"Vacunación contra la influenza debe aplicarse cada 2 años.","c":"Vacunación con virus vivos anualmente.","d":"Vacunación contra sarampión, parotiditis y rubeola en personas asintomáticas y conteos de células CD4+ superiores a 200 células/μl."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":316,"text":"¿Qué son los factores de virulencia?","options":{"a":"Son los mecanismos de defensa del huésped que se activan frente a la infección para limitar la proliferación del microorganismo.","b":"Son sustancias o productos generados por los agentes infecciosos que potencian su capacidad para producir enfermedad.","c":"Son sustancias producidas por el organismo humano para neutralizar toxinas bacterianas.","d":"Son los factores ambientales que favorecen la transmisión de los microorganismos entre individuos."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":317,"text":"Es una inmunoglobulina secretora y su función principal es la inmunidad local en las superficies mucosas:","options":{"a":"IgG.","b":"IgM.","c":"IgD.","d":"IgA."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":318,"text":"El microorganismo aerobio que coloniza el intestino grueso con mayor frecuencia provocando enfermedades diarreicas es:","options":{"a":"Escherichia coli.","b":"Shigella.","c":"Salmonella.","d":"Campylobacter"},"correct":"a","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":319,"text":"Usted es parte del personal de enfermería que atiende a un varón de 75 años con múltiples afecciones en su domicilio. ¿Qué información debe proporcionar para prevenir el riesgo de infección al paciente, su familia y su cuidador?","options":{"a":"Asegurar de que los platos y vasos se laven con agua fria para que sean seguros de utilizar.","b":"Las sábanas y ropa del paciente, deben lavarse con ciclos programados en 30º.","c":"Establecer barreras razonables para evitar la transmisión de infecciones.","d":"Cocinar todos los alimentos por completo y almacenar lo a fruta y verdura separados de los otros grupos de alimentos."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":320,"text":"¿Cuál es el periodo de incubación del virus del Ébola?","options":{"a":"2-7 días.","b":"2-12 días.","c":"2-21 días","d":"24-72h"},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":321,"text":"En el contexto de las precauciones de aislamiento, según el Manual INOZ, ¿en cuál de las siguientes situaciones está más indicada la habitación individual como medida prioritaria para prevenir la transmisión por contacto directo o indirecto?","options":{"a":"En pacientes infectados por el mismo microorganismo.","b":"En pacientes con microorganismos epidemiológicamente importantes o de alta transmisibilidad, la habitación individual es prescindible si el paciente colabora correctamente con las medidas.","c":"En pacientes fuente con hábitos higiénicos pobres, que contaminan el medio ambiente o en quienes no puede esperarse colaboración en el mantenimiento de las medidas.","d":"En pacientes con transmisión por gotas, dado que se requieren medidas estructurales específicas."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":322,"text":"Durante una aspiración de secreciones orofaríngeas, ¿qué equipo de protección está indicado si se prevé la posibilidad de generar salpicaduras o sprays?","options":{"a":"Doble mascarilla y protección ocular.","b":"Guantes y mascarilla.","c":"Bata y mascarilla.","d":"Mascarilla y gafas o protector facial."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":323,"text":"Según el Manual INOZ, respecto al manejo de lencería, utensilios de comida y limpieza ambiental en pacientes con Precauciones Basadas en la Transmisión, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Aunque la lencería pueda estar contaminada, el riesgo de transmisión se evita si se maneja, transporta y lava adecuadamente; el lavado de los utensilios con agua caliente y detergentes usados en los lavaplatos de los hospitales es suficiente.","b":"En habitaciones con Precauciones Basadas en la Transmisión debe realizarse siempre una limpieza distinta a la de pacientes con Precauciones Estándar, usando productos desinfectantes específicos para todos los microorganismos.","c":"La lencería usada debe esterilizarse antes de su transporte y los utensilios del paciente en aislamiento deben ser exclusivamente desechables.","d":"La lencería utilizada requiere un manejo cuidadoso para evitar contaminación y los platos/utensilios del paciente deben eliminarse como residuos biosanitarios."},"correct":"a","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":324,"text":"La habitación de todo paciente con infección respiratoria de transmisión aérea, como tuberculosis o sarampión, deberá reunir las siguientes características:","options":{"a":"Habitación individual con vestíbulo, presión positiva respecto a áreas adyacentes y un mínimo de 8 renovaciones de aire a la hora.","b":"Habitación individual sin vestíbulo con extracciones de aire, filtros de alta eficacia (HEPA) y presión positiva respecto a áreas adyacentes.","c":"Habitación individual con vestíbulo, extracciones de aire, filtros de alta eficacia (HEPA) y un mínimo de 8 renovaciones de aire a la hora.","d":"Habitación individual con extracciones de aire, filtros de alta eficacia (HEPA) y un mínimo de 6 renovaciones de aire a la hora."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":325,"text":"Según la Guía-Manual de Uso Adecuado de los Guantes Sanitarios de Osakidetza, ¿en cuál de las siguientes situaciones NO es obligatorio el uso de guantes, siendo suficiente la higiene de manos?","options":{"a":"Realización de curas de heridas abiertas.","b":"Obtención de muestras sanguíneas por venopunción.","c":"Ajuste de la fluidoterapia intravenosa.","d":"Manipulación de material contaminado con fluidos biológicos."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":326,"text":"En relación con el agente infeccioso dentro de la cadena epidemiológica, ¿qué característica se define como la capacidad del microorganismo para producir enfermedad clínica una vez que el huésped ha sido infectado?","options":{"a":"Infectividad.","b":"Transmisibilidad.","c":"Patogenicidad.","d":"Virulencia."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":327,"text":"En relación con el concepto de inmunidad de grupo o inmunidad de rebaño, señale la afirmación correcta:","options":{"a":"Se alcanza únicamente cuando el 100% de la población está inmunizada frente a una enfermedad infecciosa.","b":"Impide la propagación epidémica gracias a un nivel elevado, aunque incompleto, de inmunización poblacional.","c":"Consiste en la protección individual exclusiva de las personas vacunadas.","d":"Solo es efectiva en enfermedades de transmisión no respiratoria."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":328,"text":"En relación con las medidas no farmacológicas para reducir el riesgo de transmisión del SARS-CoV-2 en la comunidad, señale la opción INCORRECTA:","options":{"a":"Mantener una distancia mínima aproximada de 2 metros contribuye a disminuir el riesgo de contagio.","b":"Evitar espacios cerrados y concurridos reduce la probabilidad de transmisión aérea.","c":"Los entornos ruidosos, donde es necesario elevar la voz, favorecen la emisión de aerosoles infecciosos.","d":"En espacios cerrados, el uso adecuado de mascarilla permite flexibilizar el mantenimiento estricto de la distancia interpersonal cuando existe una ventilación adecuada."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":329,"text":"Los factores de virulencia son sustancias o productos generados por los agentes infecciosos que potencian su capacidad para producir enfermedad. En relación con los factores de virulencia, señale cuál de las siguientes opciones NO constituye uno de sus principios fundamentales:","options":{"a":"Factores de resistencia antimicrobiana.","b":"Factores de invasión.","c":"Factores de adhesión.","d":"Factores de evasión."},"correct":"a","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":330,"text":"En relación con la cadena epidemiológica de la infección, señale cuál de las siguientes opciones recoge correctamente sus seis elementos fundamentales:","options":{"a":"Agente infeccioso, reservorio, puerta de salida, vía de transmisión, huésped susceptible, estado inmunitario.","b":"Agente infeccioso, reservorio, puerta de salida, vía de transmisión, huésped susceptible, puerta de entrada.","c":"Agente infeccioso, reservorio, puerta de salida, vía de transmisión, periodo de incubación, puerta de entrada.","d":"Agente infeccioso, reservorio, respuesta inflamatoria, vía de transmisión, huésped susceptible, puerta de entrada."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":331,"text":"En relación con la colocación del Equipo de Protección Individual por parte del personal de enfermería ante pacientes con enfermedades transmisibles, señale el orden correcto de colocación:","options":{"a":"Guantes → mascarilla → bata → protección ocular.","b":"Bata → mascarilla → protección ocular → guantes.","c":"Mascarilla → guantes → bata → protección ocular.","d":"Mascarilla → protección ocular → guantes → bata."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":332,"text":"Durante la actuación de la enfermera en el área quirúrgica, el mantenimiento del campo estéril es fundamental para prevenir infecciones del sitio quirúrgico. En relación con los principios de asepsia quirúrgica, señale la opción INCORRECTA:","options":{"a":"Utilizar únicamente material esterilizado en contacto con la herida quirúrgica.","b":"Considerar estériles las mangas de la bata quirúrgica desde aproximadamente 5 cm por encima del codo hasta el puño.","c":"Mantener el campo estéril permanentemente dentro del campo visual.","d":"Mantener una distancia de al menos 15 cm respecto al campo estéril."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":333,"text":"¿Cuál de las siguientes manifestaciones clínicas es más característica del golpe de calor y permite diferenciarlo del agotamiento o los calambres por calor?","options":{"a":"Diaforesis profusa, piel de gallina y calambres musculares en extremidades.","b":"Cefalea, ansiedad, síncope y ortostasis con temperatura elevada.","c":"Disfunción profunda del sistema nervioso central, piel caliente y seca, y temperatura corporal ≥ 40,6 ºC.","d":"Sed intensa, calambres musculares localizados y diaforesis profusa."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":334,"text":"¿Qué afirmación NO es correcta respecto a la valoración enfermera de pacientes con dolor torácico?","options":{"a":"La intensidad del dolor es el principal predictor de la gravedad del cuadro.","b":"La localización del dolor no permite identificar con precisión su etiología.","c":"La intensidad y la duración del dolor torácico no permiten predecir la gravedad del proceso.","d":"En la valoración enfermera es fundamental explorar síntomas asociados como náuseas, sudoración o disnea."},"correct":"a","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":335,"text":"Ante un paciente con sospecha de accidente cerebrovascular agudo que presenta disminución del nivel de conciencia, ¿cuál debe ser la prioridad inicial de la actuación enfermera en el ámbito de urgencias?","options":{"a":"Iniciar la reposición de líquidos hipotónicos para mejorar la perfusión cerebral.","b":"Valorar de forma inmediata la permeabilidad de la vía respiratoria y el estado cardiovascular.","c":"Administrar sedación para reducir la ansiedad y prevenir el aumento del consumo de oxígeno cerebral.","d":"Posicionar al paciente en decúbito supino estricto y administrar oxígeno a alto flujo."},"correct":"b","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":336,"text":"¿Cuál de las siguientes manifestaciones clínicas es característica de un ictus hemisférico derecho?","options":{"a":"Comportamiento lento y cauteloso, parálisis o debilidad del lado izquierdo del cuerpo y tendencia a distraerse.","b":"Alteración de la capacidad intelectual, déficit del campo visual izquierdo y déficits en la percepción espacial.","c":"Parálisis del lado izquierdo del cuerpo, alteración de la percepción espacial y comportamiento impulsivo.","d":"Afasia de expresión o recepción, parálisis del lado izquierdo del cuerpo, déficits del campo visual izquierdo."},"correct":"c","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":337,"text":"Señale la respuesta INCORRECTA en relación con la respuesta fisiológica inmediata del organismo tras un traumatismo múltiple.","options":{"a":"La mortalidad en los individuos con traumatismos múltiples se relaciona con la gravedad de las lesiones y el número de sistemas y órganos afectados.","b":"Los objetivos terapéuticos son determinar la extensión de las lesiones y establecer prioridades de tratamiento.","c":"Las prioridades iniciales en el tratamiento del paciente politraumatizado se centran en asegurar la ventilación y controlar la hemorragia como amenazas vitales inmediatas.","d":"Inmediatamente después de la lesión, el cuerpo se encuentra hipermetabólico, con disminución de la activación de la coagulación y sometido a una intensa respuesta al estrés."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":338,"text":"Señale la respuesta correcta en relación con el shock y su fisiopatología inicial.","options":{"a":"El shock se caracteriza por una perfusión tisular adecuada, con aumento del aporte de oxígeno a los tejidos para compensar la agresión inicial.","b":"En la fase inicial del shock se produce una disminución del metabolismo celular que protege a los órganos frente al daño tisular.","c":"La alteración principal en el shock es exclusivamente la disminución de la presión arterial, sin repercusión celular significativa en fases precoces.","d":"El shock es un estado de hipoperfusión tisular generalizada que conduce a hipoxia celular, metabolismo anaerobio y acidosis metabólica."},"correct":"d","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":339,"text":"Señale la respuesta correcta en relación con la persona en situación de hipotermia.","options":{"a":"En la hipotermia moderada y grave pueden aparecer bradicardia, hipotensión, hipoxemia y disminución del nivel de conciencia.","b":"La hipotermia se define como una temperatura corporal central inferior a 36ºC y cursa inicialmente con vasodilatación periférica y disminución de la sudoración.","c":"Los métodos de recalentamiento activo interno se usan para la hipotermia leve a moderada e incluyen derivación cardiopulmonar, administración de líquidos intravenosos calientes y oxígeno caliente humectado, entre otros.","d":"La hipotermia se asocia habitualmente a alteraciones en el ritmo cardíaco, en especial a la Actividad Eléctrica Sin Pulso."},"correct":"a","disputed":false,"topic":"Enfermedades Infecciosas"},{"num":340,"text":"¿Cuál es la intervención terapéutica prioritaria en la intoxicación por monóxido de carbono?","options":{"a":"Administrar aire ambiente y reposo absoluto, dado que el monóxido de carbono se elimina espontáneamente.","b":"Administrar oxígeno al 100% a presión atmosférica o de preferencia hiperbárica según cifras de carboxihemoglobina.","c":"Iniciar fluidoterapia intravenosa como tratamiento principal de la hipoxia tisular.","d":"Administrar oxígeno a bajo flujo mediante gafas nasales, ajustando la fracción inspirada según la saturación obtenida por pulsioximetría."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":341,"text":"¿Cuáles son signos y síntomas específicos que pueden indicar riesgo de suicidio potencial en una persona atendida en el ámbito sanitario?","options":{"a":"Expresión de ansiedad leve y preocupación situacional transitoria.","b":"Presencia de insomnio y llanto reactivo ante acontecimientos vitales estresantes recientes.","c":"Conducta retraída acompañada de tristeza persistente, sin verbalización de ideas relacionadas con la muerte.","d":"Pérdida de un padre a temprana edad y antecedentes familiares de suicidio."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":342,"text":"¿Cuál de las siguientes afirmaciones es correcta en relación con el infarto agudo de miocardio (IAM) y su manejo inicial?","options":{"a":"Desde el punto de vista fisiopatológico, el IAM se produce fundamentalmente por un espasmo coronario reversible sin necrosis miocárdica asociada.","b":"El tratamiento inicial del IAM se basa en la administración de líquidos intravenosos de forma sistemática para mejorar la perfusión coronaria.","c":"El paciente con sospecha de IAM debe recibir inmediatamente oxígeno suplementario, ácido acetilsalicílico, nitroglicerina y morfina.","d":"El tratamiento trombolítico presenta contraindicaciones absolutas, como el antecedente de ictus isquémico, anomalía de la coagulación conocida o la hipertensión no controlada."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":343,"text":"Señale la afirmación correcta en relación con la respuesta fisiopatológica de la persona con quemadura grave.","options":{"a":"Las quemaduras graves ocasionan un estado hipermetabólico con aumento del consumo de oxígeno y glucosa y una circulación hiperdinámica.","b":"Las quemaduras graves producen una disminución mantenida de la permeabilidad capilar, lo que favorece la retención de líquidos en el espacio intravascular.","c":"La respuesta fisiopatológica a las quemaduras graves se limita al tejido cutáneo lesionado y no tiene repercusión sistémica relevante.","d":"En las quemaduras graves no se producen alteraciones metabólicas significativas durante las primeras fases tras la lesión."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":344,"text":"En un paciente politraumatizado con antecedente de lesión por aplastamiento, ¿cuál de las siguientes manifestaciones NO forma parte de la tríada clínica característica de la rabdomiólisis?","options":{"a":"Mialgias.","b":"Debilidad muscular.","c":"Orina oscura.","d":"Edema muscular."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":345,"text":"En el centro de la rueda del cambio de comportamiento de Michie et al., encontramos:","options":{"a":"La capacidad, la motivación y la oportunidad.","b":"La capacidad, la modelización y la oportunidad.","c":"La capacidad, la motivación y la educación.","d":"La capacidad, la modelización y la regulación."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":346,"text":"Entre los métodos o técnicas educativas orientadas al aprendizaje de contenidos, se distinguen aquellas de carácter bidireccional. ¿Cuál de las siguientes opciones corresponde a técnicas destinadas al desarrollo de habilidades?","options":{"a":"Carteles, vallas, folletos, cartas circulares, prensa…","b":"Tormenta de ideas, foto-palabra, dibujo-palabra….","c":"Casos, análisis de textos, discusiones, sesión de tribunal…","d":"Ejercicios y simulaciones, tales como role-playing…"},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":347,"text":"No corresponde a un factor sobre el que planea incidir la Estrategia de Promoción de la Salud y Prevención en el Sistema Nacional de Salud:","options":{"a":"Alimentación saludable.","b":"Seguridad del entorno para prevenir lesiones no intencionales.","c":"Actividad física.","d":"Enfermedades de transmisión sexual."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":348,"text":"Una herramienta para la promoción de la salud en el nivel comunitario es el modelo de activos para la salud. ¿En que se basa este modelo?","options":{"a":"En la identificación de las capacidades de la comunidad de forma que estas sean empleadas como parte de un proceso de capacitación y participación.","b":"En una herramienta cooperativa de diagnóstico comunitario que identifica, localiza y visibiliza los recursos, fortalezas y capacidades existentes en un territorio histórico.","c":"En la identificación de las riquezas y pobrezas de la comunidad que generan salud entre sus integrantes a través de un proceso participativo y centrado en lo que nos hace estar sanos.","d":"En determinar las ubicaciones relativas de puntos de referencia o marcadores dentro de un cromosoma o genoma."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":349,"text":"¿Cuál es el tamaño idóneo para desarrollar procesos educativos de promoción para la salud a nivel grupal que puedan provocar un cambio de actitud?","options":{"a":"2 personas.","b":"Entre 2 y 9 personas.","c":"Entre 10 y 20 personas.","d":"Entre 21 y 30 personas."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":350,"text":"Entre las potencialidades del trabajo grupal en la promoción de la salud, encontramos:","options":{"a":"Aprovechamiento del recurso humano y material.","b":"Apoyo que las personas participantes se dan entre sí.","c":"Descubrimiento de que lo que viven es único.","d":"Ausencia de lazos afectivos entre participantes."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":351,"text":"NO es una característica asignada al papel de los profesionales sanitarios en promoción y educación para la salud:","options":{"a":"Mejorar el liderazgo y la gobernanza participativa para la salud.","b":"Mejorar la investigación.","c":"Impulsar estrategias encaminadas a conseguir que la salud se convierta en tema prioritario.","d":"Informar del estado de salud a individuos y comunidad."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":352,"text":"Señale la respuesta CORRECTA respecto a las principales etapas de la Evaluación del Impacto de la Salud.","options":{"a":"Screening: permite identificar si una política, un proyecto o un programa es relevante para la salud.","b":"Análisis: Permite identificar mapas de conexiones y definir los límites de los aspectos que van a ser valorados.","c":"Seguimiento: Cuantifica el impacto considerando la evidencia existente.","d":"Informar: Monitorizar y evaluar los impactos de la política para generar evidencia y favorecer su difusión."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":353,"text":"Se considera un consumo de riesgo moderado en función de la cantidad de alcohol consumido:","options":{"a":"Varones < 10 UBE/semana y Mujeres < 8 UBE/semana.","b":"Varones 10-17 UBE/semana y Mujeres 8-14 UBE/semana.","c":"Varones 17-28 UBE/semana y Mujeres 11-17 UBE/semana.","d":"Varones 18-32 UBE/semana y Mujeres 12-19 UBE/semana."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":354,"text":"A partir de la perspectiva del modelo salutogénico en la promoción de la salud, diversos autores han desarrollado el concepto de determinantes de la salud. ¿Cuál de los siguientes autores NO se asocia con este desarrollo?","options":{"a":"Lalonde.","b":"Diez Roux.","c":"Marmot.","d":"Brownson."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":355,"text":"En relación con la Evaluación de Impacto en Salud (EIS), señale la opción correcta:","options":{"a":"Prospectiva: identifica las consecuencias de las políticas ya implementadas","b":"Concurrente: analiza las consecuencias de una medida mientras se está implementando.","c":"Retrospectiva: identifica las consecuencias de una medida durante su implementación, especialmente cuando se sospecha un impacto negativo.","d":"Retrospectiva: predice los efectos de las políticas antes de su implementación."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":356,"text":"¿El concepto de Educación para la Salud según la OMS es?","options":{"a":"Una acción ejercida sobre los individuos para llevarles a modificar sus comportamientos.","b":"Es un proceso de enseñanza que busca capacitar a grupos de riesgo para adquirir conocimientos, desarrollar habilidades y adoptar actitudes que promuevan estilos de vida saludables y prevengan enfermedades, mejorando el bienestar físico, mental y social a través de la toma de decisiones informadas y la participación activa.","c":"Disciplina encargada de orientar y organizar procesos educativos con el propósito de influir positivamente en conocimientos, aptitudes y costumbres de individuos y comunidades en relación con su enfermedad.","d":"Proceso de enseñanza para mejorar conocimientos, habilidades y aptitudes que promueven la salud y la enfermedad."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":357,"text":"El término “inmunización” hace referencia a:","options":{"a":"La provisión de inmunidad artificial activa o pasiva.","b":"La producción endógena de anticuerpos tras vacunación.","c":"La inducción de inmunidad natural tras pasar una infección.","d":"Exclusivamente a la administración de vacunas."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":358,"text":"La inmunidad pasiva natural se adquiere principalmente por:","options":{"a":"Vacunación materna.","b":"Lactancia artificial.","c":"Paso transplacentario de IgG y lactancia materna (IgA).","d":"Exposición ambiental temprana."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":359,"text":"Una vacuna se define como:","options":{"a":"Solución que contiene anticuerpos obtenida a partir de sangre humana y utilizada para mantener la inmunidad en personas inmunodeficientes o para conseguir inmunización pasiva.","b":"Toxinas bacterianas modificadas, convertidas en no tóxicas, pero con capacidad de estimular la formación de antitoxinas.","c":"Cualquier molécula capaz de ser reconocida por un anticuerpo o receptor de célula T. Los antígenos de las vacunas suelen ser bacterias o virus que a su vez pueden ser atenuados (vivos) o inactivados (muertos). Pueden ser enteros o una parte de ellos.","d":"Suspensión de microorganismos vivos, atenuados o porciones antigénicas de dichos agentes, que, introducidos en un huésped, producen respuesta inmunitaria adaptativa (especificidad + memoria) para prevenir la enfermedad causada por dichos microorganismos."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":360,"text":"¿Cuál de las siguientes vacunas induce inmunidad sin memoria inmunológica?","options":{"a":"Vacunas conjugadas.","b":"Vacunas de ARNm.","c":"Vacunas de polisacáridos puros.","d":"Vacunas atenuadas."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":361,"text":"En lactantes, el lugar anatómico recomendado para la vacunación intramuscular es:","options":{"a":"Vasto externo del muslo.","b":"Deltoides.","c":"Glúteo.","d":"Región escapular."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":362,"text":"La congelación de una vacuna puede provocar:","options":{"a":"Aumento de su inmunogenicidad.","b":"Pérdida visible del color.","c":"Contaminación bacteriana.","d":"Inactivación irreversible."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":363,"text":"“Dosis puesta, dosis que cuenta” significa que:","options":{"a":"Se reinicia la pauta vacunal independientemente del tiempo transcurrido.","b":"Se tendrán en cuenta los intervalos mínimos entre dosis de una misma vacuna.","c":"Se contabilizan todas las dosis recibidas y que hayan respetado los intervalos mínimos.","d":"Conocer los intervalos entre vacunas, las pautas según edad y pautas aceleradas de algunas vacunas nos facilitará diseñar el calendario vacunal."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":364,"text":"¿Cuál es una contraindicación permanente para la vacunación?","options":{"a":"Enfermedad leve con o sin febrícula.","b":"Reacción anafiláctica previa a un componente.","c":"Lactancia materna.","d":"Tratamiento antibiótico."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":365,"text":"Tras la administración de tratamiento sustitutivo con inmunoglobulinas mediante hemoderivados, se recomienda diferir la administración de vacunas vivas atenuadas:","options":{"a":"Al menos 1 mes.","b":"Al menos 2 meses.","c":"Al menos 3 meses.","d":"Al menos 6 meses."},"correct":"c","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":366,"text":"¿Qué tipo de vacuna puede administrarse en las personas con inmunodeficiencias humorales que reciben inmunoglobulinas de forma periódica?","options":{"a":"Inactivadas.","b":"Oral.","c":"Intradérmica.","d":"Viva atenuada."},"correct":"a","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":367,"text":"La administración simultánea de vacunas:","options":{"a":"Reduce las probabilidades de inmunización.","b":"Puede administrarse en idénticos lugares anatómicos.","c":"Deben mezclarse vacunas distintas en la misma jeringa.","d":"Es segura y recomendable."},"correct":"d","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":368,"text":"Según el calendario vacunal infantil de Euskadi, ¿Que vacunas corresponde administrar a los 11 meses? Calendario vacunal eus 2026","options":{"a":"Hepatitis B, difteria, tétanos, tosferina, Hib, poliomielitis), neumococo conjugada,Meningococo (B) y rotavirus.","b":"Hepatitis B, difteria, tétanos, tosferina, Hib, poliomielitis), neumococo conjugada.","c":"Sarampion, Rubeola, Parotiditis y Meningococo (B,ACWY).","d":"Hepatitis B, difteria, tétanos, tosferina, Hib, poliomielitis), neumococo conjugada,Meningococo (B,ACWY) y rotavirus."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":369,"text":"El concepto de polimedicación se define como:","options":{"a":"El consumo de menos de cinco fármacos de forma concomitante.","b":"El consumo de cinco o más fármacos de forma concomitante.","c":"El consumo de ocho o más fármacos de forma concomitante.","d":"El consumo de diez o más fármacos de forma concomitante."},"correct":"b","disputed":false,"topic":"Traumatología, Geriatría y Cuidados Especiales"},{"num":370,"text":"¿Qué criterios propuestos por la Sociedad Europea de Geriatría son los más utilizados para detectar prescripciones potencialmente inapropiadas en personas mayores de 65 años?","options":{"a":"AGS Beers.","b":"LESS-CHRON.","c":"STOPP/START.","d":"IPEC."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":371,"text":"¿Cuál de las siguientes, NO forma parte de las cuatro enfermedades no transmisibles responsables de morbilidad y mortalidad en el mundo?","options":{"a":"Cardiovasculares.","b":"Cáncer.","c":"Diabetes.","d":"Osteoarticulares."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":372,"text":"El termino comorbilidad hace referencia a:","options":{"a":"Es la ocurrencia simultanea de dos patologías en la misma persona, sin tener en cuenta ni el orden jerárquico entre ellos ni su gravedad.","b":"Es la existencia de otras enfermedades en una persona que ya tiene una enfermedad que consideramos principal.","c":"Es la aparición de otras enfermedades en una persona que ya tiene una enfermedad que consideramos secundaria.","d":"Es la ocurrencia simultanea de múltiples problemas de salud en la misma persona, sin tener en cuenta ni el orden jerárquico entre ellos ni su gravedad."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":373,"text":"¿Es un método indirecto validado para medir la adherencia al tratamiento farmacológico?","options":{"a":"Test de Morisky-Green.","b":"El Indice internacional normalizado (INR).","c":"Hemoglobina glicosilada.","d":"Test de Hemingway."},"correct":"a","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":374,"text":"Es un requisito que deben cumplir las rutas asistenciales que se establezcan para la atención de pacientes crónicos.","options":{"a":"No tienen por qué ser consensuadas entre los dos niveles (Gestores y profesionales de la salud).","b":"Abordar aspectos globales de un proceso asistencial y no aspectos demasiado concretos.","c":"Que las rutas de coordinación sean claras y concisas, con capacidad de ser modificadas fácilmente.","d":"Mantener contactos pasivos con la enfermera referente del/ de la paciente."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":375,"text":"Es una de las cinco cualificaciones básicas con las que deben contar todos los profesionales que atienden a pacientes con problemas de salud crónicos:","options":{"a":"Comprensión emocional.","b":"Sociabilidad.","c":"Disposición al optimismo.","d":"Atención centrada en el paciente."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":376,"text":"¿Cuál de las siguientes NO es una enfermedad crónica frecuente en la infancia?","options":{"a":"Trastorno de déficit de atención por hiperactividad (TDAH).","b":"Fibrosis quística.","c":"Cardiopatía isquemica.","d":"Desnutrición."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":377,"text":"Un factor en las intervenciones en procesos crónicos es:","options":{"a":"Se priorizan intervenciones preventivas, proactivas y rehabilitadoras frente al enfoque curativo de la enfermedad aguda.","b":"Se centra la atención en las necesidades globales del paciente a corto plazo, más allá de lo exclusivamente clínico.","c":"Se requiere una atención coordinada e integral con “visión individuo “desde la atención primaria a lo largo de la enfermedad.","d":"Se realiza una valoración global de la persona, incidiendo en síntomas agudos e incidiendo en su contexto social y funcional."},"correct":"a","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":378,"text":"Es un modelo poblacional de referencia e intervención de atención a crónicos:","options":{"a":"Modelo de Atención a crónicos.","b":"Piramide de King´s Fund.","c":"Modelo de Atención Innovadora a condiciones crónicas.","d":"Pirámide de Pagoda."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":379,"text":"Señale la respuesta INCORRECTA en relación con la Pirámide de Kaiser:","options":{"a":"En los pacientes de mayor complejidad con frecuente comorbilidad se hace necesaria una gestión integral del caso en su conjunto, con cuidados fundamentalmente profesionales.","b":"Los pacientes de alto riesgo, pero de menor complejidad en lo que respecta a su comorbilidad reciben una gestión de la enfermedad que combina cuidados informales y cuidados profesionales.","c":"La mayoría de pacientes crónicos con condiciones todavía en estadios incipientes reciben apoyo para su autogestión.","d":"La población general es foco de intervenciones de prevención y promoción que tratan de controlar los factores de riesgo que puedan llevar a los individuos a la enfermedad crónica."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":380,"text":"Probablemente, la principal referencia internacional en el ámbito de la atención a las enfermedades crónicas es el Modelo de Atención a Crónicos. ¿Cuáles son los tres planos interrelacionados en los que se articula la atención a la cronicidad?","options":{"a":"La comunidad actúa como usuaria de los servicios, el sistema sanitario se organiza con proveedores y aseguramiento, y la interacción con el paciente que tiene impacto clínico.","b":"Las políticas comunitarias sustituyen al sistema sanitario formal, las organizaciones proveedoras desaparecen en favor de la autogestión, y la práctica clínica se desarrolla sin comunicación directa con el paciente.","c":"La comunidad con sus recursos públicos y privados determinan por completo las decisiones clínicas, el sistema sanitario aporta estructuras organizativas propias, y la interacción con el paciente en la asistencia sanitaria.","d":"La comunidad con sus políticas y múltiples recursos públicos y privados, el sistema sanitario con sus organizaciones proveedoras y esquemas de aseguramiento, y la interacción con el paciente en la práctica clínica."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":381,"text":"¿Cuál de las siguientes afirmaciones respecto a la absorción de los fármacos es INCORRECTA?","options":{"a":"La biodisponibilidad indica la cantidad de fármaco inalterado que alcanza la circulación sistémica y también la velocidad a la que lo hace.","b":"La administración intravenosa presenta una biodisponibilidad del 100%, ya que el fármaco llega directamente a la circulación sistémica.","c":"El metabolismo presistémico puede disminuir la cantidad de fármaco que alcanza la circulación sistémica.","d":"El grado de ionización, la liposolubilidad y el volumen de distribución del fármaco son factores influyentes en el grado de absorción de los fármacos."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":382,"text":"¿Cuál de las siguientes afirmaciones respecto a la eliminación renal de los fármacos es correcta?","options":{"a":"La filtración glomerular permite el paso del fármaco desde la sangre al filtrado glomerular; se filtran con mayor facilidad las moléculas hidrosolubles y de pequeño tamaño.","b":"La filtración glomerular se realiza mediante transporte activo y depende principalmente del pH urinario.","c":"La reabsorción tubular ocurre fundamentalmente por filtración y es independiente de la liposolubilidad del fármaco.","d":"La reabsorción tubular se produce únicamente en fármacos ionizados, ya que atraviesan mejor las membranas tubulares."},"correct":"a","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":383,"text":"Según la clasificación por frecuencia de aparición, ¿cuál de las siguientes afirmaciones sobre las reacciones adversas a medicamentos (RAM) es correcta?","options":{"a":"Una RAM frecuente es aquella que aparece en ≥1/1.000 y <1/100.","b":"Una RAM muy frecuente es aquella que aparece en ≥1/100 y <1/10.","c":"Una RAM rara es aquella que aparece en ≥1/10.000 y <1/1.000.","d":"Una RAM muy rara es aquella que aparece en ≥1/10.000 y <1/1.000."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":384,"text":"¿Cuál de las siguientes afirmaciones está relacionada con las reacciones adversas a medicamentos de tipo B?","options":{"a":"Se trata de reacciones cuyos efectos están relacionados con el mecanismo de acción del fármaco.","b":"No se relacionan con la acción farmacológica del medicamento y, por tanto, son imprevisibles.","c":"Se trata de reacciones que se producen como consecuencia de la administración prolongada y continua de un fármaco.","d":"Son reacciones adversas que aparecen algún tiempo después de la administración del medicamento."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":385,"text":"En España, la notificación espontánea de sospechas de reacciones adversas a medicamentos es obligatoria para profesionales sanitarios y laboratorios farmacéuticos, y voluntaria para los ciudadanos, según la normativa reguladora de farmacovigilancia. ¿Cuál de las siguientes opciones identifica correctamente el Real Decreto y su fecha?","options":{"a":"Real Decreto 577/2013, de 26 de julio de 2013.","b":"Real Decreto 577/2012, de 26 de julio de 2012.","c":"Real Decreto 557/2013, de 26 de junio de 2013.","d":"Real Decreto 577/2014, de 26 de julio de 2014."},"correct":"a","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":386,"text":"¿Cuál de los siguientes signos o síntomas NO se considera una reacción adversa medicamentosa de las que con mayor frecuencia aparecen en las bases de datos de farmacovigilancia?","options":{"a":"Hipotensión.","b":"Urticaria.","c":"Prurito.","d":"Ictericia."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":387,"text":"Respecto a la vía inhalatoria de administración de fármacos, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"Permite concentraciones elevadas en el lugar de acción y bajas en sangre.","b":"La absorción es rápida en los alvéolos por su alta permeabilidad e irrigación.","c":"Los fármacos pueden sufrir metabolismo presistémico.","d":"El mecanismo de absorción suele ser, mayoritariamente, por difusión pasiva para los fármacos hidrososolubles."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":388,"text":"Respecto a la excreción biliar y la circulación enterohepática de los fármacos, ¿cuál de las siguientes afirmaciones es correcta?","options":{"a":"Se eliminan por bilis fármacos de bajo peso molecular.","b":"La circulación enterohepática impide la reabsorción intestinal.","c":"La β-glucuronidasa bacteriana puede liberar fármaco activo desde metabolitos conjugados.","d":"Se reabsorben principalmente metabolitos conjugados sin modificación previa."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":389,"text":"En España, ¿cuál es el método de notificación de reacciones adversas a medicamentos más utilizado?","options":{"a":"Formulario electrónico de historias clínicas.","b":"Tarjeta amarilla.","c":"Registro de dispensación farmacéutica.","d":"Notificación a través del Centro Autonómico de Farmacovigilancia."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":390,"text":"Los medicamentos termolábiles requieren condiciones específicas de conservación para mantener su estabilidad y eficacia terapéutica. ¿Cuál es el rango de temperatura adecuado para la conservación de los medicamentos termolábiles?","options":{"a":"Entre 0 y 4 °C.","b":"Entre 2 y 8 °C.","c":"Entre 6 y 10 °C.","d":"Entre 8 y 12 °C."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":391,"text":"En relación con las revisiones periódicas de los lugares de almacenamiento de medicamentos en los centros sanitarios, señale la afirmación que NO es correcta:","options":{"a":"Comprobación de la adecuada conservación de los medicamentos en función de sus requerimientos térmicos y de protección frente a la luz.","b":"Revisión sistemática de las fechas de caducidad de los medicamentos almacenados.","c":"Establecimiento de un orden lógico de los medicamentos, ordenados alfabéticamente por nombre comercial.","d":"Verificación del adecuado almacenamiento de medicamentos sometidos a control especial, como los estupefacientes."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":392,"text":"En el manejo y conservación de los medicamentos termolábiles, el personal de enfermería debe tener en cuenta determinados aspectos para garantizar su estabilidad y eficacia terapéutica. ¿Cuál de las siguientes afirmaciones NO es correcta?","options":{"a":"El aumento de la temperatura puede acelerar el deterioro del medicamento y reducir su efectividad.","b":"Las temperaturas excesivamente bajas pueden provocar congelación y alteraciones físicas en algunos preparados.","c":"La ruptura de la cadena de frío puede favorecer la formación de productos tóxicos.","d":"La mayoría de los medicamentos termolábiles pueden permanecer durante varias horas a temperatura ambiente, hasta un máximo de 20 °C, sin perder sus propiedades fisicoquímicas."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":393,"text":"Una paciente ingresada en el servicio de urgencias precisa fluidoterapia intravenosa con suero fisiológico al 0,9 %, prescribiéndose un volumen total de 500 ml. ¿cuál es la cantidad total de cloruro sódico administrada en este volumen?","options":{"a":"2,25 gramos.","b":"3,5 gramos.","c":"4,5 gramos.","d":"9 gramos."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":394,"text":"En una consulta de atención primaria se prescribe una pomada dermatológica con una concentración del 5 % para el tratamiento de una dermatosis inflamatoria. Se dispensa un envase que contiene 20 g de pomada. ¿cuál es la cantidad de principio activo contenida en este envase?","options":{"a":"0,5 gramos.","b":"1 gramo.","c":"2 gramos.","d":"5 gramos."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":395,"text":"Se consideran soluciones isotónicas aquellas que pueden administrarse por vía venosa periférica sin producir flebitis significativa, al presentar una osmolaridad compatible con la del plasma. ¿Cuál de las siguientes soluciones se considera isotónica?","options":{"a":"160 mOsmol/l.","b":"420 mOsmol/l.","c":"690 mOsmol/l.","d":"870 mOsmol/l."},"correct":"b","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":396,"text":"En la práctica clínica, al elaborar una prescripción farmacológica es fundamental tener en cuenta determinados factores que pueden influir de manera significativa en la adherencia al tratamiento por parte del paciente. ¿Cuál de los siguientes factores NO se asocia habitualmente de manera directa con una disminución de la adherencia terapéutica?","options":{"a":"Bajo nivel educativo y analfabetismo.","b":"Dificultad de acceso a los centros sanitarios y elevado coste del transporte.","c":"Creencias culturales y percepciones erróneas sobre la enfermedad.","d":"Obesidad asociada a malos hábitos alimenticios."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":397,"text":"El Servicio Profesional Farmacéutico de Sistemas Personalizados de Dosificación en farmacia comunitaria consiste en la preparación individualizada de la medicación de pacientes, especialmente polimedicados, con el objetivo de mejorar la adherencia terapéutica y reducir errores en la administración. En relación con este servicio, señale la afirmación INCORRECTA:","options":{"a":"Puede ser solicitado por el médico prescriptor cuando detecta riesgo de incumplimiento terapéutico.","b":"Puede ser recomendado por el trabajador social en pacientes con dificultades de alfabetización.","c":"Únicamente el paciente o su familia pueden solicitar este servicio a la oficina de farmacia.","d":"Facilita la correcta administración de la medicación y contribuye a la mejora del cumplimiento terapéutico."},"correct":"c","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":398,"text":"En el contexto de la atención domiciliaria, el personal de enfermería desempeña un papel clave en la detección de errores en la administración de medicamentos. ¿Cuál de los siguientes conjuntos de estrategias resulta más adecuado para identificar dichos errores?","options":{"a":"Entrevista estructurada, demostraciones prácticas y supervisión de los registros de autoadministración.","b":"Revisión de la historia clínica, control analítico y ajuste farmacológico.","c":"Encuestas telefónicas, revisión administrativa y control del stock domiciliario.","d":"Observación directa, valoración nutricional y evaluación del entorno físico."},"correct":"a","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":399,"text":"La vía sublingual permite una rápida absorción del fármaco y evita el metabolismo hepático de primer paso, lo que incrementa su biodisponibilidad y rapidez de acción. ¿Cuál de las siguientes situaciones clínicas justifica preferentemente el uso de la vía sublingual?","options":{"a":"Paciente con infección respiratoria que precisa antibioterapia oral durante 10 días.","b":"Paciente con dolor abdominal funcional y episodios recurrentes de náuseas leves, en tratamiento sintomático.","c":"Paciente con artritis reumatoide en tratamiento inmunomodulador de mantenimiento.","d":"Paciente con dolor torácico de inicio súbito compatible con isquemia miocárdica y dificultad para la deglución."},"correct":"d","disputed":false,"topic":"Farmacología y Administración de Medicamentos"},{"num":400,"text":"En la administración de medicamentos por vía intramuscular en el paciente adulto, es fundamental seleccionar adecuadamente el área anatómica en función del volumen a administrar. ¿Cuál de las siguientes asociaciones entre zona de inyección intramuscular y volumen máximo recomendado es correcta?","options":{"a":"Área deltoidea: hasta 2,5 ml.","b":"Área ventroglútea: hasta 5 ml.","c":"Área dorsoglútea: hasta 8 ml.","d":"Área del vasto lateral externo: hasta 3 ml."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":401,"text":"En relación con la administración de medicamentos por vía intramuscular, determinadas condiciones clínicas pueden contraindicar su utilización debido al aumento del riesgo de complicaciones locales o sistémicas. ¿Cuál de las siguientes situaciones NO constituye una contraindicación habitual para la administración intramuscular?","options":{"a":"Trastornos de la coagulación.","b":"Edema importante en la zona de punción.","c":"Vasculopatía periférica.","d":"Panículo adiposo de gran espesor en la zona de inyección."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":402,"text":"Según la clasificación de los medicamentos peligrosos, establecida en función de su potencial riesgo para la salud, estos se agrupan en tres categorías principales:","options":{"a":"Grupo 1: fármacos con bajo riesgo toxicológico; Grupo 2: medicamentos de uso hospitalario; Grupo 3: fármacos de dispensación ambulatoria.","b":"Grupo 1: fármacos antineoplásicos; Grupo 2: fármacos no antineoplásicos que cumplen criterios del NIOSH; Grupo 3: fármacos con riesgo reproductivo.","c":"Grupo 1: medicamentos biológicos; Grupo 2: psicofármacos; Grupo 3: fármacos teratógenos.","d":"Grupo 1: fármacos de alto riesgo toxicológico; Grupo 2: medicamentos genéricos; Grupo 3: fármacos de uso restringido."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":403,"text":"En la administración de medicamentos por vía parenteral, el ángulo de inserción de la aguja varía en función de la vía utilizada, con el fin de garantizar una correcta deposición del fármaco y minimizar complicaciones. ¿Cuál de las siguientes asociaciones entre vía de administración y ángulo de inyección es correcta?","options":{"a":"Intradérmica: 10–15º / Subcutánea: 45–90º / Intramuscular: 90º.","b":"Intradérmica: 15-20º / Subcutánea: 35-45º / Intramuscular: 60-90º.","c":"Intradérmica: 10-15º / Subcutánea: 90º / Intramuscular: 45-90º.","d":"Intradérmica: 15-20º / Subcutánea: 45-60º / Intramuscular: 75-90º."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":404,"text":"En relación con el procedimiento adecuado para la administración de pomadas oftálmicas, señale la afirmación que NO es correcta:","options":{"a":"El paciente debe colocarse en posición sentada o en decúbito, con la cabeza ligeramente hacia atrás.","b":"Se debe retraer el párpado inferior para exponer el saco conjuntival.","c":"Tras la aplicación, se debe indicar al paciente que parpadee una o dos veces y mantenga posteriormente los ojos cerrados.","d":"Debe aplicarse aproximadamente una tira de 0,5 cm de pomada, evitando el contacto directo con la córnea."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":405,"text":"En relación con el Decreto 38/2012, de 13 de marzo, sobre historia clínica y derechos y obligaciones de pacientes y profesionales de la salud en materia de documentación clínica, señale qué normativa NO está relacionada ni resulta de aplicación directa en su desarrollo o marco jurídico:","options":{"a":"Ley 41/2002, de 14 de noviembre, básica reguladora de la autonomía del paciente.","b":"Ley Orgánica 15/1999, de 13 de diciembre, de Protección de Datos de Carácter Personal.","c":"Real Decreto 1093/2010, de 3 de septiembre, por el que se aprueba el conjunto mínimo de datos de los informes clínicos en el SNS.","d":"Ley 44/2003, de 21 de noviembre, de ordenación de las profesiones sanitarias."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":406,"text":"Según el artículo 7 del Decreto 38/2012, sobre la cumplimentación de la historia clínica, ¿cuál de las siguientes afirmaciones sobre las anotaciones subjetivas es CORRECTA?","options":{"a":"Son datos objetivos verificables mediante pruebas complementarias y deben ser accesibles siempre al paciente.","b":"Incluyen impresiones o valoraciones personales del profesional no sustentadas directamente en datos objetivos y pueden quedar claramente identificadas para facilitar su disociación.","c":"No deben constar en la historia clínica por afectar a la intimidad del paciente.","d":"Pueden incorporar expresiones o comentarios sin relación directa con la asistencia sanitaria si aportan contexto clínico."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":407,"text":"En relación con el acceso a la historia clínica según el Decreto 38/2012 y la normativa básica estatal, señale la opción CORRECTA:","options":{"a":"El acceso del paciente a su historia clínica es absoluto y no puede limitarse en ningún caso.","b":"Los profesionales sanitarios pueden acceder libremente a cualquier historia clínica del centro, con independencia de que intervengan o no en la asistencia del paciente.","c":"El acceso a la historia clínica debe limitarse a los fines específicos previstos legalmente, garantizando los derechos de la persona titular de los datos.","d":"La entrega de documentación clínica no requiere identificar a la persona solicitante ni justificar la finalidad del acceso, para facilitar la transparencia asistencial."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":408,"text":"En relación con el acceso a la historia clínica por personal sanitario con finalidad distinta a la asistencial y por terceras personas, según el Decreto 38/2012, señale la opción CORRECTA.","options":{"a":"El personal sanitario con funciones de inspección o evaluación puede acceder libremente a toda la historia clínica sin limitación de datos ni necesidad de justificar el acceso.","b":"El acceso a la historia clínica con fines de investigación exige siempre el consentimiento expreso de la persona paciente, sin excepciones.","c":"Las compañías aseguradoras privadas pueden acceder a la historia clínica completa del paciente para fines de facturación sin necesidad de consentimiento.","d":"El acceso a la historia clínica con fines de gestión, inspección o investigación debe limitarse a los datos imprescindibles y, como norma general, garantizar la disociación o anonimización de los datos identificativos."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":409,"text":"Según el Decreto 38/2012, ¿cuánto tiempo debe transcurrir desde el fallecimiento de la persona paciente para que pueda destruirse la totalidad de su documentación clínica?","options":{"a":"Cinco años desde el fallecimiento.","b":"Diez años desde el fallecimiento.","c":"Quince años desde el fallecimiento.","d":"La documentación clínica no puede destruirse tras el fallecimiento."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":410,"text":"Según el Decreto 38/2012, antes de otorgar el consentimiento informado, ¿cuál de las siguientes NO forma parte de la información básica que debe recibir la persona paciente?","options":{"a":"La finalidad y los beneficios esperados de la intervención terapéutica.","b":"Las consecuencias relevantes o de importancia asociadas a la intervención.","c":"Los riesgos relacionados con las circunstancias personales o profesionales de la persona paciente.","d":"Los riesgos probables en condiciones normales, conforme a la experiencia del profesional que realizará el procedimiento."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":411,"text":"Según el Decreto 147/2015, sobre derechos y deberes de las personas en el sistema sanitario de Euskadi, ¿cuál de las siguientes afirmaciones es CORRECTA en relación con la negativa al tratamiento?","options":{"a":"La persona paciente puede negarse a cualquier tratamiento en todo caso, incluso cuando exista riesgo grave e inmediato para su vida.","b":"La negativa al tratamiento solo es válida si se formaliza siempre por escrito mediante consentimiento informado negativo.","c":"La persona paciente puede negarse al tratamiento, salvo en los supuestos previstos legalmente, aunque dicha negativa pueda ocasionar un perjuicio grave para su salud.","d":"La negativa al tratamiento queda anulada automáticamente cuando el profesional considera que la decisión no es beneficiosa para la persona paciente."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":412,"text":"Según el artículo 5 del Decreto 147/2015, relativo a los derechos de la persona paciente en la participación responsable en la gestión de su propia salud, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"La persona paciente tiene derecho a decidir unilateralmente la organización y priorización de los recursos sanitarios públicos que se le asignen, en función de sus preferencias personales.","b":"La persona paciente puede acceder a la información contenida en su historia clínica y obtener copia de la misma, conforme a los límites y garantías previstos en la normativa vigente.","c":"La persona paciente tiene derecho a recibir información comprensible sobre los recursos sanitarios y sociosanitarios disponibles para poder gestionar su salud con el mayor nivel de autonomía posible.","d":"La persona paciente tiene derecho a conocer la identidad, titulación y especialidad del profesional sanitario responsable de su diagnóstico y tratamiento."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":413,"text":"Según el artículo 6 del Decreto 147/2015, relativo a los derechos en relación con la organización y gestión del sistema sanitario de Euskadi, ¿cuál de las siguientes afirmaciones sobre los derechos lingüísticos de las personas usuarias es INCORRECTA?","options":{"a":"Las personas usuarias tienen derecho a que se garanticen sus derechos lingüísticos conforme a la normativa vigente sobre normalización del uso del euskera en el ámbito sanitario.","b":"El sistema sanitario debe posibilitar que la persona usuaria pueda relacionarse con los servicios sanitarios en cualquiera de las lenguas oficiales de la Comunidad Autónoma del País Vasco.","c":"El ejercicio de los derechos lingüísticos por parte de la persona usuaria queda condicionado a la disponibilidad inmediata de personal sanitario bilingüe en cada centro o servicio.","d":"Los derechos lingüísticos en el sistema sanitario se fundamentan en la legislación autonómica sobre normalización del euskera y en la normativa específica aplicable a las personas consumidoras y usuarias."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":414,"text":"Según el artículo 7 del Decreto 147/2015, relativo a los derechos en relación con las políticas sanitarias específicas, ¿cuál de los siguientes NO se considera un colectivo vulnerable conforme a los criterios establecidos en dicho artículo?","options":{"a":"Personas con trastorno mental.","b":"Personas con enfermedades raras de origen genético.","c":"Personas inmigrantes en situación administrativa irregular.","d":"Personas con discapacidad o diversidad funcional."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":415,"text":"De acuerdo con el artículo 12.2 del Decreto 147/2015, la posesión de la Tarjeta Individual Sanitaria en el Sistema Sanitario de Euskadi permite el ejercicio de determinadas facultades. ¿Cuál de las siguientes NO se corresponde con una facultad reconocida en dicho artículo?","options":{"a":"Obtención de una segunda opinión médica en procesos de enfermedad que conlleven riesgo para la vida o afecten gravemente a su calidad, en los términos previstos normativamente.","b":"Elección de profesional facultativo general y pediatra, así como de centro de atención primaria y, en su caso, del hospital correspondiente.","c":"Acceso a la asistencia sanitaria en un período de tiempo razonable, con garantía de plazo máximo de respuesta en los supuestos reglamentariamente establecidos.","d":"Elección del profesional de enfermería, fisioterapia o trabajo social en el marco de la organización asistencial del sistema sanitario de Euskadi."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":416,"text":"En relación con las funciones de los Servicios de Atención a Pacientes y Personas Usuarias del sistema sanitario de Euskadi, según el Decreto 147/2015, señale la afirmación CORRECTA:","options":{"a":"Los Servicios de Atención a Pacientes y Personas Usuarias pueden formular propuestas de mediación, pero la resolución de la reclamación corresponde siempre al órgano competente.","b":"La mediación llevada a cabo por estos servicios tiene carácter vinculante y sustituye la resolución administrativa cuando hay conformidad de la persona usuaria.","c":"Estos servicios pueden resolver reclamaciones cuando, tras un proceso de mediación, exista acuerdo entre las partes implicadas.","d":"Cuando una reclamación es susceptible de mediación, queda excluida su posterior resolución por la Administración sanitaria."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":417,"text":"En relación con la protección de datos de carácter personal en el ámbito sanitario y las consecuencias penales derivadas de su vulneración, señale la opción CORRECTA conforme a lo dispuesto en el artículo 199 del Código Penal:","options":{"a":"La revelación de datos de salud por parte de un profesional sanitario sin consentimiento únicamente conlleva responsabilidad administrativa, al tratarse de información obtenida en el ejercicio de una función pública.","b":"El profesional sanitario que divulga datos de salud incumpliendo su deber de secreto profesional puede ser castigado con pena de prisión y multa, además de inhabilitación especial para el ejercicio de su profesión.","c":"Solo existe responsabilidad penal cuando la revelación de datos se produce con ánimo de lucro o difusión pública masiva de la información.","d":"La divulgación de datos clínicos sin consentimiento constituye delito únicamente si el paciente demuestra un perjuicio económico directo derivado de dicha revelación."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":418,"text":"Según la Sociedad Española de Geriatría y Gerontología, ¿cuál de los siguientes términos describe cualquier procedimiento físico o mecánico dirigido a contener, sujetar o limitar el movimiento parcial o total del cuerpo y que no pueda ser manipulado por la persona?","options":{"a":"Restricción mecánica.","b":"Sujeción mecánica.","c":"Contención mecánica.","d":"Restricción física."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":419,"text":"De acuerdo con el algoritmo de actuación de la Guía de recomendaciones para la prevención y reducción del uso de contenciones en personas adultas durante la atención sanitaria de Osakidetza (2024), ¿en qué momento puede valorarse la aplicación de contención mecánica?","options":{"a":"Ante la presencia inicial de agitación psicomotriz, como medida preventiva para evitar riesgos potenciales.","b":"Cuando exista riesgo de daños inminentes, de forma simultánea a la valoración inicial de la persona atendida.","c":"Siempre que la persona atendida rechace las intervenciones de acompañamiento o distracción verbal.","d":"Tras constatar que las medidas previas no coercitivas han fracasado y persiste un riesgo de daño, con prescripción facultativa y consentimiento informado si procede."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":420,"text":"En el contexto de desescalada verbal para la prevención de la contención mecánica, ¿cuál de los siguientes dominios debería aplicarse antes de haber iniciado el contacto verbal con la persona atendida?","options":{"a":"Respetar espacio personal.","b":"Establecer límites claros.","c":"Escucha activa.","d":"Identificar deseos y sentimientos."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":421,"text":"Durante un turno de noche en una unidad de hospitalización, una paciente de 88 años, orientada y con capacidad de decisión conservada, rechaza de forma reiterada la colocación de una sonda vesical, pese a que el equipo considera que facilitaría el control clínico. Ante la insistencia del personal, la paciente vuelve a manifestar su negativa de forma expresa y comprensible. ¿Cuál es el principio bioético que se vería vulnerado si se procediera a la colocación de la sonda sin su consentimiento?","options":{"a":"Beneficencia.","b":"No maleficencia.","c":"Justicia.","d":"Autonomía."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":422,"text":"Una paciente de 83 años, ingresada en una unidad de agudos, presenta un episodio de agitación psicomotriz con riesgo inminente de caída. No consta documento de voluntades anticipadas y no es posible contactar con familiares en ese momento. El equipo decide aplicar una intervención inmediata para evitar daños graves. ¿Cuál es el fundamento ético que legitima esta actuación?","options":{"a":"El principio de autonomía.","b":"El principio de beneficencia.","c":"El principio de no maleficencia.","d":"El principio de justicia."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":423,"text":"Según el Código Deontológico de la profesión enfermera, ¿en cuál de los siguientes supuestos NO resulta de aplicación dicho Código?","options":{"a":"Una enfermera colegiada que ejerce su actividad profesional en un centro socio- sanitario en Donostia-San Sebastian.","b":"Una enfermera colegiada que presta servicios en el Hospital de Txagorritxu en Vitoria-Gasteiz.","c":"Una enfermera extranjera que, en virtud de un convenio internacional, ejerce ocasionalmente la profesión enfermera en el Hospital de Urduliz, Bizkaia.","d":"Una enfermera que, tras finalizar su contrato en Osakidetza hace un año, se ha trasladado a trabajar de forma estable a Edimburgo, Escocia."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":424,"text":"Una enfermera de atención primaria atiende a un paciente diagnosticado de una enfermedad transmisible de declaración obligatoria, que supone un riesgo grave para la salud pública. Durante la entrevista, el paciente manifiesta de forma explícita que no piensa seguir las recomendaciones sanitarias y que su intención es relacionarse con el mayor número posible de personas, siendo consciente del riesgo de contagio. Según el Código Deontológico de la profesión enfermera, ¿cuál debe ser la actuación correcta de la enfermera?","options":{"a":"Mantener el secreto profesional, ya que la confidencialidad solo puede romperse con el consentimiento expreso del paciente.","b":"Comunicar la situación a las autoridades competentes por motivos legales y de seguridad, limitando la información revelada al mínimo indispensable y al número estrictamente necesario de personas.","c":"Informar a todas las personas potencialmente expuestas para prevenir el contagio, aunque ello suponga revelar datos clínicos del paciente.","d":"Registrar la negativa del paciente en la historia clínica y respetar su decisión, al tratarse de un adulto competente."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":425,"text":"Según el Código Deontológico de la profesión enfermera, en relación con el medio ambiente y la salud comunitaria, ¿cuál de las siguientes afirmaciones es INCORRECTA?","options":{"a":"La participación de la enfermera en programas dirigidos a reducir la acción nociva de factores químicos, biológicos o físicos queda supeditada a la existencia de una orden expresa de la autoridad sanitaria competente.","b":"La enfermera tiene el deber de conocer, analizar y comunicar las consecuencias ecológicas de los contaminantes y sus efectos nocivos sobre la salud humana.","c":"La enfermera debe impartir educación para la salud ambiental con el objetivo de fomentar una conciencia sana de la comunidad respecto a los problemas del medio ambiente.","d":"La enfermera debe colaborar con las autoridades sanitarias en la planificación de actividades orientadas al control del medio ambiente y a la mejora de la atención a la salud comunitaria."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":426,"text":"En una unidad de hospitalización, una enfermera ante una elevada carga asistencial, decide pedir a un auxiliar de enfermería que administre una medicación intravenosa prescrita recientemente a un paciente, indicándole que ella estará disponible “por si surge algún problema”, ya que el auxiliar tiene experiencia en la unidad. De acuerdo con el Código Deontológico de la profesión enfermera, ¿cuál es la valoración CORRECTA de esta actuación?","options":{"a":"Es correcta, siempre que el auxiliar tenga experiencia previa y la enfermera permanezca localizable durante el procedimiento.","b":"Es incorrecta, ya que la enfermera no puede delegar funciones propias en otros profesionales que no estén debidamente capacitados, aunque exista supervisión.","c":"Es correcta si la enfermera ha informado previamente al auxiliar y ha comprobado que el paciente está estable.","d":"Es correcta si la decisión se justifica por una situación de sobrecarga asistencial y riesgo organizativo."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":427,"text":"Una enfermera con varios años de experiencia comienza a trabajar en una unidad donde se han incorporado nuevos procedimientos y tecnologías asistenciales. Ante algunas dudas técnicas, comenta que no ha recibido formación específica por parte del centro y que, hasta que no se la proporcionen, continuará aplicando los procedimientos “como siempre se han hecho”. De acuerdo con el Código Deontológico de la profesión enfermera, ¿quién tiene la responsabilidad principal de garantizar la actualización de los conocimientos necesarios para un ejercicio profesional seguro?","options":{"a":"La institución sanitaria, que debe proporcionar siempre formación previa antes de exigir cambios en la práctica clínica.","b":"La dirección de enfermería, que debe detectar las carencias formativas individuales y resolverlas.","c":"La propia enfermera, que debe identificar sus necesidades de aprendizaje y actuar de forma proactiva en su formación continua.","d":"El equipo multidisciplinar, que debe compensar las carencias formativas de sus miembros mediante el trabajo en grupo."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":428,"text":"En una unidad hospitalaria se incorporan estudiantes de Enfermería para realizar el prácticum. La supervisora asigna a cada estudiante una enfermera o enfermero de referencia. Una de las profesionales asignadas manifiesta su desacuerdo y afirma que no le corresponde supervisar ni enseñar, ya que en su salario no recibe compensación económica específica por ello. De acuerdo con el Código Deontológico de la profesión enfermera, ¿cuál de las siguientes actuaciones es la más adecuada?","options":{"a":"Recordar que la enfermera o el enfermero tiene la responsabilidad individual y colectiva de asumir la educación en Enfermería a todos sus niveles, incluida la supervisión del estudiantado en prácticas.","b":"Reasignar al estudiantado exclusivamente a la supervisora o a personal docente externo, evitando la implicación del personal asistencial.","c":"Aceptar la negativa de la profesional, ya que la actividad docente solo es exigible si existe reconocimiento económico expreso.","d":"Limitar la supervisión a la observación pasiva, evitando implicación formativa directa para no interferir en la carga asistencial."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":429,"text":"¿Qué modelo guía la estructura y contenido de la segunda edición de la Herramienta de Implantación de guías de buenas prácticas de RNAO?","options":{"a":"Modelo de Mejora Continua.","b":"Marco de Conocimiento para la Acción.","c":"Ciclo de Deming.","d":"Modelo de Rogers."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":430,"text":"¿Qué instrumento se recomienda utilizar para evaluar la calidad de una guía de buenas prácticas antes de su implantación?","options":{"a":"AGREE II.","b":"PRISMA.","c":"CONSORT.","d":"GRADE."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":431,"text":"¿Qué se considera una parte interesada (stakeholder) según la “Herramienta de implantación de buenas prácticas”?","options":{"a":"Únicamente los pacientes.","b":"Únicamente los profesionales de salud.","c":"Individuos, grupos o instituciones con interés directo en la implantación de la guía.","d":"Únicamente los financiadores del proyecto"},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":432,"text":"¿Qué fase del Marco de Conocimiento para la Acción se enfoca en la identificación de las partes interesadas?","options":{"a":"Identificación del problema.","b":"Evaluación de facilitadores y barrera.","c":"Monitorización del uso del conocimiento.","d":"Adaptación al contexto local."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":433,"text":"Según la “Herramienta de implantación de buenas prácticas”, ¿qué se incluye en la definición de \"auditoría y feedback\"?","options":{"a":"Una revisión de la literatura científica.","b":"Una encuesta de satisfacción del paciente.","c":"Un resumen del desempeño clínico que puede incluir recomendaciones para la acción.","d":"La observación directa del paciente."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":434,"text":"¿Cuál de los siguientes no es un criterio para seleccionar indicadores para monitorizar el progreso de la sostenibilidad en la institución?","options":{"a":"Validez interna.","b":"Viabilidad.","c":"Claridad y capacidad de ser entendido por los usuarios.","d":"Relevancia."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":435,"text":"¿Qué iniciativa de RNAO permite la recogida de datos y medición de indicadores estructurales, de proceso y de resultado relacionados con cada Guía de Buena Practica?","options":{"a":"AGREE II.","b":"BPSO.","c":"ADAPTE.","d":"NQuIRE."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":436,"text":"¿Qué se recomienda al involucrar a las partes interesadas con alta influencia, pero bajo apoyo?","options":{"a":"Darles mucha atención para intentar conseguir su apoyo.","b":"Ignorarlas, ya que no apoyan.","c":"Excluirlas del proceso.","d":"Solo informarles al final del proyecto."},"correct":"a","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":437,"text":"La implantación efectiva de las Guías de Buenas Practicas, puede alcanzar como objetivo:","options":{"a":"Mantener la base de conocimientos en enfermería.","b":"Aportar el nivel de carencias financieras en la investigación.","c":"Trasladar a la investigación la evidencia fruto de la práctica.","d":"Reducir la variabilidad en los cuidados."},"correct":"d","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":438,"text":"¿Qué tipo de recurso se define como \"formas de apoyo no monetarias, como el acceso a bienes y servicios\"?","options":{"a":"Recursos financieros.","b":"Recursos humanos.","c":"Recursos en especie.","d":"Recursos tecnológicos."},"correct":"c","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":439,"text":"Los indicadores potenciales de la categoría de Proceso, se asocian a:","options":{"a":"Qué ocurre.","b":"Cómo lo va a hacer.","c":"Qué necesitas tener.","d":"Qué vamos a hacer."},"correct":"b","disputed":false,"topic":"Técnicas y Procedimientos Enfermeros"},{"num":440,"text":"¿Cuál es uno de los factores clave que influyen como facilitador en la implantación de una guía de buenas prácticas?","options":{"a":"Actitudes y creencias políticas del personal.","b":"Apoyo del liderazgo.","c":"Grupo de interrelación.","d":"Integración limitada de las recomendaciones de la guía en los procesos y estructuras institucionales."},"correct":"b","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":441,"text":"En relación con las diferencias entre los enfoques cuantitativo y cualitativo en investigación en enfermería, señale la afirmación CORRECTA:","options":{"a":"El enfoque cuantitativo parte de la idea de que la realidad es construida socialmente y depende de la interpretación de los sujetos que participan en el estudio.","b":"El enfoque cualitativo se apoya fundamentalmente en marcos positivistas y busca medir variables objetivas mediante instrumentos estandarizados.","c":"El enfoque cuantitativo asume la existencia de una realidad objetiva, externa al investigador, que puede conocerse y medirse.","d":"El enfoque cualitativo pretende generalizar los resultados a grandes poblaciones mediante el análisis estadístico inferencial."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":442,"text":"Una enfermera investigadora quiere explorar cómo viven las personas con insuficiencia cardíaca avanzada la educación terapéutica recibida durante el ingreso hospitalario, con el objetivo de comprender sus percepciones, significados y experiencias. Para ello diseña un estudio cualitativo basado en entrevistas en profundidad. ¿Cuál sería la estrategia de muestreo más adecuada para este tipo de estudio?","options":{"a":"Seleccionar a las personas participantes mediante un muestreo aleatorio estratificado según edad y sexo.","b":"Incluir de forma intencional a personas que aporten información relevante, incorporando nuevas entrevistas hasta alcanzar la saturación teórica.","c":"Elegir a las personas participantes mediante muestreo por conglomerados según unidades de hospitalización.","d":"Seleccionar sistemáticamente a cada quinto paciente ingresado en la unidad durante el periodo de estudio."},"correct":"b","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":443,"text":"En un diseño de investigación descriptivo-correlacional, ¿qué se analiza principalmente?","options":{"a":"Efectos causales de una intervención.","b":"Asociaciones entre variables.","c":"Diferencias entre grupos experimentales.","d":"Evolución temporal de una cohorte."},"correct":"b","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":444,"text":"En análisis cualitativo, ¿qué representa el proceso de triangulación?","options":{"a":"Uso exclusivo de tres investigadores.","b":"Muestreo en tres fases sucesivas.","c":"Análisis estadístico tridimensional.","d":"Convergencia de múltiples fuentes metodológicas."},"correct":"d","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":445,"text":"En la fase empírica, ¿cuál es la técnica cuantitativa MÁS adecuada para medir satisfacción con cuidados?","options":{"a":"Análisis de contenido temático.","b":"Observación participante no estructurada.","c":"Cuestionario validado con escala Likert.","d":"Entrevista narrativa libre."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":446,"text":"¿Qué validez es MÁS crítica en la fase de diseño de instrumentos de medida?","options":{"a":"Validez de constructo y contenido.","b":"Validez estadística post-hoc.","c":"Validez de difusión mediática.","d":"Validez temporal retrospectiva."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":447,"text":"Una enfermera investigadora quiere explorar las experiencias y percepciones de pacientes hospitalizados sobre la calidad de los cuidados recibidos tras una cirugía mayor. Para ello, decide utilizar técnicas propias de la investigación cualitativa. ¿Cuál de las siguientes NO sería una técnica cualitativa de recogida de datos adecuada para este estudio?","options":{"a":"Entrevistas semiestructuradas a pacientes durante el ingreso.","b":"Grupos focales con personas dadas de alta recientemente.","c":"Encuestas estructuradas con preguntas cerradas.","d":"Observación participante sistemática del proceso de cuidados en la unidad."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":448,"text":"Una enfermera investigadora realiza un estudio cualitativo basado en entrevistas en profundidad a personas cuidadoras informales, con el objetivo de analizar discursos, categorías y relaciones entre significados. Para el análisis cualitativo de los datos, revisa distintos programas informáticos. ¿Cuál de los siguientes NO es un programa adecuado para el análisis cualitativo de datos?","options":{"a":"SPSS.","b":"ATLAS.ti.","c":"Ethnograph.","d":"NVivo."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":449,"text":"Un equipo de enfermería quiere investigar el cuidado de personas con demencia y el impacto en sus familiares cuidadores, con el objetivo de mejorar la atención y el apoyo desde los servicios sociosanitarios. El equipo analiza entrevistas y diarios de campo de familiares cuidadores y profesionales, aplicando codificación abierta, axial y selectiva, con comparación constante de datos, para desarrollar un modelo explicativo sobre cómo evolucionan las estrategias de cuidado familiar a lo largo del curso de la demencia. ¿A qué método cualitativo corresponde principalmente este enfoque?","options":{"a":"Teoría fundamentada.","b":"Etnografía.","c":"Fenomenología.","d":"Investigación-acción participativa."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":450,"text":"Un equipo de enfermería quiere investigar el cuidado de personas con demencia y el impacto en sus familiares cuidadores, con el objetivo de mejorar la atención y el apoyo desde los servicios sociosanitarios. El equipo diseña el estudio junto con familiares y personas con demencia en fases iniciales, quienes codiseñan intervenciones, participan en la toma de decisiones y evalúan los cambios introducidos en los apoyos comunitarios, con el objetivo explícito de transformar la práctica. ¿A qué método cualitativo corresponde principalmente este enfoque?","options":{"a":"Teoría fundamentada.","b":"Etnografía.","c":"Fenomenología.","d":"Investigación-acción participativa."},"correct":"d","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":451,"text":"Un equipo de enfermería quiere investigar el cuidado de personas con demencia y el impacto en sus familiares cuidadores, con el objetivo de mejorar la atención y el apoyo desde los servicios sociosanitarios. Las investigadoras se integran durante un año en centros de día, domicilios y asociaciones de familiares, observando rituales, normas implícitas, roles, lenguaje y prácticas compartidas en torno al cuidado de personas con demencia, con el fin de comprender la cultura del cuidado en distintos contextos comunitarios. ¿A qué método cualitativo corresponde principalmente este enfoque?","options":{"a":"Teoría fundamentada.","b":"Etnografía.","c":"Fenomenología.","d":"Investigación-acción participativa."},"correct":"b","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":452,"text":"Un equipo de enfermería quiere investigar el cuidado de personas con demencia y el impacto en sus familiares cuidadores, con el objetivo de mejorar la atención y el apoyo desde los servicios sociosanitarios. El estudio se focaliza en cómo los familiares viven y significan el cuidado cotidiano de una persona con demencia, explorando en profundidad emociones, percepciones y sentido del cuidado. ¿A qué método cualitativo corresponde principalmente este enfoque?","options":{"a":"Teoría fundamentada.","b":"Etnografía.","c":"Fenomenología.","d":"Investigación-acción participativa."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":453,"text":"En relación con el modelo de práctica basada en la evidencia (PBE) en enfermería, ¿cuál de los siguientes NO forma parte de los factores que influyen en dicho modelo?","options":{"a":"La mejor evidencia disponible procedente de la investigación científica.","b":"La experiencia clínica del profesional de enfermería.","c":"Las circunstancias, valores y preferencias de la persona paciente.","d":"La disponibilidad presupuestaria y la eficiencia económica del sistema sanitario."},"correct":"d","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":454,"text":"Una unidad de enfermería detecta una elevada tasa de úlceras por presión en pacientes inmovilizados. El equipo enfermero diseña un estudio para analizar la incidencia, identificar factores asociados y valorar la efectividad de diferentes intervenciones preventivas, con el objetivo de mejorar los cuidados y la seguridad del paciente. Desde el punto de vista conceptual, esta actuación se corresponde principalmente con:","options":{"a":"Una auditoría asistencial orientada al control interno de la calidad.","b":"La aplicación directa de la Guía BPSO de prevención de úlceras por presión.","c":"Un proceso de investigación en enfermería destinado a generar y validar conocimiento aplicable a la práctica clínica.","d":"Un programa de formación continuada sin relación con la producción de conocimiento científico."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":455,"text":"En relación con las formas de adquisición del conocimiento en enfermería, señale la opción CORRECTA:","options":{"a":"El modelado de roles permite la adquisición de conocimientos mediante la observación e imitación de profesionales expertos, siendo una estrategia clave en la formación práctica en enfermería.","b":"La experiencia personal constituye una fuente suficiente de conocimiento para la práctica enfermera, incluso en ausencia de evidencia científica.","c":"El conocimiento adquirido por tradición garantiza prácticas eficaces, ya que ha demostrado su validez al mantenerse estable a lo largo del tiempo.","d":"La intuición es una forma de conocimiento espontáneo sin base cognitiva ni relación con la experiencia clínica acumulada."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":456,"text":"En relación con la asociación entre la formación académica de los y las profesionales de enfermería y las expectativas y competencias en investigación, señale la opción INCORRECTA:","options":{"a":"En las enfermeras y enfermeros con formación de grado, no se espera ninguna implicación en actividades de investigación, lectura o valoración crítica de los estudios de investigación, limitándose su papel a la aplicación directa de cuidados asistenciales.","b":"En profesionales con formación de máster, se incluyen competencias relacionadas con la valoración crítica y síntesis de la evidencia, así como la elaboración y revisión de protocolos y guías clínicas.","c":"En profesionales con formación doctoral, se espera la generación de conocimiento científico mediante la realización de investigaciones originales y la colaboración en proyectos de investigación.","d":"En profesionales con formación postdoctoral, se asume un papel de liderazgo en investigación, incluyendo la dirección de proyectos, la obtención de financiación y la tutorización de investigadores con grado doctoral."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":457,"text":"Un equipo de enfermería quiere comprender en profundidad la experiencia vivida por personas cuidadoras informales de pacientes con demencia avanzada en domicilio, con el objetivo de identificar significados, percepciones y necesidades comunes que orienten futuras intervenciones de apoyo. Para responder a esta pregunta de investigación, ¿cuál es el proceso de síntesis de la evidencia más adecuado?","options":{"a":"Metaanálisis, utilizando métodos estadísticos para estimar el efecto global del cuidado informal sobre la carga del cuidador.","b":"Metasíntesis, integrando de forma sistemática estudios cualitativos originales para desarrollar una interpretación comprensiva de los hallazgos.","c":"Revisión sistemática, combinando estudios cuantitativos y cualitativos mediante análisis estadístico.","d":"Revisión sistemática de métodos mixtos, centrada en estudios experimentales y cuasiexperimentales con análisis estadístico."},"correct":"b","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":458,"text":"Un grupo de enfermeras quiere actualizar un protocolo clínico sobre prevención de caídas y decide basar sus recomendaciones en el nivel más alto de evidencia científica disponible, según la pirámide de niveles de evidencia en investigación en enfermería. ¿En cuál de los siguientes niveles de evidencia se situaría la fuente más adecuada para este objetivo?","options":{"a":"Nivel I: Revisión sistemática y metaanálisis.","b":"Nivel II: Ensayo controlado aleatorizado (ECA) o estudio experimental.","c":"Nivel III: Estudios cuasiexperimentales","d":"Nivel IV: Revisión sistemática de métodos mixtos y metasíntesis."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":459,"text":"Una enfermera participa en un estudio experimental con modelos animales cuyo objetivo es comprender los mecanismos celulares implicados en la pérdida de masa muscular asociada al envejecimiento, sin aplicación directa e inmediata en la práctica asistencial. ¿A qué tipo de investigación corresponde este estudio?","options":{"a":"Investigación aplicada.","b":"Investigación básica.","c":"Investigación traslacional.","d":"Investigación evaluativa clínica."},"correct":"b","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":460,"text":"Durante la valoración crítica de un estudio de investigación en enfermería, tanto cuantitativo como cualitativo, la enfermera revisora debe aplicar una serie de principios clave para determinar la calidad y utilidad del estudio. ¿Cuál de los siguientes NO constituye un principio clave de la valoración crítica según las guías metodológicas en investigación en enfermería?","options":{"a":"Analizar la relevancia del problema estudiado para la práctica enfermera y su contribución a la práctica basada en la evidencia.","b":"Identificar los puntos fuertes y débiles del estudio, siendo objetivo y realista en su valoración.","c":"Evaluar la calidad del estudio y la coherencia de sus hallazgos con la literatura existente.","d":"Determinar si los resultados del estudio confirman la hipótesis del autor y descartar el estudio si no lo hacen."},"correct":"d","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":461,"text":"En el contexto de la práctica basada en la evidencia en enfermería, se utilizan diferentes bases de datos y recursos bibliográficos para localizar estudios científicos. ¿Cuál de los siguientes recursos es el que cubre de forma más específica y amplia la literatura de revistas internacionales del ámbito de la enfermería?","options":{"a":"CINAHL.","b":"MEDLINE (PubMed).","c":"PsycINFO.","d":"Biblioteca Cochrane."},"correct":"a","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":462,"text":"En una unidad de atención primaria se plantea revisar la evidencia disponible sobre la administración de inyecciones intramusculares en población adulta, con el objetivo de reducir complicaciones locales asociadas a la técnica. Para ello, el equipo formula una pregunta clínica utilizando el formato PICO. ¿Cuál de los siguientes elementos del PICO está incorrectamente formulado en relación con este escenario?","options":{"a":"P: Personas adultas que reciben inyecciones intramusculares en el ámbito asistencial.","b":"I: Administración de la inyección intramuscular sin aspiración, siguiendo la localización anatómica correcta.","c":"C: Administración de la inyección intramuscular con aspiración previa durante varios segundos, independientemente del lugar de punción.","d":"O: Grado de conocimiento del personal de enfermería sobre la técnica de inyección intramuscular."},"correct":"d","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":463,"text":"Un equipo de enfermería de un hospital comarcal de Osakidetza decide implantar la práctica basada en la evidencia (PBE) de forma estructurada para mejorar la calidad y seguridad de los cuidados. Para ello, revisan distintos modelos teóricos que guían la implementación de la PBE en la práctica clínica. ¿Cuál de los siguientes NO corresponde a un modelo o programa reconocido de práctica basada en la evidencia en enfermería?","options":{"a":"Modelo de Stetler para la implementación de la práctica basada en la evidencia.","b":"Modelo de Iowa para la práctica basada en la evidencia.","c":"Modelo Integrado de Transferencia Clínica Basada en Resultados Asistenciales (MITC-BRA).","d":"Programa Best Practice Spotlight Organization (BPSO)."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":464,"text":"Un grupo de enfermeras participa en un proyecto de investigación que parte de hallazgos obtenidos en estudios básicos sobre la respuesta inflamatoria al dolor postoperatorio. A partir de estos resultados, se diseña una intervención de cuidados enfermeros, se prueba en una unidad hospitalaria concreta y posteriormente se ajusta para su implantación progresiva en la práctica clínica, evaluando resultados en pacientes reales. ¿A qué tipo de investigación corresponde principalmente este enfoque?","options":{"a":"Investigación básica.","b":"Investigación aplicada.","c":"Investigación translacional.","d":"Investigación clínica descriptiva."},"correct":"c","disputed":false,"topic":"Investigación Enfermera y Metodología"},{"num":465,"text":"Se realiza un estudio sobre la presión arterial sistólica en una muestra de 200 pacientes. Los datos siguen una distribución normal con media de 130 mmHg y desviación estándar de 15 mmHg. ¿Qué característica define a una distribución normal?","options":{"a":"Es asimétrica y presenta una cola derecha más prolongada.","b":"Es simétrica alrededor de la media y tiene forma de campana.","c":"Todos los valores tienen la misma frecuencia.","d":"La media es siempre mayor que la mediana."},"correct":"b","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":466,"text":"En un estudio observacional sobre tiempos de espera en urgencias, se obtienen los siguientes datos (en minutos): 5, 7, 10, 12, 15, 20, 120. ¿Cuál de las siguientes afirmaciones sobre las medidas de tendencia central es CORRECTA?","options":{"a":"La media es la medida más representativa del tiempo típico de espera.","b":"La moda es 120 minutos, coincidiendo con el valor más alto.","c":"La mediana es 12 minutos y refleja mejor el tiempo central sin influencia de valores atípicos.","d":"La media y la mediana son idénticas, por lo que ambas son igualmente válidas."},"correct":"c","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":467,"text":"¿Cuál de los siguientes parámetros indica la dispersión o variabilidad de los datos alrededor de la media en una distribución?","options":{"a":"La dispersión variable.","b":"El rango intercuartílico.","c":"La correlación de Pearson.","d":"La desviación estándar y la varianza."},"correct":"d","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":468,"text":"¿Qué representa el intervalo de confianza al 95% en una investigación?","options":{"a":"Que existe un 95% de probabilidad de que la media muestral se encuentre en ese rango.","b":"Que si repitiéramos el estudio 100 veces, aproximadamente en 95 ocasiones el parámetro poblacional estaría dentro del intervalo calculado.","c":"Que el 95% de los datos se encuentran en ese intervalo.","d":"Que el 5% de los datos son erróneos."},"correct":"b","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":469,"text":"En un ensayo clínico que contrasta la hipótesis de que una intervención educativa mejora la adherencia al tratamiento antihipertensivo (H₀: la intervención no mejora la adherencia; H₁: la intervención sí la mejora), ¿qué significa rechazar la hipótesis nula?","options":{"a":"Que la hipótesis nula es absolutamente cierta.","b":"Que se asume que la hipótesis alternativa es verdadera basándose en la evidencia obtenida.","c":"Que existe suficiente evidencia estadística para asumir que la hipótesis alternativa es verdadera.","d":"Que el estudio fue realizado incorrectamente."},"correct":"c","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":470,"text":"En una investigación se obtiene un valor de p = 0,03 al comparar dos métodos de cuidado de heridas. Si se fija un nivel de significación α = 0,05, ¿qué conclusión es CORRECTA?","options":{"a":"No hay diferencias significativas entre los métodos.","b":"Hay diferencias estadísticamente significativas entre los métodos.","c":"El resultado no es clínicamente significativo.","d":"Necesariamente uno de los métodos es mejor que el otro en la práctica."},"correct":"b","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":471,"text":"Un investigador desea comparar la media de glucosa en sangre entre dos grupos de pacientes diabéticos (grupo control y grupo intervención) en un estudio con muestras pequeñas (n = 15 en cada grupo). ¿Cuál es el test estadístico más apropiado?","options":{"a":"ANOVA.","b":"Chi cuadrado.","c":"Test t de Student para muestras independientes.","d":"Correlación de Pearson."},"correct":"c","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":472,"text":"En un estudio sobre la incidencia de infecciones nosocomiales, se clasificó a 250 pacientes según el tipo de infección (respiratoria, urinaria, herida quirúrgica) y la unidad hospitalaria (UCI, planta, ambulatorio). ¿Cuál es el test más apropiado para determinar si existe asociación entre estas dos variables categóricas?","options":{"a":"Test de chi cuadrado (χ²).","b":"Test t de Student.","c":"ANOVA.","d":"Test de Mann-Whitney."},"correct":"a","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":473,"text":"En una investigación sobre la satisfacción de pacientes con la atención de enfermería (escala Likert 1-5), los datos NO siguen una distribución normal. ¿Cuál de los siguientes tests sería el más apropiado para comparar la satisfacción entre dos grupos?","options":{"a":"Test de Mann-Whitney (prueba NO paramétrica).","b":"ANOVA.","c":"Test t de Student.","d":"Test de correlación de Pearson."},"correct":"a","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":474,"text":"¿Cuál de las siguientes afirmaciones sobre el tamaño muestral es CORRECTA?","options":{"a":"Un tamaño muestral mayor siempre garantiza resultados estadísticamente significativos.","b":"El tamaño muestral no influye en la amplitud del intervalo de confianza.","c":"El tamaño muestral solo es importante en estudios cualitativos.","d":"Un tamaño muestral mayor reduce el error estándar y hace más precisa la estimación del parámetro poblacional."},"correct":"d","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":475,"text":"En una muestra de 80 pacientes con insuficiencia cardíaca se registra la cantidad de ingresos hospitalarios en el último año (variable de recuento). La distribución es muy asimétrica a la derecha, con pocos pacientes que han tenido muchos ingresos. ¿Qué medida de dispersión es más adecuada para acompañar a la mediana al describir esta variable?","options":{"a":"Desviación estándar.","b":"Varianza.","c":"Coeficiente de variación.","d":"Rango intercuartílico."},"correct":"d","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":476,"text":"En un estudio de enfermería sobre niveles de ansiedad (escala cuantitativa) se obtienen los siguientes resultados: media 30 puntos, desviación estándar 5 puntos. Asumiendo distribución aproximadamente normal, ¿qué porcentaje aproximado de pacientes se espera que tenga niveles de ansiedad entre 25 y 35 puntos?","options":{"a":"Alrededor del 50 %","b":"Alrededor del 68 %","c":"Alrededor del 95 %","d":"Alrededor del 99 %"},"correct":"b","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":477,"text":"Según la Guía-Manual: Uso adecuado de los guantes sanitarios, ¿qué tipo de guantes se deben utilizar para la aspiración de secreciones en la Unidad de Cuidados Intensivos?","options":{"a":"No estériles de látex.","b":"No estériles de polímero.","c":"Estériles de vinilo.","d":"Estériles de nitrilo."},"correct":"d","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":478,"text":"NO es una recomendación en el uso de guantes:","options":{"a":"Los guantes deben ser utilizados cuando sea necesario y el tiempo imprescindible ya que el abuso de empleo de los mismos confiere falsa seguridad y aumenta la contaminación cruzada.","b":"Las manos deben lavarse o descontaminarse antes de usar guantes, después no es necesario y estos no deben ser lavados ni reutilizados.","c":"Se deben utilizar siempre que el profesional sanitario presente cortes, heridas o lesiones cutáneas.","d":"Tener las manos libres de objetos como anillos, relojes, etc. porque pueden romper el guante, sin cremas, con las uñas cortas y sin esmalte, para facilitar una buena limpieza de material potencialmente infeccioso."},"correct":"b","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":479,"text":"¿Cuál es el objetivo general de la Estrategia de Seguridad del Paciente 2021– 2030?","options":{"a":"Eliminar completamente los errores sanitarios.","b":"Minimizar los riesgos y daños evitables asociados a la atención sanitaria.","c":"Aumentar la eficiencia económica del sistema sanitario.","d":"Incrementar la satisfacción profesional del personal sanitario."},"correct":"b","disputed":false,"topic":"Estadística y Evidencia Científica"},{"num":480,"text":"Un evento adverso se define como:","options":{"a":"Un error profesional sin consecuencias.","b":"Un incidente que no produce daño.","c":"Un daño no intencionado relacionado con la asistencia sanitaria.","d":"Una complicación inevitable de la enfermedad."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":481,"text":"Las infecciones relacionadas con la asistencia sanitaria (IRAS) se caracterizan por:","options":{"a":"Aparecer durante o después de la atención sanitaria.","b":"Estar presentes siempre al ingreso.","c":"Ser inevitables.","d":"No estar relacionadas con procedimientos."},"correct":"a","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":482,"text":"El aislamiento por contacto está especialmente indicado en pacientes con:","options":{"a":"Infecciones por vía aérea.","b":"Neutropenia grave.","c":"Infecciones transmitidas por gotas.","d":"Microorganismos multirresistentes."},"correct":"d","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":483,"text":"En seguridad, ¿A quién nos referimos con el termino segundas víctimas?","options":{"a":"A la propia organización sanitaria en la que ha tenido lugar el evento adverso.","b":"Al entorno más cercano del paciente que queda traumatizado por el evento adverso.","c":"Al profesional que participa en un evento adverso y que queda traumatizado por esta experiencia.","d":"A los pacientes, constituyendo una experiencia traumática para ellos."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":484,"text":"La notificación de incidentes de seguridad debe ser:","options":{"a":"Obligatoria y punitiva.","b":"Obligatoria y punitiva, para cualquier evento adverso.","c":"Voluntaria y no punitiva, solo para eventos adversos con daño.","d":"Voluntaria y no punitiva."},"correct":"d","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":485,"text":"Las intervenciones eficaces en prevención de caídas deben ser:","options":{"a":"Estándar para todos.","b":"Restrictivas de la movilidad.","c":"Individualizadas y multifactoriales.","d":"Farmacológicas."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":486,"text":"En pacientes institucionalizados con alto riesgo de caídas se puede considerar:","options":{"a":"Administrar vitamina D.","b":"Uso de sujeciones.","c":"Reposo absoluto.","d":"Barandillas sistemáticas."},"correct":"a","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":487,"text":"La prevención de caídas NO debe basarse en:","options":{"a":"Información al paciente.","b":"Uso sistemático de sujeciones.","c":"Participación activa del paciente.","d":"Intervenciones personalizadas."},"correct":"b","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":488,"text":"¿Cuál es un factor de riesgo intrínseco de caídas?","options":{"a":"Suelo mojado.","b":"Alteración del equilibrio.","c":"Mala iluminación.","d":"Barreras arquitectónicas."},"correct":"b","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":489,"text":"¿Cómo se define la violencia sexual según la Organización Mundial de la Salud?","options":{"a":"Todo acto sexual no consentido ejercido únicamente por la pareja.","b":"Cualquier acto sexual ejercido mediante coacción, independientemente de la relación con la víctima.","c":"Únicamente los actos sexuales con penetración forzada por vía vaginal o anal.","d":"Aquel acto sexual dirigido contra la sexualidad de una persona, ejercido exclusivamente en el ámbito privado."},"correct":"b","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":490,"text":"Según la Ley Orgánica 10/2022, ¿qué conductas se consideran violencias sexuales?","options":{"a":"Actos sexuales no consentidos que condicionan el libre desarrollo de la vida sexual.","b":"La agresión sexual, el acoso sexual y la explotación de la prostitución propia.","c":"La agresión sexual y el abuso sexual, existiendo distinción entre ambos conceptos.","d":"Solo la agresión y abuso sexual con violencia física."},"correct":"a","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":491,"text":"Actualmente, la edad del consentimiento sexual en España es de:","options":{"a":"15 años.","b":"16 años.","c":"17 años.","d":"18 años."},"correct":"b","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":492,"text":"En la actuación ante las agresiones sexuales es necesaria la coordinación interinstitucional. Por ello, cuando una mujer acude al hospital declarando una agresión sexual,","options":{"a":"Desde el Hospital se pondrá en conocimiento del Juzgado de guardia y se avisará también a la Policía Local en caso de existir intención de interponer una denuncia por parte de la mujer.","b":"Desde el Hospital se pondrá en conocimiento del Juzgado de guardia y en caso de querer interponer una denuncia la mujer deberá en cualquier caso desplazarse al Juzgado o Comisaria.","c":"Desde el Hospital se pondrá en conocimiento del Juzgado de guardia independientemente de que la mujer haya interpuesto o no una denuncia.","d":"Desde el Hospital se pondrá en conocimiento del Juzgado de guardia la situación únicamente en caso de existir intención de interponer una denuncia por parte de la mujer."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":493,"text":"El intervalo de tiempo para considerar reciente una agresión sexual con penetración vaginal es:","options":{"a":"≤ 72 horas.","b":"≤ 5 días.","c":"≤ 10 días.","d":"≤ 15 días."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":494,"text":"¿Dónde debe realizarse la valoración de una paciente con sospecha de agresión sexual reciente cuya situación de gravedad no obligue a un tratamiento médico inmediato?","options":{"a":"En el Juzgado de guardia.","b":"En el domicilio de la víctima.","c":"En un centro de Atención Primaria.","d":"En un centro hospitalario."},"correct":"d","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":495,"text":"¿Está condicionada la recogida de muestras biológicas a la presentación de una denuncia por agresión sexual?","options":{"a":"Sí, en cualquier caso.","b":"Solo en mayores de edad.","c":"No, en ningún caso.","d":"Únicamente si lo autoriza el Juez o Jueza de guardia."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":496,"text":"¿Cuál es el orden correcto de recogida de muestras en una agresión sexual para evitar la contaminación de una zona a otra?","options":{"a":"Vulva, vagina, cérvix, región anal.","b":"Región anal, vulva, vagina, cérvix.","c":"Región anal, vagina, cérvix, vulva.","d":"Vulva, región anal, vagina, cérvix."},"correct":"b","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":497,"text":"¿Cuáles son los tres niveles de actuación del Sistema Sanitario frente a la violencia de género?","options":{"a":"Prevención primaria, secundaria y terciaria.","b":"Diagnóstico, tratamiento y seguimiento.","c":"Atención primaria, hospitalaria y urgente.","d":"Atención médica, jurídica y social."},"correct":"a","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":498,"text":"¿En relación a la violencia de género, cuál de los siguientes grupos NO se considera de especial vulnerabilidad?","options":{"a":"Trastorno mental leve.","b":"Residentes en municipios pequeños.","c":"Envejecimiento.","d":"Diversidad funcional."},"correct":"a","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":499,"text":"En la fase de precontemplación de la violencia de género, según el modelo de Prochaska y DiClemente, el objetivo principal es:","options":{"a":"Acompañar a la mujer para ayudar a determinar el mejor plan a seguir para poder introducir algunos cambios.","b":"Fomentar la duda sobre la aceptabilidad del maltrato.","c":"Aumentar la toma de conciencia y solucionar la incertidumbre a favor de establecer cambios.","d":"Acompañar a la mujer en sus acciones de cambio para que no se sienta sola y ayudarle a reafirmar su proceso."},"correct":"b","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"},{"num":500,"text":"¿Cuál de las siguientes actuaciones NO debe realizar el personal de Enfermería en la atención a mujeres en situación de violencia de género?","options":{"a":"Hacer una clara valoración del riesgo y asegurar un clima de confianza.","b":"Registrar la situación de violencia en la historia clínica y valorar, de forma individualizada, la necesidad de comunicación judicial en función del riesgo y del momento vital de la mujer.","c":"Proponer a la mujer la realización de terapia de pareja o mediación familiar, interpretando la violencia como un conflicto relacional.","d":"Priorizar la intervención inicial básica y posponer derivaciones hasta consensuarlas con la mujer, garantizando confidencialidad y continuidad asistencial."},"correct":"c","disputed":false,"topic":"Seguridad del Paciente y Calidad Asistencial"}];

